#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum BfvRefreshTranscriptMode {
    Exact,
    BoundedNoise,
}

impl BfvRefreshTranscriptMode {
    fn rotation_seed_label(self) -> &'static str {
        match self {
            Self::Exact => "rotation refresh transcript seed",
            Self::BoundedNoise => "bounded-noise rotation refresh transcript seed",
        }
    }

    fn bootstrap_seed_label(self) -> &'static str {
        match self {
            Self::Exact => "bootstrap refresh transcript seed",
            Self::BoundedNoise => "bounded-noise bootstrap refresh transcript seed",
        }
    }

    fn digest_domain(self) -> &'static [u8] {
        match self {
            Self::Exact => BFV_REFRESH_TRANSCRIPT_DIGEST_DOMAIN,
            Self::BoundedNoise => BFV_BOUNDED_NOISE_REFRESH_TRANSCRIPT_DIGEST_DOMAIN,
        }
    }

    fn public_key_proof_statement_domain(self) -> &'static [u8] {
        match self {
            Self::Exact => BFV_PUBLIC_KEY_PROOF_STATEMENT_DOMAIN,
            Self::BoundedNoise => BFV_BOUNDED_NOISE_PUBLIC_KEY_PROOF_STATEMENT_DOMAIN,
        }
    }

    fn ciphertext_proof_statement_domain(self) -> &'static [u8] {
        match self {
            Self::Exact => BFV_CIPHERTEXT_PROOF_STATEMENT_DOMAIN,
            Self::BoundedNoise => BFV_BOUNDED_NOISE_CIPHERTEXT_PROOF_STATEMENT_DOMAIN,
        }
    }

    fn bootstrap_key_proof_statement_domain(self) -> &'static [u8] {
        match self {
            Self::Exact => BFV_BOOTSTRAP_KEY_ZERO_REFRESH_PROOF_STATEMENT_DOMAIN,
            Self::BoundedNoise => {
                BFV_BOUNDED_NOISE_BOOTSTRAP_KEY_ZERO_REFRESH_PROOF_STATEMENT_DOMAIN
            }
        }
    }

    fn bootstrap_key_transcript_proof_statement_domain(self) -> &'static [u8] {
        match self {
            Self::Exact => BFV_BOOTSTRAP_KEY_TRANSCRIPT_ZERO_REFRESH_PROOF_STATEMENT_DOMAIN,
            Self::BoundedNoise => {
                BFV_BOUNDED_NOISE_BOOTSTRAP_KEY_TRANSCRIPT_ZERO_REFRESH_PROOF_STATEMENT_DOMAIN
            }
        }
    }
}

impl BfvEvaluationKeyBundle {
    /// Validate evaluation-key shapes against BFV parameters.
    ///
    /// # Errors
    /// Returns [`BfvError`] when key material is malformed or duplicated.
    pub fn validate(&self, params: &BfvParameters) -> Result<(), BfvError> {
        params.validate()?;
        validate_evaluation_key_bundle_metadata(params, self)?;
        validate_relinearization_key(params, &self.relinearization_key)?;
        validate_rotation_key_set_entries(params, &self.rotation_keys)?;
        validate_galois_key_set_entries(params, &self.galois_keys)?;
        if let Some(bootstrap_key) = self.bootstrap_key.as_ref() {
            validate_bootstrap_key_entries(params, bootstrap_key)?;
        }
        Ok(())
    }

    /// Verify public encrypted-zero refresh transcripts for the whole bundle.
    ///
    /// This is a public admission diagnostic for the current deterministic
    /// refresh-key format. It requires one transcript seed for every rotation
    /// refresh key and matching metadata for the optional bootstrap key, then
    /// recomputes each encrypted-zero refresh ciphertext from `public_key`.
    /// This prevents callers from validating only a subset of refresh material.
    /// It is still separate from the future proof-carrying full bootstrap key
    /// format.
    ///
    /// # Errors
    /// Returns [`BfvError`] when the bundle, public key, transcript inventory,
    /// or recomputed refresh material is malformed or inconsistent.
    pub fn validate_refresh_transcripts(
        &self,
        params: &BfvParameters,
        public_key: &BfvPublicKey,
        rotation_transcripts: &[BfvRotationKeyTranscriptSeed<'_>],
        bootstrap_transcript: Option<BfvBootstrapKeyTranscriptSeed<'_>>,
    ) -> Result<(), BfvError> {
        self.validate_refresh_transcripts_for_mode(
            params,
            public_key,
            rotation_transcripts,
            bootstrap_transcript,
            BfvRefreshTranscriptMode::Exact,
        )
    }

    /// Verify public rounded encrypted-zero refresh transcripts for the bundle.
    ///
    /// This is the bounded-noise counterpart of
    /// [`Self::validate_refresh_transcripts`]. It requires one transcript seed
    /// for every rotation refresh key and matching metadata for the optional
    /// bootstrap key, then recomputes each rounded encrypted-zero refresh
    /// ciphertext from `public_key`. Legacy exact-lift refresh transcript
    /// validation is intentionally separate so admission can bind which BFV
    /// refresh mode was authorized.
    ///
    /// # Errors
    /// Returns [`BfvError`] when the bundle, public key, transcript inventory,
    /// bounded-noise capacity, or recomputed refresh material is malformed or
    /// inconsistent.
    pub fn validate_bounded_noise_refresh_transcripts(
        &self,
        params: &BfvParameters,
        public_key: &BfvPublicKey,
        rotation_transcripts: &[BfvRotationKeyTranscriptSeed<'_>],
        bootstrap_transcript: Option<BfvBootstrapKeyTranscriptSeed<'_>>,
    ) -> Result<(), BfvError> {
        self.validate_refresh_transcripts_for_mode(
            params,
            public_key,
            rotation_transcripts,
            bootstrap_transcript,
            BfvRefreshTranscriptMode::BoundedNoise,
        )
    }

    fn validate_refresh_transcripts_for_mode(
        &self,
        params: &BfvParameters,
        public_key: &BfvPublicKey,
        rotation_transcripts: &[BfvRotationKeyTranscriptSeed<'_>],
        bootstrap_transcript: Option<BfvBootstrapKeyTranscriptSeed<'_>>,
        mode: BfvRefreshTranscriptMode,
    ) -> Result<(), BfvError> {
        validate_refresh_preflight(params, rotation_transcripts, bootstrap_transcript, mode)?;
        validate_public_key(params, public_key)?;
        validate_public_key_not_all_zero(public_key)?;
        self.validate(params)?;
        if rotation_transcripts.len() != self.rotation_keys.len() {
            return Err(BfvError::ShapeMismatch(format!(
                "evaluation-key bundle expected {} rotation refresh transcripts, found {}",
                self.rotation_keys.len(),
                rotation_transcripts.len()
            )));
        }
        let mut seen_rotations = std::collections::BTreeSet::new();
        for transcript in rotation_transcripts {
            if !seen_rotations.insert(transcript.rotation_steps) {
                return Err(BfvError::InvalidParameters(format!(
                    "duplicate rotation refresh transcript for {} steps",
                    transcript.rotation_steps
                )));
            }
            if self
                .rotation_keys
                .iter()
                .all(|key| key.rotation_steps != transcript.rotation_steps)
            {
                return Err(BfvError::ShapeMismatch(format!(
                    "rotation refresh transcript supplied for missing rotation key {}",
                    transcript.rotation_steps
                )));
            }
        }
        for rotation_key in &self.rotation_keys {
            let transcript = rotation_transcripts
                .iter()
                .find(|transcript| transcript.rotation_steps == rotation_key.rotation_steps)
                .ok_or_else(|| {
                    BfvError::ShapeMismatch(format!(
                        "missing deterministic transcript seed for rotation key {}",
                        rotation_key.rotation_steps
                    ))
                })?;
            match mode {
                BfvRefreshTranscriptMode::Exact => validate_rotation_key_zero_refresh_transcript(
                    params,
                    public_key,
                    rotation_key,
                    transcript.seed,
                )?,
                BfvRefreshTranscriptMode::BoundedNoise => {
                    validate_rotation_key_bounded_noise_zero_refresh_transcript(
                        params,
                        public_key,
                        rotation_key,
                        transcript.seed,
                    )?;
                }
            }
        }

        Self::validate_bootstrap_refresh_transcript_for_mode(
            params,
            public_key,
            self.bootstrap_key.as_ref(),
            bootstrap_transcript,
            mode,
        )?;
        Ok(())
    }

    fn validate_bootstrap_refresh_transcript_for_mode(
        params: &BfvParameters,
        public_key: &BfvPublicKey,
        bootstrap_key: Option<&BfvBootstrapKey>,
        bootstrap_transcript: Option<BfvBootstrapKeyTranscriptSeed<'_>>,
        mode: BfvRefreshTranscriptMode,
    ) -> Result<(), BfvError> {
        match (bootstrap_key, bootstrap_transcript) {
            (Some(bootstrap_key), Some(transcript)) => {
                if bootstrap_key.mode == BfvBootstrapKeyMode::FullBootstrapV1 {
                    return Err(BfvError::ShapeMismatch(
                        "full BFV bootstrap keys must not carry deterministic zero-refresh transcript seeds"
                            .to_owned(),
                    ));
                }
                if transcript.key_id != bootstrap_key.key_id
                    || transcript.max_refresh_rounds != bootstrap_key.max_refresh_rounds
                {
                    return Err(BfvError::ShapeMismatch(
                        "bootstrap refresh transcript metadata does not match bundle bootstrap key"
                            .to_owned(),
                    ));
                }
                match mode {
                    BfvRefreshTranscriptMode::Exact => {
                        validate_bootstrap_key_zero_refresh_transcript(
                            params,
                            public_key,
                            bootstrap_key,
                            transcript.seed,
                        )?;
                    }
                    BfvRefreshTranscriptMode::BoundedNoise => {
                        validate_bootstrap_key_bounded_noise_zero_refresh_transcript(
                            params,
                            public_key,
                            bootstrap_key,
                            transcript.seed,
                        )?;
                    }
                }
            }
            (Some(bootstrap_key), None) => {
                if bootstrap_key.mode == BfvBootstrapKeyMode::FullBootstrapV1 {
                    validate_bootstrap_key_public_key_digest(params, public_key, bootstrap_key)?;
                    return Ok(());
                }
                return Err(BfvError::ShapeMismatch(format!(
                    "missing deterministic transcript seed for bootstrap key {}",
                    bootstrap_key.key_id
                )));
            }
            (None, Some(_)) => {
                return Err(BfvError::ShapeMismatch(
                    "bootstrap refresh transcript supplied but bundle has no bootstrap key"
                        .to_owned(),
                ));
            }
            (None, None) => {}
        }
        Ok(())
    }

    /// Return a stable digest over the public refresh transcript inventory.
    ///
    /// The digest is intended for governance/admission binding of the current
    /// deterministic encrypted-zero refresh material. It first validates that
    /// every public rotation/bootstrap refresh mask in the bundle matches the
    /// supplied transcript seed, then hashes the parameter set, public key,
    /// evaluation-key digest, and transcript seed metadata in bundle order. It
    /// does not replace future proof-carrying full bootstrap key admission.
    ///
    /// # Errors
    /// Returns [`BfvError`] when transcript validation fails or canonical
    /// encoding of the digest material fails.
    pub fn refresh_transcript_digest(
        &self,
        params: &BfvParameters,
        public_key: &BfvPublicKey,
        rotation_transcripts: &[BfvRotationKeyTranscriptSeed<'_>],
        bootstrap_transcript: Option<BfvBootstrapKeyTranscriptSeed<'_>>,
    ) -> Result<Hash, BfvError> {
        self.refresh_transcript_digest_for_mode(
            params,
            public_key,
            rotation_transcripts,
            bootstrap_transcript,
            BfvRefreshTranscriptMode::Exact,
        )
    }

    /// Return a stable digest over rounded public refresh transcripts.
    ///
    /// This is the bounded-noise counterpart of
    /// [`Self::refresh_transcript_digest`]. It validates every public
    /// rotation/bootstrap refresh mask with the rounded BFV transcript
    /// generators, then hashes the same public inventory under a separate
    /// domain so exact-lift and bounded-noise admission digests cannot collide.
    ///
    /// # Errors
    /// Returns [`BfvError`] when bounded transcript validation fails or
    /// canonical encoding of the digest material fails.
    pub fn bounded_noise_refresh_transcript_digest(
        &self,
        params: &BfvParameters,
        public_key: &BfvPublicKey,
        rotation_transcripts: &[BfvRotationKeyTranscriptSeed<'_>],
        bootstrap_transcript: Option<BfvBootstrapKeyTranscriptSeed<'_>>,
    ) -> Result<Hash, BfvError> {
        self.refresh_transcript_digest_for_mode(
            params,
            public_key,
            rotation_transcripts,
            bootstrap_transcript,
            BfvRefreshTranscriptMode::BoundedNoise,
        )
    }

    /// Return the proof statement digest for a transcript-bound exact bootstrap key.
    ///
    /// This is the governance-facing statement hash for the current
    /// proof-carrying bootstrap-key admission path. It validates the complete
    /// refresh transcript inventory, then binds the parameter set, public key,
    /// evaluation-key digest, refresh-transcript digest, bootstrap transcript
    /// metadata, and public bootstrap refresh ciphertexts. The returned
    /// statement is `None` when the bundle has no bootstrap key. Governed
    /// `FullBootstrapV1` keys must use
    /// [`Self::full_bootstrap_material_proof_statement_digest`] instead.
    ///
    /// # Errors
    /// Returns [`BfvError`] when transcript validation fails or canonical
    /// encoding of the statement material fails.
    pub fn bootstrap_key_zero_refresh_proof_statement_digest_for_transcript(
        &self,
        params: &BfvParameters,
        public_key: &BfvPublicKey,
        rotation_transcripts: &[BfvRotationKeyTranscriptSeed<'_>],
        bootstrap_transcript: Option<BfvBootstrapKeyTranscriptSeed<'_>>,
    ) -> Result<Option<Hash>, BfvError> {
        self.bootstrap_key_zero_refresh_proof_statement_digest_for_transcript_mode(
            params,
            public_key,
            rotation_transcripts,
            bootstrap_transcript,
            BfvRefreshTranscriptMode::Exact,
        )
    }

    /// Return the proof statement digest for a transcript-bound bounded bootstrap key.
    ///
    /// This is the bounded-noise counterpart of
    /// [`Self::bootstrap_key_zero_refresh_proof_statement_digest_for_transcript`].
    /// It uses a separate domain so exact-lift and bounded-noise proof
    /// statements cannot collide.
    ///
    /// # Errors
    /// Returns [`BfvError`] when bounded transcript validation fails or
    /// canonical encoding of the statement material fails.
    pub fn bounded_noise_bootstrap_key_zero_refresh_proof_statement_digest_for_transcript(
        &self,
        params: &BfvParameters,
        public_key: &BfvPublicKey,
        rotation_transcripts: &[BfvRotationKeyTranscriptSeed<'_>],
        bootstrap_transcript: Option<BfvBootstrapKeyTranscriptSeed<'_>>,
    ) -> Result<Option<Hash>, BfvError> {
        self.bootstrap_key_zero_refresh_proof_statement_digest_for_transcript_mode(
            params,
            public_key,
            rotation_transcripts,
            bootstrap_transcript,
            BfvRefreshTranscriptMode::BoundedNoise,
        )
    }

    fn refresh_transcript_digest_for_mode(
        &self,
        params: &BfvParameters,
        public_key: &BfvPublicKey,
        rotation_transcripts: &[BfvRotationKeyTranscriptSeed<'_>],
        bootstrap_transcript: Option<BfvBootstrapKeyTranscriptSeed<'_>>,
        mode: BfvRefreshTranscriptMode,
    ) -> Result<Hash, BfvError> {
        self.validate_refresh_transcripts_for_mode(
            params,
            public_key,
            rotation_transcripts,
            bootstrap_transcript,
            mode,
        )?;
        let evaluation_key_digest = self.digest(params)?;
        let rotation_transcripts = self
            .rotation_keys
            .iter()
            .map(|rotation_key| {
                let transcript = rotation_transcripts
                    .iter()
                    .find(|transcript| transcript.rotation_steps == rotation_key.rotation_steps)
                    .ok_or_else(|| {
                        BfvError::ShapeMismatch(format!(
                            "missing deterministic transcript seed for rotation key {}",
                            rotation_key.rotation_steps
                        ))
                    })?;
                Ok(BfvRotationKeyTranscriptDigestMaterial {
                    rotation_steps: rotation_key.rotation_steps,
                    seed: transcript.seed.to_vec(),
                })
            })
            .collect::<Result<Vec<_>, BfvError>>()?;
        let bootstrap_transcript =
            bootstrap_transcript.map(|transcript| BfvBootstrapKeyTranscriptDigestMaterial {
                key_id: transcript.key_id.to_owned(),
                max_refresh_rounds: transcript.max_refresh_rounds,
                seed: transcript.seed.to_vec(),
            });
        let material = BfvRefreshTranscriptDigestMaterial {
            version: BFV_REFRESH_TRANSCRIPT_DIGEST_MATERIAL_VERSION_V1,
            field_count: BFV_REFRESH_TRANSCRIPT_DIGEST_MATERIAL_FIELD_COUNT_V1,
            params: *params,
            public_key: public_key.clone(),
            evaluation_key_digest,
            rotation_transcripts,
            bootstrap_transcript,
        };
        let bytes = norito::to_bytes(&material).map_err(|err| {
            BfvError::InvalidParameters(format!("refresh transcript digest encoding failed: {err}"))
        })?;
        Ok(Hash::new_from_chunks(&[
            mode.digest_domain(),
            bytes.as_slice(),
        ]))
    }

    fn bootstrap_key_zero_refresh_proof_statement_digest_for_transcript_mode(
        &self,
        params: &BfvParameters,
        public_key: &BfvPublicKey,
        rotation_transcripts: &[BfvRotationKeyTranscriptSeed<'_>],
        bootstrap_transcript: Option<BfvBootstrapKeyTranscriptSeed<'_>>,
        mode: BfvRefreshTranscriptMode,
    ) -> Result<Option<Hash>, BfvError> {
        let refresh_transcript_digest = self.refresh_transcript_digest_for_mode(
            params,
            public_key,
            rotation_transcripts,
            bootstrap_transcript,
            mode,
        )?;
        let Some(bootstrap_key) = self.bootstrap_key.as_ref() else {
            return Ok(None);
        };
        if bootstrap_key.mode == BfvBootstrapKeyMode::FullBootstrapV1 {
            return Err(BfvError::ShapeMismatch(
                "full BFV bootstrap keys must use full-bootstrap material proof statements instead of deterministic zero-refresh transcript statements"
                    .to_owned(),
            ));
        }
        let Some(bootstrap_transcript) = bootstrap_transcript else {
            return Err(BfvError::ShapeMismatch(format!(
                "missing deterministic transcript seed for bootstrap key {}",
                bootstrap_key.key_id
            )));
        };
        let evaluation_key_digest = self.digest(params)?;
        let (bootstrap_round_count, zero_refresh_digest, bootstrap_round_digests) =
            bootstrap_key_refresh_digest_summary_v1(bootstrap_key)?;
        let material = BfvBootstrapKeyTranscriptProofStatementMaterial {
            version: BFV_BOOTSTRAP_KEY_TRANSCRIPT_PROOF_STATEMENT_MATERIAL_VERSION_V1,
            field_count: BFV_BOOTSTRAP_KEY_TRANSCRIPT_PROOF_STATEMENT_MATERIAL_FIELD_COUNT_V1,
            params: *params,
            public_key: public_key.clone(),
            evaluation_key_digest,
            refresh_transcript_digest,
            bootstrap_transcript: BfvBootstrapKeyTranscriptDigestMaterial {
                key_id: bootstrap_transcript.key_id.to_owned(),
                max_refresh_rounds: bootstrap_transcript.max_refresh_rounds,
                seed: bootstrap_transcript.seed.to_vec(),
            },
            bootstrap_round_count,
            zero_refresh_digest,
            bootstrap_round_digests,
            bootstrap_key: bootstrap_key.clone(),
        };
        let bytes = norito::to_bytes(&material).map_err(|err| {
            BfvError::InvalidParameters(format!(
                "bootstrap key transcript proof statement encoding failed: {err}"
            ))
        })?;
        Ok(Some(Hash::new_from_chunks(&[
            mode.bootstrap_key_transcript_proof_statement_domain(),
            bytes.as_slice(),
        ])))
    }

    /// Return the proof statement digest for admitted full-bootstrap material.
    ///
    /// This is the governance-facing statement hash for `FullBootstrapV1`
    /// bundles. It validates the bundle under admission rules, then binds the
    /// BFV parameters, public key, evaluation-key bundle digest, bootstrap-key
    /// metadata, and full-bootstrap material digest under a full-mode-specific
    /// domain. Refresh-only bundles and bundles without a bootstrap key return
    /// `None` so they cannot be mistaken for proof-carrying full-bootstrap
    /// statements.
    ///
    /// The statement does not by itself execute full bootstrap; execution must
    /// still route through the governed artifact-aware evaluator and carry the
    /// matching material proof accepted by the Soracloud verifier gate.
    ///
    /// # Errors
    /// Returns [`BfvError`] when public metadata, full-bootstrap material,
    /// evaluation-key material, public-key shape, or canonical encoding fails.
    pub fn full_bootstrap_material_proof_statement_digest(
        &self,
        params: &BfvParameters,
        public_key: &BfvPublicKey,
    ) -> Result<Option<Hash>, BfvError> {
        validate_evaluation_key_bundle_metadata(params, self)?;
        validate_public_key(params, public_key)?;
        validate_public_key_not_all_zero(public_key)?;
        self.validate(params)?;
        let Some(bootstrap_key) = self.bootstrap_key.as_ref() else {
            return Ok(None);
        };
        validate_bootstrap_key_public_key_digest(params, public_key, bootstrap_key)?;
        if bootstrap_key.mode == BfvBootstrapKeyMode::RefreshOnlyV1 {
            return Ok(None);
        }
        let material = bootstrap_key
            .full_bootstrap_material
            .as_ref()
            .ok_or_else(|| {
                BfvError::InvalidParameters(
                    "full BFV bootstrap key mode requires bootstrapping circuit material"
                        .to_owned(),
                )
            })?;
        let full_bootstrap_material_digest =
            bfv_full_bootstrap_circuit_material_digest(params, material)?;
        let material = BfvFullBootstrapMaterialProofStatementMaterial {
            version: BFV_FULL_BOOTSTRAP_MATERIAL_PROOF_STATEMENT_MATERIAL_VERSION_V1,
            field_count: BFV_FULL_BOOTSTRAP_MATERIAL_PROOF_STATEMENT_MATERIAL_FIELD_COUNT_V1,
            params: *params,
            public_key: public_key.clone(),
            evaluation_key_digest: self.digest(params)?,
            bootstrap_key_id: bootstrap_key.key_id.clone(),
            bootstrap_key_mode: bootstrap_key.mode,
            max_refresh_rounds: bootstrap_key.max_refresh_rounds,
            full_bootstrap_material_digest,
        };
        let bytes = norito::to_bytes(&material).map_err(|err| {
            BfvError::InvalidParameters(format!(
                "full-bootstrap material proof statement encoding failed: {err}"
            ))
        })?;
        Ok(Some(Hash::new_from_chunks(&[
            BFV_FULL_BOOTSTRAP_MATERIAL_PROOF_STATEMENT_DOMAIN,
            bytes.as_slice(),
        ])))
    }

    /// Verify that all public refresh ciphertexts decrypt to zero.
    ///
    /// This is a key-owner diagnostic for bundle construction. Public
    /// evaluators still validate only shapes, bounds, and metadata because the
    /// current encrypted-zero refresh path does not carry public zero-plaintext
    /// proofs.
    ///
    /// # Errors
    /// Returns [`BfvError`] when the bundle is malformed, `secret_key` does not
    /// match the parameter set, or any rotation/bootstrap refresh ciphertext
    /// decrypts to non-zero plaintext under `secret_key`.
    pub fn validate_zero_refreshes(
        &self,
        params: &BfvParameters,
        secret_key: &BfvSecretKey,
    ) -> Result<(), BfvError> {
        validate_evaluation_key_bundle_zero_refresh_preflight(params, self)?;
        validate_bfv_seeded_encryption_residual_capacity(params)?;
        validate_secret_key(params, secret_key)?;
        validate_evaluation_key_bundle_key_switch_entries(params, self)?;
        for (index, rotation_key) in self.rotation_keys.iter().enumerate() {
            validate_refresh_ciphertext_decrypts_to_zero(
                params,
                secret_key,
                &rotation_key.zero_refresh,
                &format!("evaluation-key bundle rotation_keys[{index}].zero_refresh"),
            )?;
        }
        if let Some(bootstrap_key) = self.bootstrap_key.as_ref() {
            validate_bootstrap_key_zero_refreshes(params, secret_key, bootstrap_key)?;
        }
        Ok(())
    }

    /// Verify that all rounded public refresh ciphertexts decrypt to zero.
    ///
    /// This is the bounded-noise counterpart of [`Self::validate_zero_refreshes`]
    /// for key-owner bundle construction. It checks rounded plaintext zero and
    /// the fresh bounded-noise budget for every rotation/bootstrap refresh mask.
    ///
    /// # Errors
    /// Returns [`BfvError`] when the bundle is malformed, `secret_key` does not
    /// match the parameter set, any refresh ciphertext decrypts to non-zero
    /// plaintext, or any refresh ciphertext exceeds the bounded-noise budget.
    pub fn validate_bounded_noise_zero_refreshes(
        &self,
        params: &BfvParameters,
        secret_key: &BfvSecretKey,
    ) -> Result<(), BfvError> {
        validate_evaluation_key_bundle_zero_refresh_preflight(params, self)?;
        validate_bfv_bounded_noise_encryption_capacity(params)?;
        validate_secret_key(params, secret_key)?;
        validate_evaluation_key_bundle_key_switch_entries(params, self)?;
        for (index, rotation_key) in self.rotation_keys.iter().enumerate() {
            validate_rotation_key_bounded_noise_zero_refresh_with_label(
                params,
                secret_key,
                rotation_key,
                &format!("evaluation-key bundle rotation_keys[{index}].zero_refresh"),
            )?;
        }
        if let Some(bootstrap_key) = self.bootstrap_key.as_ref() {
            validate_bootstrap_key_bounded_noise_zero_refreshes_with_label(
                params,
                secret_key,
                bootstrap_key,
                "evaluation-key bundle bootstrap_key",
            )?;
        }
        Ok(())
    }

    /// Verify that evaluation keys are consistent with a secret key.
    ///
    /// This is a key-owner diagnostic for bundle construction. It checks that
    /// relinearization entries decrypt to the expected scaled `s^2` residues,
    /// Galois entries decrypt to the expected scaled automorphed-secret
    /// residues, and every public refresh ciphertext decrypts to zero. The
    /// residual for key-switch entries must stay in the current deterministic
    /// plaintext-modulus-multiple error profile.
    ///
    /// # Errors
    /// Returns [`BfvError`] when the bundle is malformed, `secret_key` does not
    /// match the parameter set, any key-switch entry has an unexpected
    /// plaintext residue or oversized error multiple, or any public refresh
    /// ciphertext decrypts to non-zero plaintext.
    pub fn validate_secret_key_consistency(
        &self,
        params: &BfvParameters,
        secret_key: &BfvSecretKey,
    ) -> Result<(), BfvError> {
        self.validate_zero_refreshes(params, secret_key)?;
        let secret_square = poly_mul_mod(params, &secret_key.s, &secret_key.s);
        validate_key_switch_entry_residuals(
            params,
            &secret_key.s,
            &secret_square,
            &self.relinearization_key.entries,
            "evaluation-key bundle relinearization_key",
        )?;
        for (index, galois_key) in self.galois_keys.iter().enumerate() {
            let target_secret = apply_galois_automorphism_poly(
                params,
                &secret_key.s,
                galois_key.automorphism_power,
            )?;
            validate_key_switch_entry_residuals(
                params,
                &secret_key.s,
                &target_secret,
                &galois_key.entries,
                &format!("evaluation-key bundle galois_keys[{index}]"),
            )?;
        }
        Ok(())
    }

    /// Verify that bounded-noise evaluation keys match a secret key.
    ///
    /// This is the rounded BFV counterpart of
    /// [`Self::validate_secret_key_consistency`]. It checks that relinearization
    /// entries decrypt to raw `base^i * s^2`, Galois entries decrypt to raw
    /// `base^i * sigma_k(s)`, and every public rotation/bootstrap refresh
    /// ciphertext decrypts to zero, all under the bounded centered-noise policy.
    ///
    /// # Errors
    /// Returns [`BfvError`] when the bundle is malformed, `secret_key` does not
    /// match the parameter set, any bounded key-switch entry has an unexpected
    /// target residue or oversized noise, or any public refresh ciphertext
    /// decrypts to non-zero plaintext or exceeds the bounded-noise budget.
    pub fn validate_bounded_noise_secret_key_consistency(
        &self,
        params: &BfvParameters,
        secret_key: &BfvSecretKey,
    ) -> Result<(), BfvError> {
        self.validate_bounded_noise_zero_refreshes(params, secret_key)?;
        validate_bounded_noise_relinearization_key_secret_consistency_with_label(
            params,
            secret_key,
            &self.relinearization_key,
            "evaluation-key bundle relinearization_key",
        )?;
        for (index, galois_key) in self.galois_keys.iter().enumerate() {
            validate_bounded_noise_galois_key_secret_consistency_with_label(
                params,
                secret_key,
                galois_key,
                &format!("evaluation-key bundle galois_keys[{index}]"),
            )?;
        }
        Ok(())
    }

    /// Return a stable digest over the evaluation-key bundle.
    ///
    /// # Errors
    /// Returns [`BfvError`] when validation or canonical encoding fails.
    pub fn digest(&self, params: &BfvParameters) -> Result<Hash, BfvError> {
        self.validate(params)?;
        validate_evaluation_key_bundle_digest_refresh_material_v1(self)?;
        let bytes = norito::to_bytes(self).map_err(|err| {
            BfvError::InvalidParameters(format!("evaluation key encoding failed: {err}"))
        })?;
        Ok(Hash::new_from_chunks(&[
            BFV_EVALUATION_KEY_DIGEST_DOMAIN,
            bytes.as_slice(),
        ]))
    }
}

/// Return a stable digest over the BFV Galois-key set used by full-bootstrap execution.
///
/// The digest is bound into full-bootstrap execution witness material so a
/// proof statement identifies the exact public automorphism key material used
/// to derive its deterministic trace.
///
/// # Errors
/// Returns [`BfvError`] when the key set is malformed or canonical encoding fails.
pub fn bfv_full_bootstrap_galois_key_set_digest_v1(
    params: &BfvParameters,
    galois_keys: &[BfvGaloisKey],
) -> Result<Hash, BfvError> {
    validate_galois_key_set(params, galois_keys, "BFV full-bootstrap Galois key set")?;
    let params_bytes = norito::to_bytes(params).map_err(|err| {
        BfvError::InvalidParameters(format!(
            "BFV full-bootstrap Galois key set parameter encoding failed: {err}"
        ))
    })?;
    let mut key_material = galois_keys.to_vec();
    key_material.sort_by_key(|key| key.automorphism_power);
    let key_bytes = norito::to_bytes(&key_material).map_err(|err| {
        BfvError::InvalidParameters(format!(
            "BFV full-bootstrap Galois key set encoding failed: {err}"
        ))
    })?;
    Ok(Hash::new_from_chunks(&[
        BFV_FULL_BOOTSTRAP_GALOIS_KEY_SET_DIGEST_DOMAIN,
        params_bytes.as_slice(),
        key_bytes.as_slice(),
    ]))
}

/// BFV ciphertext with two components.
#[cfg_attr(feature = "json", derive(JsonSerialize, JsonDeserialize))]
#[derive(Clone, Debug, PartialEq, Eq, Encode, Decode, IntoSchema)]
pub struct BfvCiphertext {
    /// First ciphertext polynomial.
    pub c0: Vec<u64>,
    /// Second ciphertext polynomial.
    pub c1: Vec<u64>,
}

/// Secret-key diagnostic for the first-release exact BFV residual.
///
/// This is not a bounded-RLWE noise estimate. It decomposes each centered
/// decrypted coefficient as `plaintext + t * residual_multiple`, where `t` is
/// the plaintext modulus used by the deterministic exact evaluator bridge.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct BfvExactResidualProfile {
    /// Plaintext coefficients returned by the normal BFV decrypt path.
    pub plaintext: Vec<u64>,
    /// Signed residual multiple for each centered decrypted coefficient.
    pub residual_multiples: Vec<i128>,
    /// Largest absolute residual multiple in this ciphertext.
    pub max_abs_residual_multiple: u128,
    /// Largest centered residual multiple representable before wraparound.
    pub centered_residual_multiple_capacity: u128,
    /// Remaining margin to the centered residual capacity.
    pub residual_multiple_headroom: u128,
}

/// Secret-key diagnostic for rounded BFV plaintext scaling.
///
/// Unlike [`BfvExactResidualProfile`], this profile measures centered
/// ciphertext noise around the nearest `round(q/t) * plaintext` representative.
/// It is the first bounded-noise BFV diagnostic used by the pending BFV-RNS
/// replacement path.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct BfvBoundedNoiseProfile {
    /// Plaintext coefficients returned by rounded BFV decryption.
    pub plaintext: Vec<u64>,
    /// Signed centered noise for each decrypted coefficient.
    pub noise: Vec<i128>,
    /// Largest absolute centered noise coefficient.
    pub max_abs_noise: u128,
    /// Largest centered noise admitted before rounded plaintext decoding may cross a boundary.
    pub centered_decoding_capacity: u128,
    /// Remaining margin to the centered rounded-decoding capacity.
    pub noise_headroom: u128,
}

/// Public BFV parameters published to clients for encrypted identifier input.
#[cfg_attr(feature = "json", derive(JsonSerialize, JsonDeserialize))]
#[derive(Clone, Debug, PartialEq, Eq, Encode, Decode, IntoSchema)]
pub struct BfvIdentifierPublicParameters {
    /// Underlying BFV parameter set.
    pub parameters: BfvParameters,
    /// Public key used to encrypt identifier input.
    pub public_key: BfvPublicKey,
    /// Maximum number of raw UTF-8 input bytes accepted by the envelope.
    pub max_input_bytes: u16,
}

/// BFV ciphertext envelope for identifier input.
#[cfg_attr(feature = "json", derive(JsonSerialize, JsonDeserialize))]
#[derive(Clone, Debug, PartialEq, Eq, Encode, Decode, IntoSchema)]
pub struct BfvIdentifierCiphertext {
    /// Scalar ciphertext slots: slot 0 is the byte length, followed by one slot per byte.
    pub slots: Vec<BfvCiphertext>,
}

impl BfvIdentifierPublicParameters {
    /// Validate the public parameters and envelope capacity.
    ///
    /// # Errors
    /// Returns [`BfvError`] when the envelope is internally inconsistent or
    /// does not use a registered production BFV parameter profile.
    pub fn validate(&self) -> Result<(), BfvError> {
        validate_identifier_public_parameter_metadata(self)?;
        validate_public_key(&self.parameters, &self.public_key)?;
        validate_public_key_not_all_zero(&self.public_key)?;
        Ok(())
    }
}

fn validate_identifier_public_parameter_metadata(
    public_parameters: &BfvIdentifierPublicParameters,
) -> Result<(), BfvError> {
    validate_identifier_public_parameter_metadata_parts(
        &public_parameters.parameters,
        public_parameters.max_input_bytes,
    )
}

fn validate_identifier_public_parameter_metadata_parts(
    params: &BfvParameters,
    max_input_bytes: u16,
) -> Result<(), BfvError> {
    validate_registered_bfv_parameters(params)?;
    if max_input_bytes == 0 {
        return Err(BfvError::InvalidParameters(
            "max_input_bytes must be at least 1".to_owned(),
        ));
    }
    if u64::from(max_input_bytes) >= params.plaintext_modulus {
        return Err(BfvError::InvalidParameters(
            "max_input_bytes must fit into one plaintext slot".to_owned(),
        ));
    }
    if max_input_bytes > RAM_LFE_BFV_IDENTIFIER_MAX_INPUT_BYTES {
        return Err(BfvError::InvalidParameters(format!(
            "max_input_bytes must be at most {RAM_LFE_BFV_IDENTIFIER_MAX_INPUT_BYTES} for the registered RAM-LFE BFV identifier profile"
        )));
    }
    Ok(())
}

/// Return the registered BFV parameter set used by RAM-LFE byte-slot programs.
#[must_use]
pub const fn ram_lfe_bfv_parameters_v1() -> BfvParameters {
    BfvParameters {
        polynomial_degree: 64,
        ciphertext_modulus: RAM_LFE_BFV_CIPHERTEXT_MODULUS,
        plaintext_modulus: RAM_LFE_BFV_PLAINTEXT_MODULUS,
        decomposition_base_log: 12,
    }
}

/// Return the registered BFV RNS chain for RAM-LFE byte-slot programs.
#[must_use]
pub fn ram_lfe_bfv_rns_modulus_chain_v1() -> BfvRnsModulusChain {
    BfvRnsModulusChain {
        moduli: RAM_LFE_BFV_RNS_MODULI_V1.to_vec(),
    }
}

/// Validate that parameters match a registered production BFV profile.
///
/// # Errors
/// Returns [`BfvError`] when the parameter set is malformed or not registered.
pub fn validate_registered_bfv_parameters(params: &BfvParameters) -> Result<(), BfvError> {
    params.validate()?;
    if *params != ram_lfe_bfv_parameters_v1() {
        return Err(BfvError::InvalidParameters(
            "BFV parameter set is not registered for production FHE evaluation".to_owned(),
        ));
    }
    validate_bfv_seeded_encryption_residual_capacity(params)?;
    Ok(())
}

/// Return the registered BFV RNS chain for a production BFV parameter set.
///
/// # Errors
/// Returns [`BfvError`] when the parameter set is not registered or the
/// registered chain fails validation.
pub fn registered_bfv_rns_modulus_chain(
    params: &BfvParameters,
) -> Result<BfvRnsModulusChain, BfvError> {
    validate_registered_bfv_parameters(params)?;
    let chain = ram_lfe_bfv_rns_modulus_chain_v1();
    validate_rns_exact_evaluator_chain(params, &chain)?;
    validate_registered_bfv_rns_negacyclic_roots(params, &chain)?;
    Ok(chain)
}

/// Return the stable digest for a registered BFV RNS modulus chain.
///
/// # Errors
/// Returns [`BfvError`] when the parameter set is not registered or the
/// registered chain fails validation or canonical encoding.
pub fn registered_bfv_rns_modulus_chain_digest(params: &BfvParameters) -> Result<Hash, BfvError> {
    let chain = registered_bfv_rns_modulus_chain(params)?;
    chain.digest_for_parameters(params)
}

/// Return the registered BFV RNS chain used for key-switch decomposition.
///
/// The returned chain is the smallest prefix of the registered evaluator chain
/// that can still cover the ciphertext modulus and key-switch decomposition
/// base. Target-limb key-switch bridges decompose in this source chain and
/// extend the resulting digit polynomials into the full evaluator chain.
///
/// # Errors
/// Returns [`BfvError`] when the parameter set is not registered, the
/// registered evaluator chain is malformed, or no prefix covers the required
/// key-switch decomposition product.
pub fn registered_bfv_key_switch_decomposition_chain(
    params: &BfvParameters,
) -> Result<BfvRnsModulusChain, BfvError> {
    let evaluator_chain = registered_bfv_rns_modulus_chain(params)?;
    registered_bfv_key_switch_decomposition_chain_for_evaluator(params, &evaluator_chain)
}

/// Return the stable digest for the registered key-switch decomposition chain.
///
/// # Errors
/// Returns [`BfvError`] when the parameter set is not registered, the
/// decomposition chain fails validation, or canonical encoding fails.
pub fn registered_bfv_key_switch_decomposition_chain_digest(
    params: &BfvParameters,
) -> Result<Hash, BfvError> {
    let chain = registered_bfv_key_switch_decomposition_chain(params)?;
    let bytes = norito::to_bytes(&chain).map_err(|err| {
        BfvError::InvalidParameters(format!(
            "RNS key-switch decomposition-chain encoding failed: {err}"
        ))
    })?;
    Ok(Hash::new_from_chunks(&[
        BFV_RNS_KEY_SWITCH_DECOMPOSITION_CHAIN_DIGEST_DOMAIN,
        bytes.as_slice(),
    ]))
}

/// Return the registered BFV RNS chain used as centered scale-round source.
///
/// The returned chain is the smallest prefix of the registered evaluator chain
/// that can exactly represent the two-product centered raw-product sum used by
/// rounded BFV multiplication cross terms before target-limb conversion into
/// the evaluator chain.
///
/// # Errors
/// Returns [`BfvError`] when the parameter set is not registered, the
/// registered evaluator chain is malformed, or no prefix covers the centered
/// scale-round product-sum bound.
pub fn registered_bfv_centered_scale_round_source_chain(
    params: &BfvParameters,
) -> Result<BfvRnsModulusChain, BfvError> {
    let evaluator_chain = registered_bfv_rns_modulus_chain(params)?;
    registered_bfv_centered_scale_round_source_chain_for_evaluator(params, &evaluator_chain)
}

/// Return the stable digest for the registered centered scale-round source chain.
///
/// # Errors
/// Returns [`BfvError`] when the parameter set is not registered, the source
/// chain fails validation, or canonical encoding fails.
pub fn registered_bfv_centered_scale_round_source_chain_digest(
    params: &BfvParameters,
) -> Result<Hash, BfvError> {
    let chain = registered_bfv_centered_scale_round_source_chain(params)?;
    let bytes = norito::to_bytes(&chain).map_err(|err| {
        BfvError::InvalidParameters(format!(
            "RNS centered scale-round source-chain encoding failed: {err}"
        ))
    })?;
    Ok(Hash::new_from_chunks(&[
        BFV_RNS_CENTERED_SCALE_ROUND_SOURCE_CHAIN_DIGEST_DOMAIN,
        bytes.as_slice(),
    ]))
}

/// Return the stable digest for a registered BFV parameter set.
///
/// # Errors
/// Returns [`BfvError`] when the parameter set is not registered.
pub fn registered_bfv_parameter_digest(params: &BfvParameters) -> Result<Hash, BfvError> {
    validate_registered_bfv_parameters(params)?;
    let bytes = norito::to_bytes(params)
        .map_err(|err| BfvError::InvalidParameters(format!("parameter encoding failed: {err}")))?;
    Ok(Hash::new_from_chunks(&[
        BFV_PARAMETER_DIGEST_DOMAIN,
        bytes.as_slice(),
    ]))
}

/// Return the stable digest for a BFV public key under a parameter set.
///
/// # Errors
/// Returns [`BfvError`] when the parameter set or public-key shape is invalid.
pub fn bfv_public_key_digest(
    params: &BfvParameters,
    public_key: &BfvPublicKey,
) -> Result<Hash, BfvError> {
    params.validate()?;
    validate_public_key(params, public_key)?;
    validate_public_key_not_all_zero(public_key)?;
    let material = BfvPublicKeyDigestMaterial {
        params: *params,
        public_key: public_key.clone(),
    };
    let bytes = norito::to_bytes(&material).map_err(|err| {
        BfvError::InvalidParameters(format!("public key digest encoding failed: {err}"))
    })?;
    Ok(Hash::new_from_chunks(&[
        BFV_PUBLIC_KEY_DIGEST_DOMAIN,
        bytes.as_slice(),
    ]))
}

/// Return the stable digest for a non-inert BFV ciphertext under a parameter set.
///
/// This digest is the public commitment used by ciphertext proof-statement
/// material. It rejects the all-zero ciphertext sentinel so verifier-facing
/// statement hashes cannot bless placeholder encrypted inputs.
///
/// # Errors
/// Returns [`BfvError`] when the parameter set or ciphertext shape is invalid,
/// the ciphertext is all zero, or canonical statement encoding fails.
pub fn bfv_ciphertext_digest(
    params: &BfvParameters,
    ciphertext: &BfvCiphertext,
) -> Result<Hash, BfvError> {
    params.validate()?;
    validate_ciphertext(params, ciphertext)?;
    validate_ciphertext_not_all_zero("BFV ciphertext digest ciphertext", ciphertext)?;
    let material = BfvCiphertextDigestMaterial {
        params: *params,
        ciphertext: ciphertext.clone(),
    };
    let bytes = norito::to_bytes(&material).map_err(|err| {
        BfvError::InvalidParameters(format!("ciphertext digest encoding failed: {err}"))
    })?;
    Ok(Hash::new_from_chunks(&[
        BFV_CIPHERTEXT_DIGEST_DOMAIN,
        bytes.as_slice(),
    ]))
}

/// Return the public statement digest for exact-lift BFV public-key admission.
///
/// This is the canonical public input for a proof that an admitted BFV public
/// key has a secret-key witness and exact residual-multiple error profile
/// compatible with `params`. The function binds the parameter set, public key,
/// and public-key digest under an exact-lift-specific domain. It validates only
/// public metadata and shape; the secret-key consistency claim must still be
/// proven by the attached verifier.
///
/// # Errors
/// Returns [`BfvError`] when parameter capacity, public-key shape, public-key
/// digesting, or canonical statement encoding fails.
pub fn bfv_public_key_proof_statement_digest(
    params: &BfvParameters,
    public_key: &BfvPublicKey,
) -> Result<Hash, BfvError> {
    bfv_public_key_proof_statement_digest_for_mode(
        params,
        public_key,
        BfvRefreshTranscriptMode::Exact,
    )
}

/// Return the public statement digest for bounded-noise BFV public-key admission.
///
/// This is the bounded-noise counterpart of
/// [`bfv_public_key_proof_statement_digest`]. It uses a separate domain so
/// exact-lift and rounded-noise public-key admission proofs cannot collide.
///
/// # Errors
/// Returns [`BfvError`] when bounded-noise capacity, public-key shape,
/// public-key digesting, or canonical statement encoding fails.
pub fn bfv_bounded_noise_public_key_proof_statement_digest(
    params: &BfvParameters,
    public_key: &BfvPublicKey,
) -> Result<Hash, BfvError> {
    bfv_public_key_proof_statement_digest_for_mode(
        params,
        public_key,
        BfvRefreshTranscriptMode::BoundedNoise,
    )
}

/// Return the public statement digest for exact-lift BFV ciphertext admission.
///
/// This is the canonical public input for a future proof that an admitted
/// ciphertext is encrypted under the published BFV public key and satisfies the
/// declared exact residual-multiple bound. The helper binds the parameter set,
/// public key, public-key digest, ciphertext, ciphertext digest, and declared
/// bound under an exact-lift-specific domain; the witness claim must still be
/// proven by the attached verifier.
///
/// # Errors
/// Returns [`BfvError`] when exact seeded-encryption capacity, public-key
/// shape, ciphertext shape, inert ciphertext rejection, bound validation, or
/// canonical statement encoding fails.
pub fn bfv_ciphertext_exact_residual_proof_statement_digest(
    params: &BfvParameters,
    public_key: &BfvPublicKey,
    ciphertext: &BfvCiphertext,
    max_abs_residual_multiple: u128,
) -> Result<Hash, BfvError> {
    bfv_ciphertext_proof_statement_digest_for_mode(
        params,
        public_key,
        ciphertext,
        max_abs_residual_multiple,
        BfvRefreshTranscriptMode::Exact,
    )
}

/// Return the public statement digest for bounded-noise BFV ciphertext admission.
///
/// This is the bounded-noise counterpart of
/// [`bfv_ciphertext_exact_residual_proof_statement_digest`]. It uses a
/// separate domain and validates the declared centered-noise bound against the
/// rounded BFV decoding capacity before hashing the statement material.
///
/// # Errors
/// Returns [`BfvError`] when bounded-noise capacity, public-key shape,
/// ciphertext shape, inert ciphertext rejection, bound validation, or canonical
/// statement encoding fails.
pub fn bfv_bounded_noise_ciphertext_proof_statement_digest(
    params: &BfvParameters,
    public_key: &BfvPublicKey,
    ciphertext: &BfvCiphertext,
    max_abs_noise: u128,
) -> Result<Hash, BfvError> {
    bfv_ciphertext_proof_statement_digest_for_mode(
        params,
        public_key,
        ciphertext,
        max_abs_noise,
        BfvRefreshTranscriptMode::BoundedNoise,
    )
}

fn bfv_public_key_proof_statement_digest_for_mode(
    params: &BfvParameters,
    public_key: &BfvPublicKey,
    mode: BfvRefreshTranscriptMode,
) -> Result<Hash, BfvError> {
    match mode {
        BfvRefreshTranscriptMode::Exact => {
            validate_bfv_seeded_encryption_residual_capacity(params)?
        }
        BfvRefreshTranscriptMode::BoundedNoise => {
            validate_bfv_bounded_noise_encryption_capacity(params)?;
        }
    }
    let public_key_digest = bfv_public_key_digest(params, public_key)?;
    validate_nonzero_material_digest(
        "BFV public-key proof statement public-key digest",
        &public_key_digest,
    )?;
    validate_no_full_bootstrap_placeholder_material_digest(
        "BFV public-key proof statement public-key digest",
        &public_key_digest,
    )?;
    let material = BfvPublicKeyProofStatementMaterial {
        version: BFV_PUBLIC_KEY_PROOF_STATEMENT_MATERIAL_VERSION_V1,
        field_count: BFV_PUBLIC_KEY_PROOF_STATEMENT_MATERIAL_FIELD_COUNT_V1,
        params: *params,
        public_key: public_key.clone(),
        public_key_digest,
    };
    let bytes = norito::to_bytes(&material).map_err(|err| {
        BfvError::InvalidParameters(format!("public-key proof statement encoding failed: {err}"))
    })?;
    Ok(Hash::new_from_chunks(&[
        mode.public_key_proof_statement_domain(),
        bytes.as_slice(),
    ]))
}

fn bfv_ciphertext_proof_statement_digest_for_mode(
    params: &BfvParameters,
    public_key: &BfvPublicKey,
    ciphertext: &BfvCiphertext,
    declared_bound: u128,
    mode: BfvRefreshTranscriptMode,
) -> Result<Hash, BfvError> {
    match mode {
        BfvRefreshTranscriptMode::Exact => {
            validate_bfv_seeded_encryption_residual_capacity(params)?;
            validate_exact_residual_bound_within_centered_capacity(
                params,
                declared_bound,
                "BFV ciphertext proof statement exact residual bound",
            )?;
        }
        BfvRefreshTranscriptMode::BoundedNoise => {
            validate_bfv_bounded_noise_encryption_capacity(params)?;
            validate_bounded_noise_bound_within_decoding_capacity(
                params,
                declared_bound,
                "BFV ciphertext proof statement bounded-noise bound",
            )?;
        }
    }
    let public_key_digest = bfv_public_key_digest(params, public_key)?;
    validate_nonzero_material_digest(
        "BFV ciphertext proof statement public-key digest",
        &public_key_digest,
    )?;
    validate_no_full_bootstrap_placeholder_material_digest(
        "BFV ciphertext proof statement public-key digest",
        &public_key_digest,
    )?;
    let ciphertext_digest = bfv_ciphertext_digest(params, ciphertext)?;
    validate_nonzero_material_digest(
        "BFV ciphertext proof statement ciphertext digest",
        &ciphertext_digest,
    )?;
    validate_no_full_bootstrap_placeholder_material_digest(
        "BFV ciphertext proof statement ciphertext digest",
        &ciphertext_digest,
    )?;
    let material = BfvCiphertextProofStatementMaterial {
        version: BFV_CIPHERTEXT_PROOF_STATEMENT_MATERIAL_VERSION_V1,
        field_count: BFV_CIPHERTEXT_PROOF_STATEMENT_MATERIAL_FIELD_COUNT_V1,
        params: *params,
        public_key: public_key.clone(),
        public_key_digest,
        ciphertext: ciphertext.clone(),
        ciphertext_digest,
        declared_bound,
    };
    let bytes = norito::to_bytes(&material).map_err(|err| {
        BfvError::InvalidParameters(format!("ciphertext proof statement encoding failed: {err}"))
    })?;
    Ok(Hash::new_from_chunks(&[
        mode.ciphertext_proof_statement_domain(),
        bytes.as_slice(),
    ]))
}

fn validate_public_key_not_all_zero(public_key: &BfvPublicKey) -> Result<(), BfvError> {
    if !public_key.b.is_empty() && public_key.b.iter().all(|&coefficient| coefficient == 0) {
        return Err(BfvError::InvalidParameters(
            "BFV public key b component must not be all zero".to_owned(),
        ));
    }
    if !public_key.a.is_empty() && public_key.a.iter().all(|&coefficient| coefficient == 0) {
        return Err(BfvError::InvalidParameters(
            "BFV public key a component must not be all zero".to_owned(),
        ));
    }
    Ok(())
}

/// Public affine circuit over scalar ciphertext inputs.
#[cfg_attr(feature = "json", derive(JsonSerialize, JsonDeserialize))]
#[derive(Clone, Debug, PartialEq, Eq, Encode, Decode, IntoSchema)]
pub struct BfvAffineCircuit {
    /// Output rows; each row stores one plaintext weight per input ciphertext.
    pub weights: Vec<Vec<u64>>,
    /// Plaintext bias added to each output row.
    pub bias: Vec<u64>,
}

impl BfvAffineCircuit {
    /// Validate the circuit shape and plaintext coefficients.
    ///
    /// # Errors
    /// Returns [`BfvError`] when the circuit shape is invalid.
    pub fn validate(&self, params: &BfvParameters, input_count: usize) -> Result<(), BfvError> {
        params.validate()?;
        if self.weights.is_empty() {
            return Err(BfvError::InvalidCircuit(
                "affine circuit must have at least one output row".to_owned(),
            ));
        }
        if self.weights.len() != self.bias.len() {
            return Err(BfvError::InvalidCircuit(
                "weights and bias must have the same outer length".to_owned(),
            ));
        }
        for (row_index, row) in self.weights.iter().enumerate() {
            if row.len() != input_count {
                return Err(BfvError::InvalidCircuit(format!(
                    "weights[{row_index}] expected {input_count} inputs, found {}",
                    row.len()
                )));
            }
            for &weight in row {
                if weight >= params.plaintext_modulus {
                    return Err(BfvError::InvalidCircuit(format!(
                        "weight {weight} exceeds plaintext modulus {}",
                        params.plaintext_modulus
                    )));
                }
            }
        }
        for &bias in &self.bias {
            if bias >= params.plaintext_modulus {
                return Err(BfvError::InvalidCircuit(format!(
                    "bias {bias} exceeds plaintext modulus {}",
                    params.plaintext_modulus
                )));
            }
        }
        Ok(())
    }
}

/// Errors raised by the deterministic BFV baseline.
#[derive(Clone, Debug, Error, PartialEq, Eq)]
pub enum BfvError {
    /// The parameter set is invalid.
    #[error("invalid BFV parameters: {0}")]
    InvalidParameters(String),
    /// The ciphertext or key shape does not match the parameter set.
    #[error("shape mismatch: {0}")]
    ShapeMismatch(String),
    /// Plaintext coefficients exceed the plaintext modulus.
    #[error("plaintext coefficient {coefficient} exceeds plaintext modulus {plaintext_modulus}")]
    PlaintextOutOfRange {
        /// Offending plaintext coefficient.
        coefficient: u64,
        /// Active plaintext modulus.
        plaintext_modulus: u64,
    },
    /// The affine circuit is invalid.
    #[error("invalid affine circuit: {0}")]
    InvalidCircuit(String),
    /// The identifier input does not fit the configured BFV envelope.
    #[error("identifier input exceeds the maximum supported length of {max_input_bytes} bytes")]
    InputTooLong {
        /// Maximum supported identifier byte length.
        max_input_bytes: u16,
    },
    /// The identifier envelope is malformed after decryption.
    #[error("invalid BFV identifier envelope: {0}")]
    InvalidIdentifierEncoding(String),
}

/// Deterministic BFV key generation from a seed.
///
/// # Errors
/// Returns [`BfvError`] when parameters are invalid or the deterministic seed
/// is empty or oversized.
pub fn keygen_from_seed(
    params: &BfvParameters,
    seed: &[u8],
) -> Result<(BfvSecretKey, BfvPublicKey, BfvRelinearizationKey), BfvError> {
    validate_deterministic_seed("BFV keygen seed", seed)?;
    validate_bfv_seeded_encryption_residual_capacity(params)?;

    let mut rng = derive_rng(KEYGEN_DOMAIN, seed);
    let secret = sample_nonzero_secret_poly(params, &mut rng);
    let (b, a) = loop {
        let a = sample_nonzero_uniform_poly(params, &mut rng);
        let e = sample_error_poly(params, &mut rng);
        let as_product = poly_mul_mod(params, &a, &secret);
        let b = poly_sub_mod(params, &poly_neg_mod(params, &as_product), &e);
        if b.iter().any(|&coefficient| coefficient != 0) {
            break (b, a);
        }
    };

    let secret_sq = poly_mul_mod(params, &secret, &secret);
    let relin_entries = key_switch_entries_from_rng(params, &secret, &secret_sq, &mut rng)?;

    let secret_key = BfvSecretKey { s: secret };
    let public_key = BfvPublicKey { b, a };
    let relinearization_key = BfvRelinearizationKey {
        entries: relin_entries,
    };
    validate_public_key_secret_consistency(params, &secret_key, &public_key)?;
    validate_key_switch_entry_residuals(
        params,
        &secret_key.s,
        &secret_sq,
        &relinearization_key.entries,
        "generated relinearization key",
    )?;
    Ok((secret_key, public_key, relinearization_key))
}

/// Verify that a BFV public key is consistent with a secret key.
///
/// This is a key-owner diagnostic for key material construction. It checks
/// that `b + a*s` decrypts as a plaintext-modulus-multiple error term within
/// the current deterministic exact evaluator bound. It is not a public proof
/// that a published key was honestly generated.
///
/// # Errors
/// Returns [`BfvError`] when the key material is malformed or inert, the public
/// key does not match `secret_key`, or the public-key residual exceeds the
/// current error profile.
pub fn validate_public_key_secret_consistency(
    params: &BfvParameters,
    secret_key: &BfvSecretKey,
    public_key: &BfvPublicKey,
) -> Result<(), BfvError> {
    validate_public_key(params, public_key)?;
    validate_public_key_not_all_zero(public_key)?;
    validate_secret_key(params, secret_key)?;
    let residual = poly_add_mod(
        params,
        &public_key.b,
        &poly_mul_mod(params, &public_key.a, &secret_key.s),
    );
    validate_plaintext_multiple_residual_bound(params, &residual, &zero_poly(params), "public key")
}

/// Deterministic bounded-noise BFV public-key generation from a seed.
///
/// This generates the same secret/public key shapes as [`keygen_from_seed`],
/// but samples public-key error coefficients from a centered small-noise
/// distribution rather than plaintext-modulus multiples. It is the keygen entry
/// for the rounded BFV-RNS replacement path; evaluation-key material is still
/// produced by the exact-lift bridge until the full bounded-noise key-switching
/// path lands.
///
/// # Errors
/// Returns [`BfvError`] when parameters are invalid, the rounded-decoding
/// capacity is too narrow for seeded encryption noise, or the deterministic
/// seed is empty or oversized.
pub fn keygen_bounded_noise_from_seed(
    params: &BfvParameters,
    seed: &[u8],
) -> Result<(BfvSecretKey, BfvPublicKey), BfvError> {
    let (secret_key, public_key, _) =
        keygen_bounded_noise_with_relinearization_from_seed(params, seed)?;
    Ok((secret_key, public_key))
}

/// Deterministic bounded-noise BFV key generation with relinearization material.
///
/// The relinearization entries encrypt raw `base^i * s^2` key-switch material
/// with small centered error. They are intended for
/// [`multiply_ciphertexts_bounded_noise`], not the exact-lift evaluator.
///
/// # Errors
/// Returns [`BfvError`] when parameters are invalid, the rounded-decoding
/// capacity is too narrow for seeded encryption noise, or the deterministic
/// seed is empty or oversized.
pub fn keygen_bounded_noise_with_relinearization_from_seed(
    params: &BfvParameters,
    seed: &[u8],
) -> Result<(BfvSecretKey, BfvPublicKey, BfvRelinearizationKey), BfvError> {
    validate_deterministic_seed("bounded-noise BFV keygen seed", seed)?;
    validate_bfv_bounded_noise_encryption_capacity(params)?;

    let mut rng = derive_rng(BOUNDED_NOISE_KEYGEN_DOMAIN, seed);
    let secret = sample_nonzero_secret_poly(params, &mut rng);
    let (b, a) = loop {
        let a = sample_nonzero_uniform_poly(params, &mut rng);
        let e = sample_bounded_noise_poly(params, &mut rng);
        let as_product = poly_mul_mod(params, &a, &secret);
        let b = poly_sub_mod(params, &poly_neg_mod(params, &as_product), &e);
        if b.iter().any(|&coefficient| coefficient != 0) {
            break (b, a);
        }
    };

    let secret_key = BfvSecretKey { s: secret };
    let public_key = BfvPublicKey { b, a };
    let secret_sq = poly_mul_mod(params, &secret_key.s, &secret_key.s);
    let relinearization_key = BfvRelinearizationKey {
        entries: key_switch_entries_bounded_noise_from_rng(
            params,
            &secret_key.s,
            &secret_sq,
            &mut rng,
        )?,
    };
    validate_bounded_noise_public_key_secret_consistency(params, &secret_key, &public_key)?;
    validate_bounded_noise_relinearization_key_secret_consistency(
        params,
        &secret_key,
        &relinearization_key,
    )?;
    Ok((secret_key, public_key, relinearization_key))
}

/// Verify that a rounded BFV public key is consistent with a secret key.
///
/// This key-owner diagnostic checks that `b + a*s` is bounded centered noise,
/// not a plaintext-modulus-multiple residual. It is not a public proof that a
/// published key was honestly generated.
///
/// # Errors
/// Returns [`BfvError`] when key material is malformed or inert, does not match
/// `secret_key`, or exceeds the bounded-noise keygen error profile.
pub fn validate_bounded_noise_public_key_secret_consistency(
    params: &BfvParameters,
    secret_key: &BfvSecretKey,
    public_key: &BfvPublicKey,
) -> Result<(), BfvError> {
    validate_public_key(params, public_key)?;
    validate_public_key_not_all_zero(public_key)?;
    validate_secret_key(params, secret_key)?;
    let residual = poly_add_mod(
        params,
        &public_key.b,
        &poly_mul_mod(params, &public_key.a, &secret_key.s),
    );
    validate_centered_noise_bound(
        params,
        &residual,
        u128::from(BFV_BOUNDED_NOISE_COEFFICIENT_BOUND),
        "bounded-noise public key",
    )
}

/// Verify that a bounded-noise relinearization key matches a secret key.
///
/// # Errors
/// Returns [`BfvError`] when the key shape is malformed or any entry fails to
/// decrypt to raw `base^i * s^2` with the configured small centered error
/// bound.
pub fn validate_bounded_noise_relinearization_key_secret_consistency(
    params: &BfvParameters,
    secret_key: &BfvSecretKey,
    relinearization_key: &BfvRelinearizationKey,
) -> Result<(), BfvError> {
    validate_bounded_noise_relinearization_key_secret_consistency_with_label(
        params,
        secret_key,
        relinearization_key,
        "bounded-noise relinearization key",
    )
}

fn validate_bounded_noise_relinearization_key_secret_consistency_with_label(
    params: &BfvParameters,
    secret_key: &BfvSecretKey,
    relinearization_key: &BfvRelinearizationKey,
    label: &str,
) -> Result<(), BfvError> {
    validate_relinearization_key(params, relinearization_key)?;
    validate_secret_key(params, secret_key)?;
    let secret_square = poly_mul_mod(params, &secret_key.s, &secret_key.s);
    validate_bounded_noise_key_switch_entry_residuals(
        params,
        &secret_key.s,
        &secret_square,
        &relinearization_key.entries,
        label,
    )
}

/// Encrypt a plaintext polynomial from a seed.
///
/// The plaintext is encoded coefficient-wise under the plaintext modulus. The
/// caller may pass fewer than `polynomial_degree` coefficients; the remainder
/// are treated as zero.
///
/// # Errors
/// Returns [`BfvError`] when parameters, plaintext, key shapes, public-key
/// material, or the deterministic seed are invalid.
pub fn encrypt_from_seed(
    params: &BfvParameters,
    public_key: &BfvPublicKey,
    plaintext: &[u64],
    seed: &[u8],
) -> Result<BfvCiphertext, BfvError> {
    validate_plaintext(params, plaintext)?;
    validate_deterministic_seed("BFV encryption seed", seed)?;
    validate_bfv_seeded_encryption_residual_capacity(params)?;
    validate_public_key(params, public_key)?;
    validate_public_key_not_all_zero(public_key)?;

    let encoded_plaintext = encode_plaintext(params, plaintext);
    let mut rng = derive_rng(BFV_ENCRYPT_SEED_DERIVATION_DOMAIN, seed);
    let u = sample_nonzero_small_poly(params, &mut rng);
    let e1 = sample_error_poly(params, &mut rng);
    let e2 = sample_error_poly(params, &mut rng);
    let c0 = poly_add_mod(
        params,
        &poly_add_mod(params, &poly_mul_mod(params, &public_key.b, &u), &e1),
        &encoded_plaintext,
    );
    let c1 = poly_add_mod(params, &poly_mul_mod(params, &public_key.a, &u), &e2);
    Ok(BfvCiphertext { c0, c1 })
}

/// Encrypt a plaintext polynomial with rounded BFV plaintext scaling.
///
/// The plaintext is encoded as `(q / t) * m` in `R_q`, and fresh error
/// coefficients are sampled from a small centered distribution. This is the
/// encryption entry for the pending bounded-noise BFV-RNS path.
///
/// # Errors
/// Returns [`BfvError`] when parameters, plaintext, key shapes, public-key
/// material, rounded-noise capacity, or deterministic seed material are
/// invalid.
pub fn encrypt_bounded_noise_from_seed(
    params: &BfvParameters,
    public_key: &BfvPublicKey,
    plaintext: &[u64],
    seed: &[u8],
) -> Result<BfvCiphertext, BfvError> {
    validate_plaintext(params, plaintext)?;
    validate_deterministic_seed("bounded-noise BFV encryption seed", seed)?;
    validate_bfv_bounded_noise_encryption_capacity(params)?;
    validate_public_key(params, public_key)?;
    validate_public_key_not_all_zero(public_key)?;

    let encoded_plaintext = encode_rounded_plaintext(params, plaintext)?;
    let mut rng = derive_rng(BFV_BOUNDED_NOISE_ENCRYPT_SEED_DERIVATION_DOMAIN, seed);
    let u = sample_nonzero_small_poly(params, &mut rng);
    let e1 = sample_bounded_noise_poly(params, &mut rng);
    let e2 = sample_bounded_noise_poly(params, &mut rng);
    let c0 = poly_add_mod(
        params,
        &poly_add_mod(params, &poly_mul_mod(params, &public_key.b, &u), &e1),
        &encoded_plaintext,
    );
    let c1 = poly_add_mod(params, &poly_mul_mod(params, &public_key.a, &u), &e2);
    Ok(BfvCiphertext { c0, c1 })
}

/// Derive deterministic key-switching material for a BFV Galois automorphism.
///
/// The key switches ciphertexts encrypted under `sigma_k(s)` back to the
/// original secret key `s`, where `sigma_k` maps `x -> x^k` in
/// `Z_q[x] / (x^n + 1)`. This is the deterministic baseline primitive needed
/// before packed slot rotations can be wired through public Galois keys.
///
/// # Errors
/// Returns [`BfvError`] when parameters, secret-key shape, or automorphism
/// power are invalid, or when the deterministic seed is empty or oversized.
pub fn galois_key_from_seed(
    params: &BfvParameters,
    secret_key: &BfvSecretKey,
    automorphism_power: u32,
    seed: &[u8],
) -> Result<BfvGaloisKey, BfvError> {
    params.validate()?;
    validate_galois_automorphism_power(params, automorphism_power)?;
    validate_deterministic_seed("BFV Galois key seed", seed)?;
    validate_secret_key(params, secret_key)?;

    let target_secret = apply_galois_automorphism_poly(params, &secret_key.s, automorphism_power)?;
    let power_bytes = automorphism_power.to_le_bytes();
    let material: [u8; Hash::LENGTH] =
        Hash::new_from_chunks(&[GALOIS_KEYGEN_DOMAIN, power_bytes.as_slice(), seed]).into();
    let mut rng = ChaCha20Rng::from_seed(material);
    let entries = key_switch_entries_from_rng(params, &secret_key.s, &target_secret, &mut rng)?;
    let key = BfvGaloisKey {
        automorphism_power,
        entries,
    };
    validate_galois_key(params, &key)?;
    validate_key_switch_entry_residuals(
        params,
        &secret_key.s,
        &target_secret,
        &key.entries,
        "generated Galois key",
    )?;
    Ok(key)
}

/// Derive deterministic bounded-noise Galois key-switching material.
///
/// The key switches ciphertexts encrypted under `sigma_k(s)` back to the
/// original secret key `s`, with small centered key-switch entry errors for the
/// rounded BFV-RNS migration path.
///
/// # Errors
/// Returns [`BfvError`] when parameters, secret-key shape, automorphism power,
/// or deterministic seed material are invalid.
pub fn galois_key_bounded_noise_from_seed(
    params: &BfvParameters,
    secret_key: &BfvSecretKey,
    automorphism_power: u32,
    seed: &[u8],
) -> Result<BfvGaloisKey, BfvError> {
    validate_galois_automorphism_power(params, automorphism_power)?;
    validate_deterministic_seed("bounded-noise BFV Galois key seed", seed)?;
    validate_bfv_bounded_noise_encryption_capacity(params)?;
    validate_secret_key(params, secret_key)?;

    let target_secret = apply_galois_automorphism_poly(params, &secret_key.s, automorphism_power)?;
    let power_bytes = automorphism_power.to_le_bytes();
    let material: [u8; Hash::LENGTH] = Hash::new_from_chunks(&[
        BOUNDED_NOISE_GALOIS_KEYGEN_DOMAIN,
        power_bytes.as_slice(),
        seed,
    ])
    .into();
    let mut rng = ChaCha20Rng::from_seed(material);
    let entries =
        key_switch_entries_bounded_noise_from_rng(params, &secret_key.s, &target_secret, &mut rng)?;
    let key = BfvGaloisKey {
        automorphism_power,
        entries,
    };
    validate_galois_key(params, &key)?;
    validate_bounded_noise_galois_key_secret_consistency(params, secret_key, &key)?;
    Ok(key)
}

/// Verify that a bounded-noise Galois key matches a secret key.
///
/// # Errors
/// Returns [`BfvError`] when the key shape is malformed, the automorphism power
/// is invalid, or any entry fails to decrypt to raw `base^i * sigma_k(s)` with
/// the configured small centered error bound.
pub fn validate_bounded_noise_galois_key_secret_consistency(
    params: &BfvParameters,
    secret_key: &BfvSecretKey,
    galois_key: &BfvGaloisKey,
) -> Result<(), BfvError> {
    validate_bounded_noise_galois_key_secret_consistency_with_label(
        params,
        secret_key,
        galois_key,
        "bounded-noise Galois key",
    )
}

fn validate_bounded_noise_galois_key_secret_consistency_with_label(
    params: &BfvParameters,
    secret_key: &BfvSecretKey,
    galois_key: &BfvGaloisKey,
    label: &str,
) -> Result<(), BfvError> {
    validate_galois_key(params, galois_key)?;
    validate_secret_key(params, secret_key)?;
    let target_secret =
        apply_galois_automorphism_poly(params, &secret_key.s, galois_key.automorphism_power)?;
    validate_bounded_noise_key_switch_entry_residuals(
        params,
        &secret_key.s,
        &target_secret,
        &galois_key.entries,
        label,
    )
}

/// Apply a packed-polynomial BFV Galois automorphism and key switch back to `s`.
///
/// The returned ciphertext decrypts under the original secret key to the
/// automorphed plaintext polynomial. The operation is deterministic for a fixed
/// input ciphertext and Galois key and does not require the evaluator to hold
/// the secret key.
///
/// # Errors
/// Returns [`BfvError`] when the ciphertext or Galois key does not match the
/// parameter set.
pub fn apply_galois_automorphism_ciphertext(
    params: &BfvParameters,
    galois_key: &BfvGaloisKey,
    ciphertext: &BfvCiphertext,
) -> Result<BfvCiphertext, BfvError> {
    params.validate()?;
    validate_galois_key_metadata(params, galois_key)?;
    validate_galois_key_entries(params, galois_key)?;
    validate_ciphertext(params, ciphertext)?;

    let automorphed_c0 =
        apply_galois_automorphism_poly(params, &ciphertext.c0, galois_key.automorphism_power)?;
    let automorphed_c1 =
        apply_galois_automorphism_poly(params, &ciphertext.c1, galois_key.automorphism_power)?;
    key_switch_from_transformed_secret(
        params,
        &galois_key.entries,
        &automorphed_c0,
        &automorphed_c1,
    )
}

/// Apply a rounded BFV Galois automorphism and bounded-noise key switch back to `s`.
///
/// # Errors
/// Returns [`BfvError`] when the ciphertext or Galois key does not match the
/// parameter set.
pub fn apply_galois_automorphism_ciphertext_bounded_noise(
    params: &BfvParameters,
    galois_key: &BfvGaloisKey,
    ciphertext: &BfvCiphertext,
) -> Result<BfvCiphertext, BfvError> {
    validate_galois_key_metadata(params, galois_key)?;
    validate_bfv_bounded_noise_encryption_capacity(params)?;
    validate_galois_key_entries(params, galois_key)?;
    validate_ciphertext(params, ciphertext)?;

    let automorphed_c0 =
        apply_galois_automorphism_poly(params, &ciphertext.c0, galois_key.automorphism_power)?;
    let automorphed_c1 =
        apply_galois_automorphism_poly(params, &ciphertext.c1, galois_key.automorphism_power)?;
    key_switch_from_transformed_secret(
        params,
        &galois_key.entries,
        &automorphed_c0,
        &automorphed_c1,
    )
}

/// Apply a rounded BFV Galois automorphism through an exact RNS key-switch bridge.
///
/// The ciphertext components are automorphed in scalar `Z_q` representation,
/// then the transformed secret component is key-switched back to `s` through
/// the RNS digit/key-switch path while preserving the bounded-noise key
/// material semantics.
///
/// # Errors
/// Returns [`BfvError`] when rounded BFV capacity is too narrow, the ciphertext
/// or Galois key does not match the parameter set, or the RNS chain is
/// malformed or too narrow for exact key switching.
pub fn apply_galois_automorphism_ciphertext_bounded_noise_rns_exact(
    params: &BfvParameters,
    rns_chain: &BfvRnsModulusChain,
    galois_key: &BfvGaloisKey,
    ciphertext: &BfvCiphertext,
) -> Result<BfvCiphertext, BfvError> {
    validate_galois_key_metadata(params, galois_key)?;
    validate_bounded_noise_rns_evaluator_corridor(params, rns_chain)?;
    validate_galois_key_entries(params, galois_key)?;
    validate_ciphertext(params, ciphertext)?;

    let automorphed_c0 =
        apply_galois_automorphism_poly(params, &ciphertext.c0, galois_key.automorphism_power)?;
    let automorphed_c1 =
        apply_galois_automorphism_poly(params, &ciphertext.c1, galois_key.automorphism_power)?;
    key_switch_from_transformed_secret_rns_exact(
        params,
        rns_chain,
        &galois_key.entries,
        &automorphed_c0,
        &automorphed_c1,
    )
}

/// Apply a rounded BFV Galois automorphism through the registered RNS bridge.
///
/// This compatibility wrapper now delegates to the registered target-limb
/// basis-extension bridge so production registered callers validate the same
/// key-switch decomposition/evaluator-chain corridor as full-bootstrap.
///
/// # Errors
/// Returns [`BfvError`] when the parameter set is not registered, rounded BFV
/// capacity is too narrow, or the ciphertext/Galois key does not match the
/// parameter set.
pub fn apply_galois_automorphism_ciphertext_bounded_noise_registered_rns_exact(
    params: &BfvParameters,
    galois_key: &BfvGaloisKey,
    ciphertext: &BfvCiphertext,
) -> Result<BfvCiphertext, BfvError> {
    apply_galois_automorphism_ciphertext_bounded_noise_registered_rns_basis_extension_exact(
        params, galois_key, ciphertext,
    )
}

/// Apply a rounded BFV Galois automorphism through a target-limb RNS bridge.
///
/// The transformed secret component is decomposed in `decomposition_chain`,
/// target-limb basis-extended into `evaluator_chain`, and then consumed by the
/// RNS key-switch products. This keeps the BFV-RNS basis-extension boundary
/// explicit while preserving deterministic exact scalar semantics.
///
/// # Errors
/// Returns [`BfvError`] when rounded BFV capacity is too narrow, the evaluator
/// chain is too narrow, the decomposition chain is not an evaluator-chain
/// prefix, or the ciphertext/Galois key does not match the parameter set.
pub fn apply_galois_automorphism_ciphertext_bounded_noise_rns_basis_extension_exact(
    params: &BfvParameters,
    decomposition_chain: &BfvRnsModulusChain,
    evaluator_chain: &BfvRnsModulusChain,
    galois_key: &BfvGaloisKey,
    ciphertext: &BfvCiphertext,
) -> Result<BfvCiphertext, BfvError> {
    validate_galois_key_metadata(params, galois_key)?;
    validate_bounded_noise_rns_basis_extension_corridor(
        params,
        decomposition_chain,
        evaluator_chain,
        "bounded-noise RNS Galois decomposition",
    )?;
    validate_galois_key_entries(params, galois_key)?;
    validate_ciphertext(params, ciphertext)?;

    let automorphed_c0 =
        apply_galois_automorphism_poly(params, &ciphertext.c0, galois_key.automorphism_power)?;
    let automorphed_c1 =
        apply_galois_automorphism_poly(params, &ciphertext.c1, galois_key.automorphism_power)?;
    key_switch_from_transformed_secret_rns_exact_with_basis_extension(
        params,
        decomposition_chain,
        evaluator_chain,
        &galois_key.entries,
        &automorphed_c0,
        &automorphed_c1,
    )
}

/// Apply a rounded BFV Galois automorphism through the registered target-limb RNS bridge.
///
/// The evaluator chain and key-switch decomposition chain are derived from the
/// registered production BFV profile, so production callers do not need to pass
/// RNS bases by hand.
///
/// # Errors
/// Returns [`BfvError`] when the parameter set is not registered, rounded BFV
/// capacity is too narrow, or the ciphertext/Galois key does not match the
/// parameter set.
pub fn apply_galois_automorphism_ciphertext_bounded_noise_registered_rns_basis_extension_exact(
    params: &BfvParameters,
    galois_key: &BfvGaloisKey,
    ciphertext: &BfvCiphertext,
) -> Result<BfvCiphertext, BfvError> {
    let evaluator_chain = registered_bfv_rns_modulus_chain(params)?;
    let decomposition_chain =
        registered_bfv_key_switch_decomposition_chain_for_evaluator(params, &evaluator_chain)?;
    apply_galois_automorphism_ciphertext_bounded_noise_rns_basis_extension_exact(
        params,
        &decomposition_chain,
        &evaluator_chain,
        galois_key,
        ciphertext,
    )
}

/// Apply a packed-polynomial BFV Galois automorphism through an exact RNS corridor.
///
/// The ciphertext components are automorphed in the scalar `Z_q` representation,
/// then the transformed secret component is key-switched with guarded exact RNS
/// polynomial products and additions. This is an exact evaluator bridge for
/// sufficiently wide chains, not the final BFV-RNS basis-extension pipeline.
///
/// # Errors
/// Returns [`BfvError`] when the ciphertext or Galois key does not match the
/// parameter set, or when the RNS chain is malformed or too narrow for exact
/// ciphertext-modulus key switching.
pub fn apply_galois_automorphism_ciphertext_rns_exact(
    params: &BfvParameters,
    rns_chain: &BfvRnsModulusChain,
    galois_key: &BfvGaloisKey,
    ciphertext: &BfvCiphertext,
) -> Result<BfvCiphertext, BfvError> {
    params.validate()?;
    validate_rns_exact_evaluator_chain(params, rns_chain)?;
    validate_galois_key_metadata(params, galois_key)?;
    validate_galois_key_entries(params, galois_key)?;
    validate_ciphertext(params, ciphertext)?;

    let automorphed_c0 =
        apply_galois_automorphism_poly(params, &ciphertext.c0, galois_key.automorphism_power)?;
    let automorphed_c1 =
        apply_galois_automorphism_poly(params, &ciphertext.c1, galois_key.automorphism_power)?;
    key_switch_from_transformed_secret_rns_exact(
        params,
        rns_chain,
        &galois_key.entries,
        &automorphed_c0,
        &automorphed_c1,
    )
}

/// Apply a packed-polynomial BFV Galois automorphism through the registered exact RNS corridor.
///
/// The evaluator chain is derived from the registered production BFV profile,
/// so production callers cannot supply an alternate chain with a different
/// public digest.
///
/// # Errors
/// Returns [`BfvError`] when the parameter set is not registered, the
/// ciphertext or Galois key does not match the parameter set, or registered RNS
/// validation fails.
pub fn apply_galois_automorphism_ciphertext_registered_rns_exact(
    params: &BfvParameters,
    galois_key: &BfvGaloisKey,
    ciphertext: &BfvCiphertext,
) -> Result<BfvCiphertext, BfvError> {
    let rns_chain = registered_bfv_rns_modulus_chain(params)?;
    apply_galois_automorphism_ciphertext_rns_exact(params, &rns_chain, galois_key, ciphertext)
}

/// Encode a full BFV packed-slot plaintext into polynomial coefficients.
///
/// The registered RAM-LFE profile has `t = 257` and `n = 64`, so `t = 1 mod
/// 2n` and the plaintext ring splits into `n` CRT slots. This helper performs
/// deterministic interpolation over those CRT points and returns coefficients
/// in `Z_t[x] / (x^n + 1)`, ready to pass to [`encrypt_from_seed`].
///
/// # Errors
/// Returns [`BfvError`] when the parameter set is not batchable, the slot count
/// is not exactly `polynomial_degree`, or any slot is outside the plaintext
/// modulus.
pub fn encode_packed_plaintext_slots(
    params: &BfvParameters,
    slots: &[u64],
) -> Result<Vec<u64>, BfvError> {
    let points = packed_plaintext_evaluation_points(params)?;
    if slots.len() != params.degree() {
        return Err(BfvError::ShapeMismatch(format!(
            "packed plaintext expected {} slots, found {}",
            params.polynomial_degree,
            slots.len()
        )));
    }
    validate_plaintext(params, slots)?;

    let modulus = params.plaintext_modulus;
    let degree = params.degree();
    let mut coefficients = vec![0_u64; degree];
    for (slot_index, (&slot_value, &point)) in slots.iter().zip(&points).enumerate() {
        let mut basis = vec![1_u64];
        let mut denominator = 1_u64;
        for (other_index, &other_point) in points.iter().enumerate() {
            if other_index == slot_index {
                continue;
            }
            basis = multiply_plaintext_linear_factor(&basis, other_point, modulus);
            denominator = mul_mod_u64(
                denominator,
                sub_mod_u64(point, other_point, modulus),
                modulus,
            );
        }
        let inverse_denominator = mod_inv_prime_u64(denominator, modulus).ok_or_else(|| {
            BfvError::InvalidParameters(
                "packed plaintext interpolation denominator is not invertible".to_owned(),
            )
        })?;
        let scale = mul_mod_u64(slot_value, inverse_denominator, modulus);
        for (coefficient, basis_coefficient) in coefficients.iter_mut().zip(&basis) {
            *coefficient = add_mod_u64(
                *coefficient,
                mul_mod_u64(*basis_coefficient, scale, modulus),
                modulus,
            );
        }
    }
    Ok(coefficients)
}

/// Decode a full BFV packed-slot plaintext from polynomial coefficients.
///
/// This is the inverse of [`encode_packed_plaintext_slots`] for batchable
/// parameter sets. It evaluates the plaintext polynomial at the canonical
/// odd-power CRT points in `Z_t`.
///
/// # Errors
/// Returns [`BfvError`] when the parameter set is not batchable, the plaintext
/// coefficient count is not exactly `polynomial_degree`, or any coefficient is
/// outside the plaintext modulus.
pub fn decode_packed_plaintext_slots(
    params: &BfvParameters,
    plaintext: &[u64],
) -> Result<Vec<u64>, BfvError> {
    let points = packed_plaintext_evaluation_points(params)?;
    if plaintext.len() != params.degree() {
        return Err(BfvError::ShapeMismatch(format!(
            "packed plaintext expected {} coefficients, found {}",
            params.polynomial_degree,
            plaintext.len()
        )));
    }
    validate_plaintext(params, plaintext)?;
    Ok(points
        .iter()
        .map(|&point| evaluate_plaintext_polynomial_mod(plaintext, point, params.plaintext_modulus))
        .collect())
}

/// Return the packed-slot permutation induced by a Galois automorphism.
///
/// For the canonical slot order used by [`encode_packed_plaintext_slots`], the
/// returned vector maps each output slot index to the input slot index that
/// appears there after applying `x -> x^k`.
///
/// # Errors
/// Returns [`BfvError`] when the parameter set is not batchable or
/// `automorphism_power` is not a canonical BFV Galois automorphism power.
pub fn packed_galois_slot_permutation(
    params: &BfvParameters,
    automorphism_power: u32,
) -> Result<Vec<usize>, BfvError> {
    packed_plaintext_root(params)?;
    let power = validate_galois_automorphism_power(params, automorphism_power)?;
    let degree = params.degree();
    let cyclotomic_order = degree.checked_mul(2).ok_or_else(|| {
        BfvError::InvalidParameters(
            "BFV packed-slot cyclotomic order exceeds deterministic bounds".to_owned(),
        )
    })?;
    (0..degree)
        .map(|slot| {
            let exponent = slot
                .checked_mul(2)
                .and_then(|value| value.checked_add(1))
                .and_then(|value| value.checked_mul(power))
                .map(|value| value % cyclotomic_order)
                .ok_or_else(|| {
                    BfvError::InvalidParameters(
                        "BFV packed-slot permutation exponent exceeds deterministic bounds"
                            .to_owned(),
                    )
                })?;
            Ok((exponent - 1) / 2)
        })
        .collect()
}

/// Return the Galois automorphism power for a canonical packed-slot left rotation.
///
/// The registered packed slot order is the canonical odd-power CRT order used
/// by [`encode_packed_plaintext_slots`]. Not every cyclic left rotation in that
/// order is representable by one BFV Galois automorphism. This helper searches
/// the deterministic automorphism surface and fails closed when the requested
/// rotation cannot be expressed by a single public Galois key.
///
/// # Errors
/// Returns [`BfvError`] when the parameter set is not batchable, the requested
/// rotation is zero, or no single Galois automorphism matches the requested
/// packed-slot rotation.
pub fn packed_left_rotation_galois_automorphism_power(
    params: &BfvParameters,
    rotation_steps: u32,
) -> Result<u32, BfvError> {
    let degree = params.degree();
    let normalized_steps = normalize_packed_rotation_steps(params, rotation_steps)?;
    let expected = (0..degree)
        .map(|slot| (slot + normalized_steps) % degree)
        .collect::<Vec<_>>();
    for power_u32 in canonical_galois_automorphism_powers(params)? {
        if packed_galois_slot_permutation(params, power_u32)? == expected {
            return Ok(power_u32);
        }
    }
    Err(BfvError::InvalidParameters(format!(
        "packed RotateLeft by {rotation_steps} slots is not representable by one BFV Galois automorphism"
    )))
}

/// Return every Galois automorphism power required for a packed left rotation.
///
/// Single-automorphism rotations return one power. Other rotations return a
/// deterministic ascending key schedule that can be evaluated by masking and
/// summing public Galois-key switched ciphertexts.
///
/// # Errors
/// Returns [`BfvError`] when the parameter set is not batchable or the
/// requested rotation is zero/effectively a full packed-slot cycle.
pub fn packed_left_rotation_galois_automorphism_powers(
    params: &BfvParameters,
    rotation_steps: u32,
) -> Result<Vec<u32>, BfvError> {
    packed_left_rotation_galois_schedule(params, rotation_steps).map(|schedule| {
        schedule
            .into_iter()
            .map(|(automorphism_power, _mask)| automorphism_power)
            .collect()
    })
}

/// Rotate a packed BFV ciphertext left with a public Galois key.
///
/// This applies a canonical packed-slot left rotation only when the requested
/// `rotation_steps` maps to the supplied Galois key. Unsupported rotations fail
/// closed instead of falling back to an unrelated permutation.
///
/// # Errors
/// Returns [`BfvError`] when the rotation is not representable by one Galois
/// automorphism, the key power does not match the requested rotation, or the
/// ciphertext/key material is malformed for the parameter set.
pub fn rotate_packed_ciphertext_slots_left(
    params: &BfvParameters,
    galois_key: &BfvGaloisKey,
    ciphertext: &BfvCiphertext,
    rotation_steps: u32,
) -> Result<BfvCiphertext, BfvError> {
    let expected_power = packed_left_rotation_galois_automorphism_power(params, rotation_steps)?;
    if galois_key.automorphism_power != expected_power {
        return Err(BfvError::InvalidParameters(format!(
            "packed RotateLeft by {rotation_steps} slots requires Galois automorphism power {expected_power}, found {}",
            galois_key.automorphism_power
        )));
    }
    apply_galois_automorphism_ciphertext(params, galois_key, ciphertext)
}

/// Rotate a packed BFV ciphertext left with a public Galois-key schedule.
///
/// This helper supports any non-zero cyclic packed-slot rotation for the
/// canonical CRT slot order. If the rotation is not a single automorphism, it
/// applies every required public Galois key, masks the slots contributed by
/// that automorphism with a packed plaintext selector, and adds the masked
/// ciphertexts. Evaluators never need the BFV secret key.
///
/// # Errors
/// Returns [`BfvError`] when the rotation is invalid, required Galois keys are
/// missing or malformed, or ciphertext/plaintext-mask arithmetic fails.
pub fn rotate_packed_ciphertext_slots_left_with_galois_keys(
    params: &BfvParameters,
    galois_keys: &[BfvGaloisKey],
    ciphertext: &BfvCiphertext,
    rotation_steps: u32,
) -> Result<BfvCiphertext, BfvError> {
    params.validate()?;
    let schedule = packed_left_rotation_galois_schedule(params, rotation_steps)?;
    validate_galois_key_set_metadata(params, galois_keys, "packed RotateLeft")?;
    validate_galois_key_set_entries(params, galois_keys)?;
    validate_ciphertext(params, ciphertext)?;
    let mut output: Option<BfvCiphertext> = None;
    for (automorphism_power, mask_slots) in schedule {
        let galois_key = galois_keys
            .iter()
            .find(|key| key.automorphism_power == automorphism_power)
            .ok_or_else(|| {
                BfvError::InvalidParameters(format!(
                    "missing BFV Galois key for packed RotateLeft automorphism power {automorphism_power}"
                ))
            })?;
        let transformed = apply_galois_automorphism_ciphertext(params, galois_key, ciphertext)?;
        let mask_plaintext = encode_packed_plaintext_slots(params, &mask_slots)?;
        let masked = multiply_plaintext_polynomial(params, &transformed, &mask_plaintext)?;
        output = Some(match output {
            Some(accumulator) => add_ciphertexts(params, &accumulator, &masked)?,
            None => masked,
        });
    }
    output.ok_or_else(|| {
        BfvError::InvalidParameters(
            "packed RotateLeft produced an empty Galois key schedule".to_owned(),
        )
    })
}

/// Rotate a rounded BFV packed ciphertext left with bounded-noise Galois keys.
///
/// This mirrors [`rotate_packed_ciphertext_slots_left_with_galois_keys`] for
/// the rounded BFV-RNS migration path: each scheduled automorphism uses
/// bounded-noise key switching, then a public packed plaintext selector masks
/// the slots contributed by that automorphism before the masked ciphertexts
/// are accumulated.
///
/// # Errors
/// Returns [`BfvError`] when rounded BFV capacity is too narrow, the rotation is
/// invalid, required Galois keys are missing or malformed, or ciphertext/
/// plaintext-mask arithmetic fails.
pub fn rotate_packed_ciphertext_slots_left_with_galois_keys_bounded_noise(
    params: &BfvParameters,
    galois_keys: &[BfvGaloisKey],
    ciphertext: &BfvCiphertext,
    rotation_steps: u32,
) -> Result<BfvCiphertext, BfvError> {
    let schedule = packed_left_rotation_galois_schedule(params, rotation_steps)?;
    validate_galois_key_set_metadata(params, galois_keys, "bounded-noise packed RotateLeft")?;
    validate_bfv_bounded_noise_encryption_capacity(params)?;
    validate_galois_key_set_entries(params, galois_keys)?;
    validate_ciphertext(params, ciphertext)?;
    let mut output: Option<BfvCiphertext> = None;
    for (automorphism_power, mask_slots) in schedule {
        let galois_key = galois_keys
            .iter()
            .find(|key| key.automorphism_power == automorphism_power)
            .ok_or_else(|| {
                BfvError::InvalidParameters(format!(
                    "missing BFV Galois key for bounded-noise packed RotateLeft automorphism power {automorphism_power}"
                ))
            })?;
        let transformed =
            apply_galois_automorphism_ciphertext_bounded_noise(params, galois_key, ciphertext)?;
        let mask_plaintext = encode_packed_plaintext_slots(params, &mask_slots)?;
        let masked =
            multiply_plaintext_polynomial_bounded_noise(params, &transformed, &mask_plaintext)?;
        output = Some(match output {
            Some(accumulator) => add_ciphertexts(params, &accumulator, &masked)?,
            None => masked,
        });
    }
    output.ok_or_else(|| {
        BfvError::InvalidParameters(
            "bounded-noise packed RotateLeft produced an empty Galois key schedule".to_owned(),
        )
    })
}

