/// Build a deterministic BFV full-bootstrap release audit package from governed artifacts.
///
/// This helper derives the v1 machine-checkable report and evidence archive
/// from the governed material and artifacts, signs the record, builds the
/// manifest, and validates the final package against those same artifacts.
/// Production runtime admission still requires externally reviewed
/// report/archive bytes through
/// [`validate_bfv_full_bootstrap_release_audit_package_for_artifacts_trusted_reviewer_and_digest_v1`].
///
/// # Errors
/// Returns [`BfvError`] when reviewer material is malformed, canonical
/// report/archive byte generation fails, package construction fails, or the
/// generated package does not validate against the governed artifacts.
pub fn bfv_full_bootstrap_release_audit_package_for_artifacts_v1(
    params: &BfvParameters,
    material: &BfvFullBootstrapCircuitMaterialV1,
    artifacts: &BfvFullBootstrapCircuitArtifactBundleV1,
    reviewer_id: &str,
    reviewer_private_key: &PrivateKey,
) -> Result<BfvFullBootstrapReleaseAuditPackageV1, BfvError> {
    validate_bfv_full_bootstrap_release_audit_reviewer_id(reviewer_id)?;
    validate_bfv_full_bootstrap_release_audit_reviewer_private_key(
        "BFV full-bootstrap release audit package reviewer private key",
        reviewer_private_key,
    )?;
    let (audit_report_bytes, audit_evidence_archive_bytes) =
        bfv_full_bootstrap_release_audit_report_and_archive_bytes_for_artifacts_v1(
            params, material, artifacts,
        )?;
    bfv_full_bootstrap_release_audit_package_v1(
        params,
        material,
        artifacts,
        &audit_report_bytes,
        &audit_evidence_archive_bytes,
        reviewer_id,
        reviewer_private_key,
    )
}

/// Build a deterministic BFV full-bootstrap release audit package and its digest.
///
/// This helper keeps generated package bytes and their digest paired for
/// deterministic evidence construction. Production runtime contexts must still
/// pin an externally reviewed package accepted by
/// [`validate_bfv_full_bootstrap_release_audit_package_for_artifacts_trusted_reviewer_and_digest_v1`].
///
/// # Errors
/// Returns [`BfvError`] when canonical package construction fails or when the
/// resulting package digest fails validation.
pub fn bfv_full_bootstrap_release_audit_package_and_digest_for_artifacts_v1(
    params: &BfvParameters,
    material: &BfvFullBootstrapCircuitMaterialV1,
    artifacts: &BfvFullBootstrapCircuitArtifactBundleV1,
    reviewer_id: &str,
    reviewer_private_key: &PrivateKey,
) -> Result<(BfvFullBootstrapReleaseAuditPackageV1, Hash), BfvError> {
    let package = bfv_full_bootstrap_release_audit_package_for_artifacts_v1(
        params,
        material,
        artifacts,
        reviewer_id,
        reviewer_private_key,
    )?;
    let package_digest = bfv_full_bootstrap_release_audit_package_digest_v1(&package)?;
    Ok((package, package_digest))
}

/// Validate a BFV full-bootstrap release audit package.
///
/// # Errors
/// Returns [`BfvError`] when the package layout is stale, the record digest is
/// stale, the signed record is malformed, or the report/archive bytes are
/// empty, all-zero, header-only, carry a blank, too-short, all-zero,
/// nested-header, or placeholder body, reuse the same artifact body, oversized,
/// omit required signed commitments or generated-circuit body size/byte evidence,
/// or do not match the signed hashes.
pub fn validate_bfv_full_bootstrap_release_audit_package_v1(
    package: &BfvFullBootstrapReleaseAuditPackageV1,
) -> Result<(), BfvError> {
    if package.version != BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_PACKAGE_VERSION_V1 {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap release audit package version {} does not match canonical version {}",
            package.version, BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_PACKAGE_VERSION_V1
        )));
    }
    if package.field_count != BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_PACKAGE_FIELD_COUNT_V1 {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap release audit package field count {} does not match canonical count {}",
            package.field_count, BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_PACKAGE_FIELD_COUNT_V1
        )));
    }
    validate_bfv_full_bootstrap_release_audit_record_v1(&package.record)?;
    validate_nonzero_material_digest(
        "BFV full-bootstrap release audit package record digest",
        &package.record_digest,
    )?;
    validate_no_full_bootstrap_placeholder_material_digest(
        "BFV full-bootstrap release audit package record digest",
        &package.record_digest,
    )?;
    let expected_record_digest =
        bfv_full_bootstrap_release_audit_record_digest_v1(&package.record)?;
    if package.record_digest != expected_record_digest {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit package record digest mismatch".to_owned(),
        ));
    }
    validate_bfv_full_bootstrap_release_audit_manifest_for_record_v1(
        &package.manifest,
        &package.record,
    )?;
    if package.manifest.record_digest != package.record_digest {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit package manifest record digest mismatch".to_owned(),
        ));
    }
    validate_nonzero_material_digest(
        "BFV full-bootstrap release audit package manifest digest",
        &package.manifest_digest,
    )?;
    validate_no_full_bootstrap_placeholder_material_digest(
        "BFV full-bootstrap release audit package manifest digest",
        &package.manifest_digest,
    )?;
    let expected_manifest_digest =
        bfv_full_bootstrap_release_audit_manifest_digest_v1(&package.manifest)?;
    if package.manifest_digest != expected_manifest_digest {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit package manifest digest mismatch".to_owned(),
        ));
    }
    validate_bfv_full_bootstrap_release_audit_package_report_and_archive_v1(package)
}

fn validate_bfv_full_bootstrap_release_audit_package_report_and_archive_v1(
    package: &BfvFullBootstrapReleaseAuditPackageV1,
) -> Result<(), BfvError> {
    let signoff_payload = &package.record.signoff.payload;
    validate_bfv_full_bootstrap_release_audit_artifact_bytes_v1(
        "BFV full-bootstrap release audit report bytes",
        &package.audit_report_bytes,
        signoff_payload.audit_report_digest,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_REPORT_BODY_MIN_BYTES,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_REPORT_MAX_BYTES,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_REPORT_HEADER_V1,
    )?;
    validate_bfv_full_bootstrap_release_audit_artifact_bytes_v1(
        "BFV full-bootstrap release audit evidence archive bytes",
        &package.audit_evidence_archive_bytes,
        signoff_payload.audit_evidence_archive_digest,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_ARCHIVE_BODY_MIN_BYTES,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_ARCHIVE_MAX_BYTES,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_ARCHIVE_HEADER_V1,
    )?;
    validate_bfv_full_bootstrap_release_audit_artifact_bodies_distinct_v1(
        &package.audit_report_bytes,
        &package.audit_evidence_archive_bytes,
    )?;
    validate_bfv_full_bootstrap_release_audit_report_binds_release_evidence_digest_v1(
        &package.audit_report_bytes,
        &signoff_payload.release_audit_evidence_digest,
    )?;
    validate_bfv_full_bootstrap_release_audit_report_binds_generated_artifact_commitments_v1(
        &package.audit_report_bytes,
        &signoff_payload.circuit_id,
        &signoff_payload.generated_circuit_body_digest,
        &signoff_payload.proof_key_pair_commitment,
        &package.record.evidence.proof_profile,
    )?;
    let archive_commitments = BfvFullBootstrapReleaseAuditArchiveSignedCommitmentsV1 {
        artifact_bundle_digest: &signoff_payload.artifact_bundle_digest,
        evaluator_artifact_set_digest: &signoff_payload.evaluator_artifact_set_digest,
        centered_scale_round_source_chain_digest: &signoff_payload
            .centered_scale_round_source_chain_digest,
        arithmetic_trace_profile_digest: &package.record.evidence.arithmetic_trace_profile_digest,
        arithmetic_air_constraint_system_digest: &package
            .record
            .evidence
            .arithmetic_air_constraint_system_digest,
        coefficient_to_slot_key_digest: &package.record.evidence.coefficient_to_slot_key_digest,
        slot_to_coefficient_key_digest: &package.record.evidence.slot_to_coefficient_key_digest,
        blind_rotation_key_digest: &package.record.evidence.blind_rotation_key_digest,
        sample_extraction_key_digest: &package.record.evidence.sample_extraction_key_digest,
        accumulator_digest: &package.record.evidence.accumulator_digest,
        proof_public_input_schema_digest: &package.record.evidence.proof_public_input_schema_digest,
        arithmetic_air_constraint_system_artifact_digest: &package
            .record
            .evidence
            .arithmetic_air_constraint_system_artifact_digest,
        generated_circuit_body_digest: &signoff_payload.generated_circuit_body_digest,
        native_circuit_fingerprint: &signoff_payload.native_circuit_fingerprint,
        proof_key_pair_commitment: &signoff_payload.proof_key_pair_commitment,
        proof_profile: &package.record.evidence.proof_profile,
        prover_key_digest: &signoff_payload.prover_key_digest,
        verifier_key_digest: &signoff_payload.verifier_key_digest,
    };
    validate_bfv_full_bootstrap_release_audit_archive_binds_signed_commitments_v1(
        &package.audit_evidence_archive_bytes,
        &signoff_payload.circuit_id,
        &archive_commitments,
    )
}

/// Validate a release audit package against a trusted reviewer key.
///
/// # Errors
/// Returns [`BfvError`] when package validation fails or the packaged record was
/// not signed by the caller's trusted reviewer id/key pair.
pub fn validate_bfv_full_bootstrap_release_audit_package_trusted_reviewer_v1(
    package: &BfvFullBootstrapReleaseAuditPackageV1,
    reviewer_id: &str,
    reviewer_public_key: &PublicKey,
) -> Result<(), BfvError> {
    validate_bfv_full_bootstrap_release_audit_trusted_reviewer_inputs_v1(
        reviewer_id,
        reviewer_public_key,
    )?;
    validate_bfv_full_bootstrap_release_audit_package_v1(package)?;
    validate_bfv_full_bootstrap_release_audit_record_trusted_reviewer_v1(
        &package.record,
        reviewer_id,
        reviewer_public_key,
    )?;
    validate_bfv_full_bootstrap_release_audit_manifest_trusted_reviewer_v1(
        &package.manifest,
        reviewer_id,
        reviewer_public_key,
    )
}

/// Validate an audit package against governed material and artifacts.
///
/// # Errors
/// Returns [`BfvError`] when package validation fails or when the packaged
/// record does not match freshly derived release audit evidence.
pub fn validate_bfv_full_bootstrap_release_audit_package_for_artifacts_v1(
    params: &BfvParameters,
    material: &BfvFullBootstrapCircuitMaterialV1,
    artifacts: &BfvFullBootstrapCircuitArtifactBundleV1,
    package: &BfvFullBootstrapReleaseAuditPackageV1,
) -> Result<(), BfvError> {
    validate_bfv_full_bootstrap_release_audit_package_v1(package)?;
    validate_bfv_full_bootstrap_release_audit_archive_binds_governed_artifacts_v1(
        &package.audit_evidence_archive_bytes,
        artifacts,
    )?;
    validate_bfv_full_bootstrap_release_audit_record_for_artifacts_v1(
        params,
        material,
        artifacts,
        &package.record,
    )
}

/// Validate an audit package against governed artifacts and a trusted reviewer.
///
/// # Errors
/// Returns [`BfvError`] when artifact/package validation fails or when the
/// packaged signoff was not issued by the trusted reviewer id/key pair.
pub fn validate_bfv_full_bootstrap_release_audit_package_for_artifacts_and_trusted_reviewer_v1(
    params: &BfvParameters,
    material: &BfvFullBootstrapCircuitMaterialV1,
    artifacts: &BfvFullBootstrapCircuitArtifactBundleV1,
    package: &BfvFullBootstrapReleaseAuditPackageV1,
    reviewer_id: &str,
    reviewer_public_key: &PublicKey,
) -> Result<(), BfvError> {
    validate_bfv_full_bootstrap_release_audit_trusted_reviewer_inputs_v1(
        reviewer_id,
        reviewer_public_key,
    )?;
    validate_bfv_full_bootstrap_release_audit_package_for_artifacts_v1(
        params, material, artifacts, package,
    )?;
    validate_bfv_full_bootstrap_release_audit_package_trusted_reviewer_v1(
        package,
        reviewer_id,
        reviewer_public_key,
    )
}

/// Validate an audit package against governed artifacts, a trusted reviewer,
/// and the caller-pinned package digest.
///
/// # Errors
/// Returns [`BfvError`] when artifact/package validation fails, the packaged
/// signoff was not issued by the trusted reviewer id/key pair, or the package
/// digest differs from or is aliased by the caller-pinned digest. The pinned
/// runtime package must carry externally reviewed report/archive markers and
/// must not use the deterministic machine-generated report/archive bodies.
pub fn validate_bfv_full_bootstrap_release_audit_package_for_artifacts_trusted_reviewer_and_digest_v1(
    params: &BfvParameters,
    material: &BfvFullBootstrapCircuitMaterialV1,
    artifacts: &BfvFullBootstrapCircuitArtifactBundleV1,
    package: &BfvFullBootstrapReleaseAuditPackageV1,
    expected_package_digest: Hash,
    reviewer_id: &str,
    reviewer_public_key: &PublicKey,
) -> Result<(), BfvError> {
    validate_nonzero_material_digest(
        "BFV full-bootstrap release audit caller-pinned package digest",
        &expected_package_digest,
    )?;
    validate_no_full_bootstrap_placeholder_material_digest(
        "BFV full-bootstrap release audit caller-pinned package digest",
        &expected_package_digest,
    )?;
    if expected_package_digest == package.record_digest {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit caller-pinned package digest must be distinct from package record digest"
                .to_owned(),
        ));
    }
    if expected_package_digest == package.manifest_digest {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit caller-pinned package digest must be distinct from package manifest digest"
                .to_owned(),
        ));
    }
    validate_bfv_full_bootstrap_release_audit_caller_pinned_package_digest_distinct_from_signed_commitments_v1(
        package,
        &expected_package_digest,
    )?;
    validate_bfv_full_bootstrap_release_audit_package_for_artifacts_and_trusted_reviewer_v1(
        params,
        material,
        artifacts,
        package,
        reviewer_id,
        reviewer_public_key,
    )?;
    validate_bfv_full_bootstrap_release_audit_package_external_review_markers_v1(package)?;
    let actual_package_digest = bfv_full_bootstrap_release_audit_package_digest_v1(package)?;
    if actual_package_digest != expected_package_digest {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit package digest mismatch".to_owned(),
        ));
    }
    Ok(())
}

/// Validate production external-review markers on a BFV full-bootstrap release audit package.
///
/// # Errors
/// Returns [`BfvError`] when report/archive bytes are malformed, contain
/// machine-generated audit artifact markers, omit the required external-review
/// report/archive markers, omit signed reviewer-id-labelled statement text, or
/// reuse copied report/archive review statements.
pub fn validate_bfv_full_bootstrap_release_audit_package_external_review_markers_v1(
    package: &BfvFullBootstrapReleaseAuditPackageV1,
) -> Result<(), BfvError> {
    let audit_report_body = bfv_full_bootstrap_release_audit_artifact_body_v1(
        "BFV full-bootstrap release audit report bytes",
        &package.audit_report_bytes,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_REPORT_BODY_MIN_BYTES,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_REPORT_HEADER_V1,
    )?;
    let audit_evidence_archive_body = bfv_full_bootstrap_release_audit_artifact_body_v1(
        "BFV full-bootstrap release audit evidence archive bytes",
        &package.audit_evidence_archive_bytes,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_ARCHIVE_BODY_MIN_BYTES,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_ARCHIVE_HEADER_V1,
    )?;
    if bfv_full_bootstrap_release_audit_body_contains_machine_generated_marker_v1(audit_report_body)
        || bfv_full_bootstrap_release_audit_body_contains_machine_generated_marker_v1(
            audit_evidence_archive_body,
        )
    {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit production package must not use machine-generated audit artifact bodies"
                .to_owned(),
        ));
    }
    validate_bfv_full_bootstrap_release_audit_body_starts_with_external_review_marker_v1(
        "BFV full-bootstrap release audit report body",
        audit_report_body,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_REPORT_EXTERNAL_REVIEW_MARKER_V1,
    )?;
    validate_bfv_full_bootstrap_release_audit_body_starts_with_external_review_marker_v1(
        "BFV full-bootstrap release audit evidence archive body",
        audit_evidence_archive_body,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_ARCHIVE_EXTERNAL_REVIEW_MARKER_V1,
    )?;
    validate_bfv_full_bootstrap_release_audit_package_external_review_marker_reviewer_id_v1(
        package,
    )?;
    Ok(())
}

fn validate_bfv_full_bootstrap_release_audit_package_external_review_marker_reviewer_id_v1(
    package: &BfvFullBootstrapReleaseAuditPackageV1,
) -> Result<(), BfvError> {
    let reviewer_id = package.record.signoff.payload.reviewer_id.as_str();
    validate_bfv_full_bootstrap_release_audit_reviewer_id(reviewer_id)?;
    let audit_report_body = bfv_full_bootstrap_release_audit_artifact_body_v1(
        "BFV full-bootstrap release audit report bytes",
        &package.audit_report_bytes,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_REPORT_BODY_MIN_BYTES,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_REPORT_HEADER_V1,
    )?;
    let audit_evidence_archive_body = bfv_full_bootstrap_release_audit_artifact_body_v1(
        "BFV full-bootstrap release audit evidence archive bytes",
        &package.audit_evidence_archive_bytes,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_ARCHIVE_BODY_MIN_BYTES,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_ARCHIVE_HEADER_V1,
    )?;
    validate_bfv_full_bootstrap_release_audit_body_external_review_statement_reviewer_id_v1(
        "BFV full-bootstrap release audit report body",
        audit_report_body,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_REPORT_EXTERNAL_REVIEW_MARKER_V1,
        reviewer_id,
    )?;
    validate_bfv_full_bootstrap_release_audit_body_external_review_statement_reviewer_id_v1(
        "BFV full-bootstrap release audit evidence archive body",
        audit_evidence_archive_body,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_ARCHIVE_EXTERNAL_REVIEW_MARKER_V1,
        reviewer_id,
    )?;
    validate_bfv_full_bootstrap_release_audit_external_review_statements_distinct_v1(
        audit_report_body,
        audit_evidence_archive_body,
    )
}

fn bfv_full_bootstrap_release_audit_body_contains_machine_generated_marker_v1(body: &[u8]) -> bool {
    if bfv_full_bootstrap_release_audit_body_contains_ascii_case_insensitive_v1(
        body,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_MACHINE_GENERATED_MARKER_V1,
    ) {
        return true;
    }
    let collapsed_body = ascii_lower_alnum_collapsed(body);
    ascii_windows_contains(
        &collapsed_body,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_MACHINE_GENERATED_COLLAPSED_MARKER_V1,
    )
}

fn validate_bfv_full_bootstrap_release_audit_body_starts_with_external_review_marker_v1(
    label: &str,
    body: &[u8],
    marker: &[u8],
) -> Result<(), BfvError> {
    let _ =
        bfv_full_bootstrap_release_audit_external_review_marker_statement_v1(label, body, marker)?;
    Ok(())
}

fn validate_bfv_full_bootstrap_release_audit_body_external_review_statement_reviewer_id_v1(
    label: &str,
    body: &[u8],
    marker: &[u8],
    reviewer_id: &str,
) -> Result<(), BfvError> {
    let statement =
        bfv_full_bootstrap_release_audit_external_review_marker_statement_v1(label, body, marker)?;
    validate_bfv_full_bootstrap_release_audit_external_review_statement_reviewer_id_label_v1(
        label,
        statement,
        reviewer_id,
    )
}

fn bfv_full_bootstrap_release_audit_external_review_marker_statement_v1<'a>(
    label: &str,
    body: &'a [u8],
    marker: &[u8],
) -> Result<&'a [u8], BfvError> {
    let marker_text = String::from_utf8_lossy(marker);
    if body.len() <= marker.len()
        || &body[..marker.len()] != marker
        || body.get(marker.len()) != Some(&b':')
    {
        return Err(BfvError::InvalidParameters(format!(
            "{label} must start with {marker_text}: marker"
        )));
    }
    if bfv_full_bootstrap_release_audit_external_review_marker_count_v1(body, marker) != 1 {
        return Err(BfvError::InvalidParameters(format!(
            "{label} must contain exactly one {marker_text}: marker"
        )));
    }
    let statement_start = marker.len() + 1;
    let statement_end = body[statement_start..]
        .iter()
        .position(|byte| matches!(*byte, b';' | b'\n' | b'\r'))
        .map_or(body.len(), |offset| statement_start + offset);
    let statement = &body[statement_start..statement_end];
    validate_bfv_full_bootstrap_release_audit_external_review_statement_printable_ascii_v1(
        label, statement,
    )?;
    if !statement.iter().any(|byte| !byte.is_ascii_whitespace()) {
        return Err(BfvError::InvalidParameters(format!(
            "{label} must include a non-empty external-review statement after the marker"
        )));
    }
    Ok(statement)
}

fn bfv_full_bootstrap_release_audit_external_review_marker_count_v1(
    body: &[u8],
    marker: &[u8],
) -> usize {
    if marker.is_empty() || body.len() <= marker.len() {
        return 0;
    }
    (0..=body.len() - marker.len())
        .filter(|index| {
            let marker_end = *index + marker.len();
            body[*index..marker_end].eq_ignore_ascii_case(marker)
                && bfv_full_bootstrap_release_audit_marker_start_has_token_boundary_v1(body, *index)
                && bfv_full_bootstrap_release_audit_marker_followed_by_colon_v1(body, marker_end)
        })
        .count()
}

fn bfv_full_bootstrap_release_audit_marker_followed_by_colon_v1(
    body: &[u8],
    mut index: usize,
) -> bool {
    while body.get(index) == Some(&b' ') {
        index += 1;
    }
    body.get(index) == Some(&b':')
}

fn validate_bfv_full_bootstrap_release_audit_external_review_statement_printable_ascii_v1(
    label: &str,
    statement: &[u8],
) -> Result<(), BfvError> {
    if statement.iter().any(|byte| !matches!(*byte, b' '..=b'~')) {
        return Err(BfvError::InvalidParameters(format!(
            "{label} external-review statement must be printable ASCII"
        )));
    }
    Ok(())
}

fn bfv_full_bootstrap_release_audit_marker_start_has_token_boundary_v1(
    body: &[u8],
    marker_start: usize,
) -> bool {
    marker_start == 0
        || body
            .get(marker_start - 1)
            .is_none_or(|byte| !bfv_full_bootstrap_release_audit_label_join_byte_v1(*byte))
}

fn validate_bfv_full_bootstrap_release_audit_external_review_statement_reviewer_id_label_v1(
    label: &str,
    statement: &[u8],
    reviewer_id: &str,
) -> Result<(), BfvError> {
    let reviewer_id = reviewer_id.as_bytes();
    let mut reviewer_label_count = 0_u8;
    let mut reviewer_label_matches = false;
    let mut has_review_text = false;

    statement
        .split(|byte| byte.is_ascii_whitespace() || matches!(*byte, b',' | b'(' | b')'))
        .filter(|token| !token.is_empty())
        .try_for_each(|token| -> Result<(), BfvError> {
            if let Some(value) =
                bfv_full_bootstrap_release_audit_external_review_reviewer_id_label_value_v1(token)
            {
                reviewer_label_count = reviewer_label_count.saturating_add(1);
                if reviewer_label_count > 1 {
                    return Err(BfvError::InvalidParameters(format!(
                        "{label} external-review statement must contain exactly one signed reviewer id label"
                    )));
                }
                reviewer_label_matches = value == reviewer_id;
            } else if bfv_full_bootstrap_release_audit_external_review_reviewer_id_label_has_case_drift_v1(token) {
                return Err(BfvError::InvalidParameters(format!(
                    "{label} external-review statement must use lowercase signed reviewer id labels"
                )));
            } else if bfv_full_bootstrap_release_audit_external_review_reviewer_id_label_has_separator_alias_v1(token) {
                return Err(BfvError::InvalidParameters(format!(
                    "{label} external-review statement must use canonical lowercase signed reviewer id labels"
                )));
            } else {
                has_review_text |= token.iter().any(u8::is_ascii_alphanumeric);
            }
            Ok(())
        })?;

    if !reviewer_label_matches {
        return Err(BfvError::InvalidParameters(format!(
            "{label} external-review statement must contain the signed reviewer id"
        )));
    }
    if !has_review_text {
        return Err(BfvError::InvalidParameters(format!(
            "{label} external-review statement must contain review text beyond the signed reviewer id"
        )));
    }
    Ok(())
}

fn validate_bfv_full_bootstrap_release_audit_external_review_statements_distinct_v1(
    audit_report_body: &[u8],
    audit_evidence_archive_body: &[u8],
) -> Result<(), BfvError> {
    let report_statement = bfv_full_bootstrap_release_audit_external_review_marker_statement_v1(
        "BFV full-bootstrap release audit report body",
        audit_report_body,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_REPORT_EXTERNAL_REVIEW_MARKER_V1,
    )?;
    let archive_statement = bfv_full_bootstrap_release_audit_external_review_marker_statement_v1(
        "BFV full-bootstrap release audit evidence archive body",
        audit_evidence_archive_body,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_ARCHIVE_EXTERNAL_REVIEW_MARKER_V1,
    )?;
    let report_review_text =
        bfv_full_bootstrap_release_audit_external_review_statement_review_text_v1(report_statement);
    let archive_review_text =
        bfv_full_bootstrap_release_audit_external_review_statement_review_text_v1(
            archive_statement,
        );
    if !report_review_text.is_empty() && report_review_text == archive_review_text {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit external-review report and evidence archive statements must be distinct after reviewer-id normalization"
                .to_owned(),
        ));
    }
    Ok(())
}

fn bfv_full_bootstrap_release_audit_external_review_statement_review_text_v1(
    statement: &[u8],
) -> Vec<u8> {
    statement
        .split(|byte| byte.is_ascii_whitespace() || matches!(*byte, b',' | b'(' | b')'))
        .filter(|token| {
            !token.is_empty()
                && bfv_full_bootstrap_release_audit_external_review_reviewer_id_label_value_v1(
                    token,
                )
                .is_none()
        })
        .flat_map(|token| {
            token
                .iter()
                .copied()
                .filter(u8::is_ascii_alphanumeric)
                .map(|byte| byte.to_ascii_lowercase())
        })
        .collect()
}

fn bfv_full_bootstrap_release_audit_external_review_reviewer_id_label_value_v1(
    token: &[u8],
) -> Option<&[u8]> {
    token
        .strip_prefix(b"reviewer-id=")
        .or_else(|| token.strip_prefix(b"reviewer="))
        .or_else(|| token.strip_prefix(b"reviewed-by="))
}

fn bfv_full_bootstrap_release_audit_external_review_reviewer_id_label_has_case_drift_v1(
    token: &[u8],
) -> bool {
    [
        b"reviewer-id=".as_slice(),
        b"reviewer=".as_slice(),
        b"reviewed-by=".as_slice(),
    ]
    .into_iter()
    .any(|prefix| {
        token
            .get(..prefix.len())
            .is_some_and(|candidate| candidate.eq_ignore_ascii_case(prefix) && candidate != prefix)
    })
}

fn bfv_full_bootstrap_release_audit_external_review_reviewer_id_label_has_separator_alias_v1(
    token: &[u8],
) -> bool {
    let Some(separator_index) = token.iter().position(|byte| *byte == b'=') else {
        return false;
    };
    let label = &token[..separator_index];
    let normalized_label = ascii_lower_alnum_collapsed(label);
    if normalized_label.is_empty() {
        return false;
    }
    [
        (b"reviewerid".as_slice(), b"reviewer-id".as_slice()),
        (b"reviewer".as_slice(), b"reviewer".as_slice()),
        (b"reviewedby".as_slice(), b"reviewed-by".as_slice()),
    ]
    .into_iter()
    .any(|(normalized, canonical)| {
        normalized_label == normalized
            && label != canonical
            && !label.eq_ignore_ascii_case(canonical)
    })
}

fn validate_bfv_full_bootstrap_release_audit_caller_pinned_package_digest_distinct_from_signed_commitments_v1(
    package: &BfvFullBootstrapReleaseAuditPackageV1,
    expected_package_digest: &Hash,
) -> Result<(), BfvError> {
    let payload = &package.record.signoff.payload;
    let signed_commitments = [
        (
            "signed release evidence digest",
            &payload.release_audit_evidence_digest,
        ),
        (
            "signed centered scale-round source-chain digest",
            &payload.centered_scale_round_source_chain_digest,
        ),
        (
            "signed artifact bundle digest",
            &payload.artifact_bundle_digest,
        ),
        (
            "signed evaluator artifact set digest",
            &payload.evaluator_artifact_set_digest,
        ),
        (
            "signed proof-key pair commitment",
            &payload.proof_key_pair_commitment,
        ),
        ("signed prover-key digest", &payload.prover_key_digest),
        ("signed verifier-key digest", &payload.verifier_key_digest),
        (
            "signed native circuit fingerprint",
            &payload.native_circuit_fingerprint,
        ),
        (
            "signed generated circuit body digest",
            &payload.generated_circuit_body_digest,
        ),
        ("signed audit report digest", &payload.audit_report_digest),
        (
            "signed evidence archive digest",
            &payload.audit_evidence_archive_digest,
        ),
    ];
    for (label, digest) in signed_commitments {
        if expected_package_digest == digest {
            return Err(BfvError::InvalidParameters(format!(
                "BFV full-bootstrap release audit caller-pinned package digest must be distinct from {label}"
            )));
        }
    }
    Ok(())
}

/// Return the digest of a BFV full-bootstrap release audit package.
///
/// # Errors
/// Returns [`BfvError`] when package validation or canonical encoding fails.
pub fn bfv_full_bootstrap_release_audit_package_digest_v1(
    package: &BfvFullBootstrapReleaseAuditPackageV1,
) -> Result<Hash, BfvError> {
    validate_bfv_full_bootstrap_release_audit_package_v1(package)?;
    let bytes = norito::to_bytes(package).map_err(|err| {
        BfvError::InvalidParameters(format!(
            "BFV full-bootstrap release audit package encoding failed: {err}"
        ))
    })?;
    Ok(Hash::new_from_chunks(&[
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_PACKAGE_DIGEST_DOMAIN,
        bytes.as_slice(),
    ]))
}

fn bfv_full_bootstrap_release_audit_artifact_digest_v1(
    label: &str,
    bytes: &[u8],
    min_body_bytes: usize,
    max_bytes: usize,
    expected_header: &[u8],
) -> Result<Hash, BfvError> {
    if bytes.is_empty() {
        return Err(BfvError::InvalidParameters(format!(
            "{label} must not be empty"
        )));
    }
    if bytes.len() > max_bytes {
        return Err(BfvError::InvalidParameters(format!(
            "{label} length {} exceeds maximum {max_bytes}",
            bytes.len()
        )));
    }
    if bytes.iter().all(|byte| *byte == 0) {
        return Err(BfvError::InvalidParameters(format!(
            "{label} must not be all zero"
        )));
    }
    if !bytes.starts_with(expected_header) {
        return Err(BfvError::InvalidParameters(format!(
            "{label} must start with canonical v1 header"
        )));
    }
    let body = &bytes[expected_header.len()..];
    if body.is_empty() {
        return Err(BfvError::InvalidParameters(format!(
            "{label} must include a non-empty body after the canonical v1 header"
        )));
    }
    if body.iter().all(|byte| *byte == 0) {
        return Err(BfvError::InvalidParameters(format!(
            "{label} body must not be all zero"
        )));
    }
    validate_bfv_full_bootstrap_release_audit_artifact_body_not_placeholder_v1(label, body)?;
    validate_bfv_full_bootstrap_release_audit_artifact_body_min_bytes_v1(
        label,
        body,
        min_body_bytes,
    )?;
    validate_bfv_full_bootstrap_release_audit_artifact_body_not_blank_v1(label, body)?;
    validate_bfv_full_bootstrap_release_audit_artifact_body_not_nested_v1(label, body)?;
    Ok(Hash::new(bytes))
}

fn bfv_full_bootstrap_release_audit_append_field(body: &mut String, label: &str, value: &str) {
    body.push_str("; ");
    body.push_str(label);
    body.push('=');
    body.push_str(value);
}

fn bfv_full_bootstrap_release_audit_append_proof_profile_fields_v1(
    body: &mut String,
    proof_profile: &BfvFullBootstrapReleaseAuditProofProfileV1,
) -> Result<(), BfvError> {
    bfv_full_bootstrap_release_audit_append_field(
        body,
        "proof-profile-field-count",
        &proof_profile.field_count.to_string(),
    );
    bfv_full_bootstrap_release_audit_append_field(
        body,
        "proof-profile-requires-canonical-base-transcript-label",
        &proof_profile
            .requires_canonical_base_transcript_label
            .to_string(),
    );
    bfv_full_bootstrap_release_audit_append_field(
        body,
        "proof-profile-rejects-suffixed-transcript-label-aliases",
        &proof_profile
            .rejects_suffixed_transcript_label_aliases
            .to_string(),
    );
    for (label, value) in [
        (
            "proof-profile-proof-input-material-digest-domain",
            proof_profile.proof_input_material_digest_domain.as_slice(),
        ),
        (
            "proof-profile-prover-input-material-digest-domain",
            proof_profile.prover_input_material_digest_domain.as_slice(),
        ),
        (
            "proof-profile-air-evaluation-material-digest-domain",
            proof_profile
                .air_evaluation_material_digest_domain
                .as_slice(),
        ),
        (
            "proof-profile-arithmetic-trace-material-digest-domain",
            proof_profile
                .arithmetic_trace_material_digest_domain
                .as_slice(),
        ),
        (
            "proof-profile-arithmetic-air-constraint-system-digest-domain",
            proof_profile
                .arithmetic_air_constraint_system_digest_domain
                .as_slice(),
        ),
        (
            "proof-profile-proof-key-material-commitment-domain",
            proof_profile
                .proof_key_material_commitment_domain
                .as_slice(),
        ),
        (
            "proof-profile-proof-key-pair-commitment-domain",
            proof_profile.proof_key_pair_commitment_domain.as_slice(),
        ),
    ] {
        let value = std::str::from_utf8(value).map_err(|err| {
            BfvError::InvalidParameters(format!(
                "BFV full-bootstrap release audit proof profile {label} is not UTF-8: {err}"
            ))
        })?;
        bfv_full_bootstrap_release_audit_append_field(body, label, value);
    }
    bfv_full_bootstrap_release_audit_append_field(
        body,
        "proof-profile-separates-release-prover-material-domains",
        &proof_profile
            .separates_release_prover_material_domains
            .to_string(),
    );
    bfv_full_bootstrap_release_audit_append_field(
        body,
        "proof-profile-separates-proof-key-material-and-pair-commitments",
        &proof_profile
            .separates_proof_key_material_and_pair_commitments
            .to_string(),
    );
    Ok(())
}

fn bfv_full_bootstrap_release_audit_artifact_digest_pair_v1(
    audit_report_bytes: &[u8],
    audit_evidence_archive_bytes: &[u8],
) -> Result<(Hash, Hash), BfvError> {
    let audit_report_digest = bfv_full_bootstrap_release_audit_artifact_digest_v1(
        "BFV full-bootstrap release audit report bytes",
        audit_report_bytes,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_REPORT_BODY_MIN_BYTES,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_REPORT_MAX_BYTES,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_REPORT_HEADER_V1,
    )?;
    let audit_evidence_archive_digest = bfv_full_bootstrap_release_audit_artifact_digest_v1(
        "BFV full-bootstrap release audit evidence archive bytes",
        audit_evidence_archive_bytes,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_ARCHIVE_BODY_MIN_BYTES,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_ARCHIVE_MAX_BYTES,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_ARCHIVE_HEADER_V1,
    )?;
    validate_bfv_full_bootstrap_release_audit_artifact_bodies_distinct_v1(
        audit_report_bytes,
        audit_evidence_archive_bytes,
    )?;
    Ok((audit_report_digest, audit_evidence_archive_digest))
}

fn bfv_full_bootstrap_release_audit_artifact_bytes_with_header_v1(
    label: &str,
    body: &[u8],
    min_body_bytes: usize,
    max_bytes: usize,
    expected_header: &[u8],
) -> Result<Vec<u8>, BfvError> {
    if body.is_empty() {
        return Err(BfvError::InvalidParameters(format!(
            "{label} body must not be empty"
        )));
    }
    if body.iter().all(|byte| *byte == 0) {
        return Err(BfvError::InvalidParameters(format!(
            "{label} body must not be all zero"
        )));
    }
    validate_bfv_full_bootstrap_release_audit_artifact_body_not_placeholder_v1(label, body)?;
    validate_bfv_full_bootstrap_release_audit_artifact_body_min_bytes_v1(
        label,
        body,
        min_body_bytes,
    )?;
    validate_bfv_full_bootstrap_release_audit_artifact_body_not_blank_v1(label, body)?;
    validate_bfv_full_bootstrap_release_audit_artifact_body_not_nested_v1(label, body)?;
    let total_len = expected_header
        .len()
        .checked_add(body.len())
        .ok_or_else(|| {
            BfvError::InvalidParameters(format!("{label} length exceeds usize bounds"))
        })?;
    if total_len > max_bytes {
        return Err(BfvError::InvalidParameters(format!(
            "{label} length {total_len} exceeds maximum {max_bytes}"
        )));
    }
    let mut bytes = Vec::with_capacity(total_len);
    bytes.extend_from_slice(expected_header);
    bytes.extend_from_slice(body);
    bfv_full_bootstrap_release_audit_artifact_digest_v1(
        label,
        &bytes,
        min_body_bytes,
        max_bytes,
        expected_header,
    )?;
    Ok(bytes)
}

fn validate_bfv_full_bootstrap_release_audit_artifact_bytes_v1(
    label: &str,
    bytes: &[u8],
    expected_digest: Hash,
    min_body_bytes: usize,
    max_bytes: usize,
    expected_header: &[u8],
) -> Result<(), BfvError> {
    let actual_digest = bfv_full_bootstrap_release_audit_artifact_digest_v1(
        label,
        bytes,
        min_body_bytes,
        max_bytes,
        expected_header,
    )?;
    if actual_digest != expected_digest {
        return Err(BfvError::InvalidParameters(format!(
            "{label} digest mismatch"
        )));
    }
    Ok(())
}

fn validate_bfv_full_bootstrap_release_audit_artifact_bodies_distinct_v1(
    audit_report_bytes: &[u8],
    audit_evidence_archive_bytes: &[u8],
) -> Result<(), BfvError> {
    let audit_report_body = bfv_full_bootstrap_release_audit_artifact_body_v1(
        "BFV full-bootstrap release audit report bytes",
        audit_report_bytes,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_REPORT_BODY_MIN_BYTES,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_REPORT_HEADER_V1,
    )?;
    let audit_evidence_archive_body = bfv_full_bootstrap_release_audit_artifact_body_v1(
        "BFV full-bootstrap release audit evidence archive bytes",
        audit_evidence_archive_bytes,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_ARCHIVE_BODY_MIN_BYTES,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_ARCHIVE_HEADER_V1,
    )?;
    let normalized_report_body =
        bfv_full_bootstrap_release_audit_body_without_edge_whitespace_v1(audit_report_body);
    let normalized_archive_body = bfv_full_bootstrap_release_audit_body_without_edge_whitespace_v1(
        audit_evidence_archive_body,
    );
    if normalized_report_body == normalized_archive_body {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit report body must be distinct from evidence archive body after edge-whitespace normalization"
                .to_owned(),
        ));
    }
    if bfv_full_bootstrap_release_audit_body_without_ascii_whitespace_v1(audit_report_body)
        == bfv_full_bootstrap_release_audit_body_without_ascii_whitespace_v1(
            audit_evidence_archive_body,
        )
    {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit report body must be distinct from evidence archive body after whitespace normalization"
                .to_owned(),
        ));
    }
    let collapsed_report_body = ascii_lower_alnum_collapsed(audit_report_body);
    let collapsed_archive_body = ascii_lower_alnum_collapsed(audit_evidence_archive_body);
    if collapsed_report_body.len()
        >= BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_COPIED_BODY_COLLAPSED_MIN_BYTES
        && collapsed_report_body == collapsed_archive_body
    {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit report body must be distinct from evidence archive body after alphanumeric normalization"
                .to_owned(),
        ));
    }
    Ok(())
}

fn validate_bfv_full_bootstrap_release_audit_report_binds_release_evidence_digest_v1(
    audit_report_bytes: &[u8],
    release_audit_evidence_digest: &Hash,
) -> Result<(), BfvError> {
    let report_body = bfv_full_bootstrap_release_audit_artifact_body_v1(
        "BFV full-bootstrap release audit report bytes",
        audit_report_bytes,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_REPORT_BODY_MIN_BYTES,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_REPORT_HEADER_V1,
    )?;
    let digest_hex = hex::encode(<[u8; Hash::LENGTH]>::from(*release_audit_evidence_digest));
    if bfv_full_bootstrap_release_audit_body_contains_labelled_value_v1(
        report_body,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_REPORT_RELEASE_EVIDENCE_LABEL_ALIASES,
        &[digest_hex.as_bytes()],
    ) {
        return Ok(());
    }
    Err(BfvError::InvalidParameters(
        "BFV full-bootstrap release audit report body must contain the signed release evidence digest"
            .to_owned(),
    ))
}

fn validate_bfv_full_bootstrap_release_audit_report_binds_generated_artifact_commitments_v1(
    audit_report_bytes: &[u8],
    circuit_id: &str,
    generated_circuit_body_digest: &Hash,
    proof_key_pair_commitment: &Hash,
    proof_profile: &BfvFullBootstrapReleaseAuditProofProfileV1,
) -> Result<(), BfvError> {
    let report_body = bfv_full_bootstrap_release_audit_artifact_body_v1(
        "BFV full-bootstrap release audit report bytes",
        audit_report_bytes,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_REPORT_BODY_MIN_BYTES,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_REPORT_HEADER_V1,
    )?;
    let signed_generated_digest_hex =
        hex::encode(<[u8; Hash::LENGTH]>::from(*generated_circuit_body_digest));
    let raw_generated_digest_hex = hex::encode(sha256(
        bfv_full_bootstrap_native_generated_circuit_body_v1(circuit_id)?,
    ));
    if !bfv_full_bootstrap_release_audit_body_contains_labelled_value_v1(
        report_body,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_GENERATED_BODY_DIGEST_LABEL_ALIASES,
        &[
            signed_generated_digest_hex.as_bytes(),
            raw_generated_digest_hex.as_bytes(),
        ],
    ) {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit report body must contain the canonical generated circuit body digest"
                .to_owned(),
        ));
    }
    validate_bfv_full_bootstrap_release_audit_report_contains_hash_v1(
        report_body,
        "proof-key pair commitment",
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_PROOF_KEY_PAIR_LABEL_ALIASES,
        proof_key_pair_commitment,
    )?;
    validate_bfv_full_bootstrap_release_audit_body_binds_proof_profile_obligations_v1(
        report_body,
        "report",
        proof_profile,
    )
}

fn validate_bfv_full_bootstrap_release_audit_report_contains_hash_v1(
    report_body: &[u8],
    label: &str,
    label_aliases: &[&[u8]],
    digest: &Hash,
) -> Result<(), BfvError> {
    let digest_hex = hex::encode(<[u8; Hash::LENGTH]>::from(*digest));
    if bfv_full_bootstrap_release_audit_body_contains_labelled_value_v1(
        report_body,
        label_aliases,
        &[digest_hex.as_bytes()],
    ) {
        return Ok(());
    }
    Err(BfvError::InvalidParameters(format!(
        "BFV full-bootstrap release audit report body must contain the signed {label}"
    )))
}

#[allow(clippy::too_many_lines)]
fn validate_bfv_full_bootstrap_release_audit_body_binds_proof_profile_obligations_v1(
    body: &[u8],
    artifact_label: &str,
    proof_profile: &BfvFullBootstrapReleaseAuditProofProfileV1,
) -> Result<(), BfvError> {
    let field_count = proof_profile.field_count.to_string();
    if !bfv_full_bootstrap_release_audit_body_contains_labelled_value_v1(
        body,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_PROOF_PROFILE_FIELD_COUNT_LABEL_ALIASES,
        &[field_count.as_bytes()],
    ) {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap release audit {artifact_label} body must contain the signed proof profile field count"
        )));
    }
    let requires_base = proof_profile
        .requires_canonical_base_transcript_label
        .to_string();
    if !bfv_full_bootstrap_release_audit_body_contains_labelled_value_v1(
        body,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_PROOF_PROFILE_REQUIRES_BASE_LABEL_ALIASES,
        &[requires_base.as_bytes()],
    ) {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap release audit {artifact_label} body must contain the signed canonical base transcript-label proof-profile obligation"
        )));
    }
    let rejects_suffixed = proof_profile
        .rejects_suffixed_transcript_label_aliases
        .to_string();
    if !bfv_full_bootstrap_release_audit_body_contains_labelled_value_v1(
        body,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_PROOF_PROFILE_REJECTS_SUFFIXED_LABEL_ALIASES,
        &[rejects_suffixed.as_bytes()],
    ) {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap release audit {artifact_label} body must contain the signed suffixed transcript-label proof-profile obligation"
        )));
    }
    for (label, aliases, value) in [
        (
            "proof input material digest domain",
            BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_PROOF_PROFILE_PROOF_INPUT_DOMAIN_LABEL_ALIASES,
            proof_profile.proof_input_material_digest_domain.as_slice(),
        ),
        (
            "prover input material digest domain",
            BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_PROOF_PROFILE_PROVER_INPUT_DOMAIN_LABEL_ALIASES,
            proof_profile.prover_input_material_digest_domain.as_slice(),
        ),
        (
            "AIR evaluation material digest domain",
            BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_PROOF_PROFILE_AIR_EVALUATION_DOMAIN_LABEL_ALIASES,
            proof_profile
                .air_evaluation_material_digest_domain
                .as_slice(),
        ),
        (
            "arithmetic trace material digest domain",
            BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_PROOF_PROFILE_TRACE_MATERIAL_DOMAIN_LABEL_ALIASES,
            proof_profile
                .arithmetic_trace_material_digest_domain
                .as_slice(),
        ),
        (
            "arithmetic AIR constraint-system digest domain",
            BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_PROOF_PROFILE_AIR_CONSTRAINT_DOMAIN_LABEL_ALIASES,
            proof_profile
                .arithmetic_air_constraint_system_digest_domain
                .as_slice(),
        ),
        (
            "proof-key material commitment domain",
            BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_PROOF_PROFILE_PROOF_KEY_MATERIAL_DOMAIN_LABEL_ALIASES,
            proof_profile
                .proof_key_material_commitment_domain
                .as_slice(),
        ),
        (
            "proof-key pair commitment domain",
            BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_PROOF_PROFILE_PROOF_KEY_PAIR_DOMAIN_LABEL_ALIASES,
            proof_profile.proof_key_pair_commitment_domain.as_slice(),
        ),
    ] {
        if !bfv_full_bootstrap_release_audit_body_contains_labelled_value_v1(
            body,
            aliases,
            &[value],
        ) {
            return Err(BfvError::InvalidParameters(format!(
                "BFV full-bootstrap release audit {artifact_label} body must contain the signed proof-profile {label}"
            )));
        }
    }
    let separates_release_prover = proof_profile
        .separates_release_prover_material_domains
        .to_string();
    if !bfv_full_bootstrap_release_audit_body_contains_labelled_value_v1(
        body,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_PROOF_PROFILE_SEPARATES_RELEASE_PROVER_DOMAINS_LABEL_ALIASES,
        &[separates_release_prover.as_bytes()],
    ) {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap release audit {artifact_label} body must contain the signed proof-profile release-prover domain-separation obligation"
        )));
    }
    let separates_proof_key = proof_profile
        .separates_proof_key_material_and_pair_commitments
        .to_string();
    if !bfv_full_bootstrap_release_audit_body_contains_labelled_value_v1(
        body,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_PROOF_PROFILE_SEPARATES_PROOF_KEY_COMMITMENTS_LABEL_ALIASES,
        &[separates_proof_key.as_bytes()],
    ) {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap release audit {artifact_label} body must contain the signed proof-profile proof-key commitment-domain separation obligation"
        )));
    }
    Ok(())
}

struct BfvFullBootstrapReleaseAuditArchiveSignedCommitmentsV1<'a> {
    artifact_bundle_digest: &'a Hash,
    evaluator_artifact_set_digest: &'a Hash,
    centered_scale_round_source_chain_digest: &'a Hash,
    arithmetic_trace_profile_digest: &'a Hash,
    arithmetic_air_constraint_system_digest: &'a Hash,
    coefficient_to_slot_key_digest: &'a Hash,
    slot_to_coefficient_key_digest: &'a Hash,
    blind_rotation_key_digest: &'a Hash,
    sample_extraction_key_digest: &'a Hash,
    accumulator_digest: &'a Hash,
    proof_public_input_schema_digest: &'a Hash,
    arithmetic_air_constraint_system_artifact_digest: &'a Hash,
    generated_circuit_body_digest: &'a Hash,
    native_circuit_fingerprint: &'a Hash,
    proof_key_pair_commitment: &'a Hash,
    proof_profile: &'a BfvFullBootstrapReleaseAuditProofProfileV1,
    prover_key_digest: &'a Hash,
    verifier_key_digest: &'a Hash,
}

fn validate_bfv_full_bootstrap_release_audit_archive_binds_signed_commitments_v1(
    audit_evidence_archive_bytes: &[u8],
    circuit_id: &str,
    commitments: &BfvFullBootstrapReleaseAuditArchiveSignedCommitmentsV1<'_>,
) -> Result<(), BfvError> {
    let archive_body = bfv_full_bootstrap_release_audit_artifact_body_v1(
        "BFV full-bootstrap release audit evidence archive bytes",
        audit_evidence_archive_bytes,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_ARCHIVE_BODY_MIN_BYTES,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_ARCHIVE_HEADER_V1,
    )?;
    validate_bfv_full_bootstrap_release_audit_archive_contains_hash_v1(
        archive_body,
        "artifact bundle digest",
        commitments.artifact_bundle_digest,
    )?;
    validate_bfv_full_bootstrap_release_audit_archive_contains_hash_v1(
        archive_body,
        "evaluator artifact set digest",
        commitments.evaluator_artifact_set_digest,
    )?;
    validate_bfv_full_bootstrap_release_audit_archive_contains_hash_v1(
        archive_body,
        "centered scale-round source-chain digest",
        commitments.centered_scale_round_source_chain_digest,
    )?;
    validate_bfv_full_bootstrap_release_audit_archive_contains_generated_circuit_body_digest_v1(
        archive_body,
        circuit_id,
        commitments.generated_circuit_body_digest,
    )?;
    validate_bfv_full_bootstrap_release_audit_archive_contains_hash_v1(
        archive_body,
        "native circuit fingerprint",
        commitments.native_circuit_fingerprint,
    )?;
    validate_bfv_full_bootstrap_release_audit_archive_contains_hash_v1(
        archive_body,
        "proof-key pair commitment",
        commitments.proof_key_pair_commitment,
    )?;
    validate_bfv_full_bootstrap_release_audit_archive_contains_hash_v1(
        archive_body,
        "prover-key digest",
        commitments.prover_key_digest,
    )?;
    validate_bfv_full_bootstrap_release_audit_archive_contains_hash_v1(
        archive_body,
        "verifier-key digest",
        commitments.verifier_key_digest,
    )?;
    validate_bfv_full_bootstrap_release_audit_archive_contains_generated_circuit_body_length_v1(
        archive_body,
        circuit_id,
    )?;
    validate_bfv_full_bootstrap_release_audit_archive_contains_generated_circuit_body_hex_v1(
        archive_body,
        circuit_id,
    )?;
    validate_bfv_full_bootstrap_release_audit_archive_contains_native_payload_hex_v1(
        archive_body,
        circuit_id,
        BfvFullBootstrapCircuitArtifactRoleV1::ProverKey,
    )?;
    validate_bfv_full_bootstrap_release_audit_archive_contains_native_payload_hex_v1(
        archive_body,
        circuit_id,
        BfvFullBootstrapCircuitArtifactRoleV1::VerifierKey,
    )?;
    validate_bfv_full_bootstrap_release_audit_archive_contains_artifact_hex_digests_v1(
        archive_body,
        commitments,
    )?;
    validate_bfv_full_bootstrap_release_audit_archive_contains_hash_v1(
        archive_body,
        "arithmetic trace profile digest",
        commitments.arithmetic_trace_profile_digest,
    )?;
    validate_bfv_full_bootstrap_release_audit_archive_contains_hash_v1(
        archive_body,
        "arithmetic AIR constraint-system digest",
        commitments.arithmetic_air_constraint_system_digest,
    )?;
    validate_bfv_full_bootstrap_release_audit_body_binds_proof_profile_obligations_v1(
        archive_body,
        "evidence archive",
        commitments.proof_profile,
    )
}

