fn bfv_full_bootstrap_release_audit_archive_label_aliases_v1(
    label: &str,
) -> &'static [&'static [u8]] {
    match label {
        "artifact bundle digest" => {
            BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_ARCHIVE_ARTIFACT_BUNDLE_LABEL_ALIASES
        }
        "evaluator artifact set digest" => {
            BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_ARCHIVE_EVALUATOR_ARTIFACT_SET_LABEL_ALIASES
        }
        "centered scale-round source-chain digest" => {
            BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_ARCHIVE_CENTERED_SOURCE_LABEL_ALIASES
        }
        "arithmetic trace profile digest" => {
            BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_ARCHIVE_TRACE_PROFILE_LABEL_ALIASES
        }
        "arithmetic AIR constraint-system digest" => {
            BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_ARCHIVE_AIR_CONSTRAINT_LABEL_ALIASES
        }
        "native circuit fingerprint" => {
            BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_ARCHIVE_NATIVE_FINGERPRINT_LABEL_ALIASES
        }
        "proof-key pair commitment" => {
            BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_PROOF_KEY_PAIR_LABEL_ALIASES
        }
        "prover-key digest" => {
            BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_ARCHIVE_PROVER_KEY_DIGEST_LABEL_ALIASES
        }
        "verifier-key digest" => {
            BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_ARCHIVE_VERIFIER_KEY_DIGEST_LABEL_ALIASES
        }
        _ => &[],
    }
}

fn bfv_full_bootstrap_release_audit_body_contains_labelled_value_v1(
    body: &[u8],
    label_aliases: &[&[u8]],
    values: &[&[u8]],
) -> bool {
    let mut matching_label_count = 0_usize;
    for label in label_aliases
        .iter()
        .copied()
        .filter(|label| !label.is_empty())
    {
        for (index, window) in body.windows(label.len()).enumerate() {
            if window != label
                || !bfv_full_bootstrap_release_audit_label_has_boundaries_v1(body, index, label)
            {
                continue;
            }
            matching_label_count += 1;
            if matching_label_count > 1 {
                return false;
            }
            let label_end = index + label.len();
            let field_end = body[label_end..]
                .iter()
                .position(|byte| matches!(*byte, b';' | b'\n' | b'\r'))
                .map_or(body.len(), |offset| label_end + offset);
            let Some(value_region) =
                bfv_full_bootstrap_release_audit_label_value_region_v1(body, label_end, field_end)
            else {
                return false;
            };
            if !values.iter().any(|value| {
                !value.is_empty()
                    && bfv_full_bootstrap_release_audit_value_region_starts_with_value_v1(
                        value_region,
                        value,
                    )
            }) {
                return false;
            }
        }
    }
    matching_label_count == 1
}

fn bfv_full_bootstrap_release_audit_label_value_region_v1(
    body: &[u8],
    label_end: usize,
    value_end: usize,
) -> Option<&[u8]> {
    let mut index = label_end;
    while index < value_end && body[index].is_ascii_whitespace() {
        index += 1;
    }
    if index >= value_end || body[index] != b'=' {
        return None;
    }
    index += 1;
    while index < value_end && body[index].is_ascii_whitespace() {
        index += 1;
    }
    Some(&body[index..value_end])
}

fn bfv_full_bootstrap_release_audit_value_without_trailing_whitespace_v1(value: &[u8]) -> &[u8] {
    let end = value
        .iter()
        .rposition(|byte| !byte.is_ascii_whitespace())
        .map_or(0, |index| index + 1);
    &value[..end]
}

fn bfv_full_bootstrap_release_audit_value_region_starts_with_value_v1(
    value_region: &[u8],
    value: &[u8],
) -> bool {
    let Some(candidate) = value_region.get(..value.len()) else {
        return false;
    };
    if candidate != value {
        return false;
    }
    value_region[value.len()..]
        .iter()
        .all(u8::is_ascii_whitespace)
}

fn bfv_full_bootstrap_release_audit_label_has_boundaries_v1(
    body: &[u8],
    label_start: usize,
    label: &[u8],
) -> bool {
    let label_end = label_start.saturating_add(label.len());
    bfv_full_bootstrap_release_audit_label_start_has_field_boundary_v1(body, label_start)
        && body
            .get(label_end)
            .is_none_or(|byte| !bfv_full_bootstrap_release_audit_label_join_byte_v1(*byte))
}

fn bfv_full_bootstrap_release_audit_label_start_has_field_boundary_v1(
    body: &[u8],
    label_start: usize,
) -> bool {
    let mut index = label_start;
    while let Some(previous) = index.checked_sub(1).and_then(|previous| body.get(previous)) {
        if matches!(*previous, b' ' | b'\t' | 0x0b | 0x0c) {
            index -= 1;
            continue;
        }
        return matches!(*previous, b';' | b'\n' | b'\r');
    }
    true
}

fn bfv_full_bootstrap_release_audit_label_join_byte_v1(byte: u8) -> bool {
    byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_')
}

fn bfv_full_bootstrap_release_audit_artifact_body_v1<'a>(
    label: &str,
    bytes: &'a [u8],
    min_body_bytes: usize,
    expected_header: &[u8],
) -> Result<&'a [u8], BfvError> {
    if !bytes.starts_with(expected_header) {
        return Err(BfvError::InvalidParameters(format!(
            "{label} must start with canonical v1 header"
        )));
    }
    let body = &bytes[expected_header.len()..];
    if body.is_empty() {
        return Err(BfvError::InvalidParameters(format!(
            "{label} must include a non-empty body after the canonical v1 header"
        )));
    }
    if body.iter().all(|byte| *byte == 0) {
        return Err(BfvError::InvalidParameters(format!(
            "{label} body must not be all zero"
        )));
    }
    validate_bfv_full_bootstrap_release_audit_artifact_body_min_bytes_v1(
        label,
        body,
        min_body_bytes,
    )?;
    validate_bfv_full_bootstrap_release_audit_artifact_body_not_blank_v1(label, body)?;
    validate_bfv_full_bootstrap_release_audit_artifact_body_not_nested_v1(label, body)?;
    validate_bfv_full_bootstrap_release_audit_artifact_body_not_placeholder_v1(label, body)?;
    Ok(body)
}

fn validate_bfv_full_bootstrap_release_audit_artifact_body_min_bytes_v1(
    label: &str,
    body: &[u8],
    min_body_bytes: usize,
) -> Result<(), BfvError> {
    if body.len() < min_body_bytes {
        return Err(BfvError::InvalidParameters(format!(
            "{label} body length {} is below minimum {min_body_bytes}",
            body.len()
        )));
    }
    Ok(())
}

fn validate_bfv_full_bootstrap_release_audit_artifact_body_not_blank_v1(
    label: &str,
    body: &[u8],
) -> Result<(), BfvError> {
    if body.iter().all(u8::is_ascii_whitespace) {
        return Err(BfvError::InvalidParameters(format!(
            "{label} body must not be blank"
        )));
    }
    Ok(())
}

fn validate_bfv_full_bootstrap_release_audit_artifact_body_not_nested_v1(
    label: &str,
    body: &[u8],
) -> Result<(), BfvError> {
    if [
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_REPORT_HEADER_V1,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_ARCHIVE_HEADER_V1,
    ]
    .iter()
    .any(|nested_header| {
        body.windows(nested_header.len())
            .any(|window| window == *nested_header)
    }) {
        return Err(BfvError::InvalidParameters(format!(
            "{label} body must not contain a canonical audit artifact header"
        )));
    }
    Ok(())
}

fn validate_bfv_full_bootstrap_release_audit_artifact_body_not_placeholder_v1(
    label: &str,
    body: &[u8],
) -> Result<(), BfvError> {
    let body_after_leading_whitespace =
        bfv_full_bootstrap_release_audit_body_after_leading_whitespace_v1(body);
    if bfv_full_bootstrap_release_audit_bytes_contain_placeholder_text_v1(
        body_after_leading_whitespace,
    ) {
        return Err(BfvError::InvalidParameters(format!(
            "{label} body must not contain placeholder audit artifact text"
        )));
    }
    Ok(())
}

fn bfv_full_bootstrap_release_audit_bytes_contain_placeholder_text_v1(bytes: &[u8]) -> bool {
    let tokens = [
        b"placeholder".as_slice(),
        b"replace-before-production".as_slice(),
        b"replace before production".as_slice(),
        b"replace_before_production".as_slice(),
        b"replace-me".as_slice(),
        b"replace me".as_slice(),
        b"replace_me".as_slice(),
        b"changeme".as_slice(),
        b"change-me".as_slice(),
        b"change me".as_slice(),
        b"change_me".as_slice(),
        b"test-only".as_slice(),
        b"test only".as_slice(),
        b"test_only".as_slice(),
        b"your-".as_slice(),
        b"your_".as_slice(),
        b"your audit".as_slice(),
        b"your_audit".as_slice(),
        b"your proof".as_slice(),
        b"your_proof".as_slice(),
        b"not for production".as_slice(),
        b"not-for-production".as_slice(),
        b"not_for_production".as_slice(),
        b"not production ready".as_slice(),
        b"not-production-ready".as_slice(),
        b"not_production_ready".as_slice(),
        b"draft".as_slice(),
        b"draft-only".as_slice(),
        b"draft only".as_slice(),
        b"draft_only".as_slice(),
        b"todo".as_slice(),
        b"dummy".as_slice(),
        b"fake".as_slice(),
        b"stub".as_slice(),
        b"mock".as_slice(),
        b"fixture".as_slice(),
        b"sample".as_slice(),
        b"template".as_slice(),
        b"example".as_slice(),
    ];
    if ascii_case_insensitive_contains_any_token(bytes, &tokens)
        || [b"pending".as_slice(), b"audit".as_slice()]
            .iter()
            .all(|token| {
                bfv_full_bootstrap_release_audit_body_contains_ascii_case_insensitive_v1(
                    bytes, token,
                )
            })
    {
        return true;
    }
    if BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_SEPARATOR_SPELLED_PLACEHOLDER_TOKENS
        .iter()
        .any(|token| ascii_contains_separator_spelled_token(bytes, token))
    {
        return true;
    }

    let collapsed_body = ascii_lower_alnum_collapsed(bytes);
    !collapsed_body.is_empty()
        && (tokens.iter().any(|token| {
            let collapsed_token = ascii_alnum_collapsed(token);
            collapsed_token.len() >= BFV_FULL_BOOTSTRAP_COLLAPSED_PLACEHOLDER_MARKER_MIN_BYTES
                && ascii_windows_contains(&collapsed_body, &collapsed_token)
        }) || [b"pending".as_slice(), b"audit".as_slice()]
            .iter()
            .all(|token| {
                let collapsed_token = ascii_alnum_collapsed(token);
                ascii_windows_contains(&collapsed_body, &collapsed_token)
            }))
}

fn bfv_full_bootstrap_release_audit_body_contains_ascii_case_insensitive_v1(
    body: &[u8],
    token: &[u8],
) -> bool {
    ascii_case_insensitive_contains_any_token(body, &[token])
}

fn ascii_case_insensitive_contains_any_token(body: &[u8], tokens: &[&[u8]]) -> bool {
    if tokens.iter().any(|token| token.is_empty()) {
        return true;
    }
    for (index, byte) in body.iter().copied().enumerate() {
        for token in tokens {
            let token = *token;
            if byte.eq_ignore_ascii_case(&token[0])
                && body
                    .get(index..index.saturating_add(token.len()))
                    .is_some_and(|window| window.eq_ignore_ascii_case(token))
            {
                return true;
            }
        }
    }
    false
}

fn ascii_contains_separator_spelled_token(bytes: &[u8], token: &[u8]) -> bool {
    if token.len() < 2 {
        return false;
    }
    for start in 0..bytes.len() {
        if !bytes[start].eq_ignore_ascii_case(&token[0]) {
            continue;
        }
        if start > 0 && bytes[start - 1].is_ascii_alphanumeric() {
            continue;
        }
        let mut index = start + 1;
        let mut matched = true;
        for &token_byte in &token[1..] {
            let separator_start = index;
            while index < bytes.len() && !bytes[index].is_ascii_alphanumeric() {
                index += 1;
            }
            if index == separator_start
                || index >= bytes.len()
                || !bytes[index].eq_ignore_ascii_case(&token_byte)
            {
                matched = false;
                break;
            }
            index += 1;
        }
        if matched && (index == bytes.len() || !bytes[index].is_ascii_alphanumeric()) {
            return true;
        }
    }
    false
}

fn ascii_lower_alnum_collapsed(bytes: &[u8]) -> Vec<u8> {
    bytes
        .iter()
        .copied()
        .filter(u8::is_ascii_alphanumeric)
        .map(|byte| byte.to_ascii_lowercase())
        .collect()
}

fn bfv_full_bootstrap_release_audit_body_after_leading_whitespace_v1(body: &[u8]) -> &[u8] {
    body.iter()
        .position(|byte| !byte.is_ascii_whitespace())
        .map_or(&[][..], |index| &body[index..])
}

fn bfv_full_bootstrap_release_audit_body_without_edge_whitespace_v1(body: &[u8]) -> &[u8] {
    let start = body
        .iter()
        .position(|byte| !byte.is_ascii_whitespace())
        .unwrap_or(body.len());
    let end = body
        .iter()
        .rposition(|byte| !byte.is_ascii_whitespace())
        .map_or(start, |index| index + 1);
    &body[start..end]
}

fn bfv_full_bootstrap_release_audit_body_without_ascii_whitespace_v1(body: &[u8]) -> Vec<u8> {
    body.iter()
        .copied()
        .filter(|byte| !byte.is_ascii_whitespace())
        .collect()
}

fn bfv_full_bootstrap_release_audit_key_evidence_from_key_v1(
    key_digest: Hash,
    key: &BfvFullBootstrapProofKeyV1,
) -> Result<BfvFullBootstrapReleaseAuditDecodedKeyV1, BfvError> {
    validate_nonzero_material_digest(
        "BFV full-bootstrap release audit proof-key digest",
        &key_digest,
    )?;
    let envelope = decode_bfv_full_bootstrap_proof_key_material_envelope_from_key_v1(key)?;
    let native =
        decode_bfv_full_bootstrap_native_proof_key_material_v1(&envelope.native_key_material)?;
    if key.centered_scale_round_source_chain_digest
        != native.centered_scale_round_source_chain_digest
    {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit key evidence centered scale-round source-chain digest does not match native material"
                .to_owned(),
        ));
    }
    let generated_circuit_body_digest =
        bfv_full_bootstrap_native_generated_circuit_body_digest_from_material_v1(&native)?;
    let evidence = BfvFullBootstrapReleaseAuditKeyEvidenceV1 {
        version: BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_KEY_EVIDENCE_VERSION_V1,
        field_count: BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_KEY_EVIDENCE_FIELD_COUNT_V1,
        key_role: key.key_role,
        key_digest,
        key_material_commitment: key.key_material_commitment,
        centered_scale_round_source_chain_digest: key.centered_scale_round_source_chain_digest,
        native_payload_kind: native.native_payload_kind.clone(),
        native_payload_circuit_id: native.native_payload_circuit_id.clone(),
        native_circuit_fingerprint: native.native_circuit_fingerprint,
        native_payload_digest: native.native_payload_digest,
        generated_circuit_body_digest,
    };
    validate_bfv_full_bootstrap_release_audit_key_evidence_shape_v1(
        "BFV full-bootstrap release audit proof key",
        key.key_role,
        &evidence,
    )?;
    Ok(BfvFullBootstrapReleaseAuditDecodedKeyV1 { evidence, native })
}

fn bfv_full_bootstrap_native_generated_circuit_body_digest_from_material_v1(
    native: &BfvFullBootstrapNativeProofKeyMaterialV1,
) -> Result<[u8; Hash::LENGTH], BfvError> {
    validate_bfv_full_bootstrap_native_proof_key_material_object_v1(native)?;
    match native.key_role {
        BfvFullBootstrapCircuitArtifactRoleV1::ProverKey => {
            let payload = norito::decode_from_bytes::<
                BfvFullBootstrapNativeStarkFriTransparentProverPayloadV1,
            >(&native.native_payload)
            .map_err(|err| {
                BfvError::InvalidParameters(format!(
                    "BFV full-bootstrap native prover generated circuit body payload is invalid: {err}"
                ))
            })?;
            Ok(payload.generated_circuit_body_digest)
        }
        BfvFullBootstrapCircuitArtifactRoleV1::VerifierKey => {
            let payload =
                norito::decode_from_bytes::<BfvFullBootstrapNativeStarkFriVerifyingKeyPayloadV1>(
                    &native.native_payload,
                )
                .map_err(|err| {
                    BfvError::InvalidParameters(format!(
                        "BFV full-bootstrap native verifier generated circuit body payload is invalid: {err}"
                    ))
                })?;
            Ok(payload.generated_circuit_body_digest)
        }
        _ => Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap artifact role {:?} is not a proof-key role",
            native.key_role
        ))),
    }
}

fn bfv_full_bootstrap_release_audit_proof_profile_from_key_and_native_v1(
    key: &BfvFullBootstrapProofKeyV1,
    native: &BfvFullBootstrapNativeProofKeyMaterialV1,
) -> Result<BfvFullBootstrapReleaseAuditProofProfileV1, BfvError> {
    validate_bfv_full_bootstrap_proof_key_profile_v1(key)?;
    validate_bfv_full_bootstrap_native_proof_key_material_object_v1(native)?;
    if key.key_role != native.key_role {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap release audit proof profile native proof-key role {:?} does not match audited key role {:?}",
            native.key_role, key.key_role
        )));
    }
    if key.centered_scale_round_source_chain_digest
        != native.centered_scale_round_source_chain_digest
    {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit proof profile centered scale-round source-chain digest does not match native material"
                .to_owned(),
        ));
    }
    let profile = BfvFullBootstrapReleaseAuditProofProfileV1 {
        version: BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_PROOF_PROFILE_VERSION_V1,
        field_count: BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_PROOF_PROFILE_FIELD_COUNT_V1,
        backend: key.backend.clone(),
        key_format: key.key_format.clone(),
        proof_system: native.proof_system.clone(),
        field: native.field.clone(),
        centered_scale_round_source_chain_digest: key.centered_scale_round_source_chain_digest,
        hash_fn: native.hash_fn,
        n_log2: native.n_log2,
        blowup_log2: native.blowup_log2,
        fold_arity: native.fold_arity,
        queries: native.queries,
        merkle_arity: native.merkle_arity,
        statement_material_version: key.statement_material_version,
        statement_material_field_count: key.statement_material_field_count,
        claim_version: key.claim_version,
        claim_field_count: key.claim_field_count,
        witness_digest_material_version: key.witness_digest_material_version,
        witness_digest_material_field_count: key.witness_digest_material_field_count,
        witness_trace_field_count: key.witness_trace_field_count,
        witness_trace_bounds_field_count: key.witness_trace_bounds_field_count,
        public_input_hash_count: key.public_input_hash_count,
        public_input_hash_bytes: key.public_input_hash_bytes,
        air_evaluation_material_version:
            BFV_FULL_BOOTSTRAP_ARITHMETIC_AIR_EVALUATION_MATERIAL_VERSION_V1,
        air_evaluation_material_field_count:
            BFV_FULL_BOOTSTRAP_ARITHMETIC_AIR_EVALUATION_MATERIAL_FIELD_COUNT_V1,
        proof_input_material_digest_domain:
            BFV_FULL_BOOTSTRAP_EXECUTION_PROOF_INPUT_MATERIAL_DIGEST_DOMAIN.to_vec(),
        prover_input_material_digest_domain:
            BFV_FULL_BOOTSTRAP_EXECUTION_PROVER_INPUT_MATERIAL_DIGEST_DOMAIN.to_vec(),
        air_evaluation_material_digest_domain:
            BFV_FULL_BOOTSTRAP_ARITHMETIC_AIR_EVALUATION_MATERIAL_DIGEST_DOMAIN.to_vec(),
        arithmetic_trace_material_digest_domain:
            BFV_FULL_BOOTSTRAP_ARITHMETIC_TRACE_MATERIAL_DIGEST_DOMAIN.to_vec(),
        arithmetic_air_constraint_system_digest_domain:
            BFV_FULL_BOOTSTRAP_ARITHMETIC_AIR_CONSTRAINT_SYSTEM_DIGEST_DOMAIN.to_vec(),
        separates_release_prover_material_domains: true,
        proof_key_material_commitment_domain:
            BFV_FULL_BOOTSTRAP_PROOF_KEY_MATERIAL_COMMITMENT_DOMAIN.to_vec(),
        proof_key_pair_commitment_domain: BFV_FULL_BOOTSTRAP_PROOF_KEY_PAIR_COMMITMENT_DOMAIN
            .to_vec(),
        separates_proof_key_material_and_pair_commitments: true,
        validates_air_evaluation_material_digest: true,
        validates_air_evaluation_trace_material_digest: true,
        requires_zero_air_composition_values: true,
        supports_exact_residual_multiple: key.supports_exact_residual_multiple,
        supports_bounded_noise: key.supports_bounded_noise,
        validates_artifact_bound_prover_input: key.validates_artifact_bound_prover_input,
        rejects_stale_galois_key_set_replay: key.rejects_stale_galois_key_set_replay,
        rejects_stale_proof_key_artifacts: key.rejects_stale_proof_key_artifacts,
        derives_opening_schedule_from_statement_hash: key
            .derives_opening_schedule_from_statement_hash,
        derives_opening_schedule_from_trace_material_digest: key
            .derives_opening_schedule_from_trace_material_digest,
        bounds_opening_schedule_rejection_sampling: key.bounds_opening_schedule_rejection_sampling,
        validates_transcript_public_padding_openings: key
            .validates_transcript_public_padding_openings,
        requires_canonical_base_transcript_label: key.requires_canonical_base_transcript_label,
        rejects_suffixed_transcript_label_aliases: key.rejects_suffixed_transcript_label_aliases,
        validates_merkle_path_shape: key.validates_merkle_path_shape,
        validates_merkle_path_roots: key.validates_merkle_path_roots,
        validates_fri_query_chain: key.validates_fri_query_chain,
        binds_first_fri_values_to_opened_air_values: key
            .binds_first_fri_values_to_opened_air_values,
        binds_fri_queries_to_air_commitment_roots: key.binds_fri_queries_to_air_commitment_roots,
    };
    validate_bfv_full_bootstrap_release_audit_proof_profile_shape_v1(&profile)?;
    Ok(profile)
}

fn validate_bfv_full_bootstrap_release_audit_signoff_payload_digests_v1(
    payload: &BfvFullBootstrapReleaseAuditSignoffPayloadV1,
) -> Result<(), BfvError> {
    validate_nonzero_material_digest(
        "BFV full-bootstrap release audit signoff evidence digest",
        &payload.release_audit_evidence_digest,
    )?;
    validate_bfv_full_bootstrap_centered_scale_round_source_chain_digest_v1(
        "BFV full-bootstrap release audit signoff centered scale-round source-chain digest",
        &payload.centered_scale_round_source_chain_digest,
    )?;
    validate_nonzero_material_digest(
        "BFV full-bootstrap release audit signoff artifact bundle digest",
        &payload.artifact_bundle_digest,
    )?;
    validate_nonzero_material_digest(
        "BFV full-bootstrap release audit signoff evaluator artifact set digest",
        &payload.evaluator_artifact_set_digest,
    )?;
    validate_nonzero_material_digest(
        "BFV full-bootstrap release audit signoff proof-key pair commitment",
        &payload.proof_key_pair_commitment,
    )?;
    validate_nonzero_material_digest(
        "BFV full-bootstrap release audit signoff prover-key digest",
        &payload.prover_key_digest,
    )?;
    validate_nonzero_material_digest(
        "BFV full-bootstrap release audit signoff verifier-key digest",
        &payload.verifier_key_digest,
    )?;
    validate_bfv_full_bootstrap_release_audit_native_circuit_fingerprint_v1(
        "BFV full-bootstrap release audit signoff native circuit fingerprint",
        &payload.circuit_id,
        &payload.native_circuit_fingerprint,
    )?;
    validate_bfv_full_bootstrap_release_audit_generated_circuit_body_digest_v1(
        "BFV full-bootstrap release audit signoff generated circuit body digest",
        &payload.circuit_id,
        &payload.generated_circuit_body_digest,
    )?;
    validate_bfv_full_bootstrap_release_audit_external_artifact_digest_pair_v1(
        "signoff",
        &payload.audit_report_digest,
        &payload.audit_evidence_archive_digest,
    )?;
    if payload.audit_report_digest == payload.release_audit_evidence_digest
        || payload.audit_evidence_archive_digest == payload.release_audit_evidence_digest
    {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit signoff external audit digests must be distinct from the release evidence digest"
                .to_owned(),
        ));
    }
    let signed_commitments = [
        (
            "release evidence digest",
            &payload.release_audit_evidence_digest,
        ),
        (
            "centered scale-round source-chain digest",
            &payload.centered_scale_round_source_chain_digest,
        ),
        ("artifact bundle digest", &payload.artifact_bundle_digest),
        (
            "evaluator artifact set digest",
            &payload.evaluator_artifact_set_digest,
        ),
        (
            "proof-key pair commitment",
            &payload.proof_key_pair_commitment,
        ),
        ("prover-key digest", &payload.prover_key_digest),
        ("verifier-key digest", &payload.verifier_key_digest),
        (
            "native circuit fingerprint",
            &payload.native_circuit_fingerprint,
        ),
        (
            "generated circuit body digest",
            &payload.generated_circuit_body_digest,
        ),
        ("audit report digest", &payload.audit_report_digest),
        (
            "evidence archive digest",
            &payload.audit_evidence_archive_digest,
        ),
    ];
    validate_no_full_bootstrap_placeholder_release_audit_signed_commitments(
        "signoff",
        &signed_commitments,
    )?;
    validate_distinct_bfv_full_bootstrap_release_audit_signed_commitments(
        "signoff",
        &signed_commitments,
    )
}

fn validate_bfv_full_bootstrap_release_audit_signoff_payload_v1(
    payload: &BfvFullBootstrapReleaseAuditSignoffPayloadV1,
) -> Result<(), BfvError> {
    if payload.version != BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_SIGNOFF_PAYLOAD_VERSION_V1 {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap release audit signoff payload version {} does not match canonical version {}",
            payload.version, BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_SIGNOFF_PAYLOAD_VERSION_V1
        )));
    }
    if payload.field_count != BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_SIGNOFF_PAYLOAD_FIELD_COUNT_V1 {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap release audit signoff payload field count {} does not match canonical count {}",
            payload.field_count, BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_SIGNOFF_PAYLOAD_FIELD_COUNT_V1
        )));
    }
    validate_bfv_full_bootstrap_canonical_circuit_id(
        "BFV full-bootstrap release audit signoff payload circuit id",
        &payload.circuit_id,
    )?;
    validate_bfv_full_bootstrap_release_audit_signoff_payload_digests_v1(payload)?;
    validate_bfv_full_bootstrap_release_audit_reviewer_id(&payload.reviewer_id)?;
    validate_bfv_full_bootstrap_release_audit_reviewer_public_key(
        "BFV full-bootstrap release audit signoff reviewer public key",
        &payload.reviewer_public_key,
    )?;
    Ok(())
}

fn validate_bfv_full_bootstrap_release_audit_signoff_payload_for_evidence_v1(
    payload: &BfvFullBootstrapReleaseAuditSignoffPayloadV1,
    evidence: &BfvFullBootstrapReleaseAuditEvidenceV1,
) -> Result<(), BfvError> {
    validate_bfv_full_bootstrap_release_audit_signoff_payload_v1(payload)?;
    validate_bfv_full_bootstrap_release_audit_evidence_v1(evidence)?;
    let expected_evidence_digest = bfv_full_bootstrap_release_audit_evidence_digest_v1(evidence)?;
    if payload.release_audit_evidence_digest != expected_evidence_digest {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit signoff evidence digest mismatch".to_owned(),
        ));
    }
    if payload.centered_scale_round_source_chain_digest
        != evidence.centered_scale_round_source_chain_digest
    {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit signoff centered scale-round source-chain digest mismatch"
                .to_owned(),
        ));
    }
    if payload.artifact_bundle_digest != evidence.artifact_bundle_digest {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit signoff artifact bundle digest mismatch".to_owned(),
        ));
    }
    if payload.evaluator_artifact_set_digest != evidence.evaluator_artifact_set_digest {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit signoff evaluator artifact set digest mismatch"
                .to_owned(),
        ));
    }
    if payload.proof_key_pair_commitment != evidence.proof_key_pair_commitment {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit signoff proof-key pair commitment mismatch"
                .to_owned(),
        ));
    }
    if payload.prover_key_digest != evidence.prover_key.key_digest {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit signoff prover-key digest mismatch".to_owned(),
        ));
    }
    if payload.verifier_key_digest != evidence.verifier_key.key_digest {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit signoff verifier-key digest mismatch".to_owned(),
        ));
    }
    if payload.native_circuit_fingerprint != evidence.prover_key.native_circuit_fingerprint
        || payload.native_circuit_fingerprint != evidence.verifier_key.native_circuit_fingerprint
    {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit signoff native circuit fingerprint mismatch"
                .to_owned(),
        ));
    }
    let expected_generated_circuit_body_digest =
        Hash::prehashed(evidence.prover_key.generated_circuit_body_digest);
    if payload.generated_circuit_body_digest != expected_generated_circuit_body_digest
        || payload.generated_circuit_body_digest
            != Hash::prehashed(evidence.verifier_key.generated_circuit_body_digest)
    {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit signoff generated circuit body digest mismatch"
                .to_owned(),
        ));
    }
    Ok(())
}

fn validate_bfv_full_bootstrap_release_audit_native_circuit_fingerprint_v1(
    label: &str,
    circuit_id: &str,
    fingerprint: &Hash,
) -> Result<(), BfvError> {
    validate_nonzero_material_digest(label, fingerprint)?;
    validate_no_full_bootstrap_placeholder_material_digest(label, fingerprint)?;
    let expected_fingerprint = bfv_full_bootstrap_native_proof_circuit_fingerprint_v1(circuit_id)?;
    if *fingerprint != expected_fingerprint {
        return Err(BfvError::InvalidParameters(format!("{label} mismatch")));
    }
    Ok(())
}

fn validate_bfv_full_bootstrap_release_audit_generated_circuit_body_digest_v1(
    label: &str,
    circuit_id: &str,
    digest: &Hash,
) -> Result<(), BfvError> {
    validate_nonzero_material_digest(label, digest)?;
    validate_no_full_bootstrap_placeholder_material_digest(label, digest)?;
    validate_no_bfv_full_bootstrap_inert_generated_circuit_body_sha256_digest(
        label,
        &<[u8; Hash::LENGTH]>::from(*digest),
    )?;
    let expected_generated_circuit_body =
        bfv_full_bootstrap_native_generated_circuit_body_v1(circuit_id)
            .map_err(|err| BfvError::InvalidParameters(format!("{label} mismatch: {err}")))?;
    let expected_digest = Hash::prehashed(sha256(&expected_generated_circuit_body));
    if *digest != expected_digest {
        return Err(BfvError::InvalidParameters(format!("{label} mismatch")));
    }
    Ok(())
}

fn validate_bfv_full_bootstrap_release_audit_external_artifact_digest_v1(
    label: &str,
    digest: &Hash,
    artifact_header: &[u8],
    min_body_bytes: usize,
) -> Result<(), BfvError> {
    if let Some(sentinels) = bfv_full_bootstrap_release_audit_inert_artifact_digests_for_header_v1(
        artifact_header,
        min_body_bytes,
    ) {
        if let Some((_, error)) = sentinels.iter().find(|(sentinel, _)| sentinel == digest) {
            return Err(BfvError::InvalidParameters(format!(
                "{label} must not identify {error}"
            )));
        }
        if is_bfv_full_bootstrap_release_audit_placeholder_artifact_digest_v1(
            digest,
            artifact_header,
        ) {
            return Err(BfvError::InvalidParameters(format!(
                "{label} must not identify a placeholder audit artifact"
            )));
        }
        return Ok(());
    }

    if *digest == Hash::new(artifact_header) {
        return Err(BfvError::InvalidParameters(format!(
            "{label} must not identify a header-only audit artifact"
        )));
    }
    for nested_header in [
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_REPORT_HEADER_V1,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_ARCHIVE_HEADER_V1,
    ] {
        for nested_prefix in BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_NESTED_HEADER_DIGEST_PREFIXES {
            let mut header_wrapped_header = Vec::with_capacity(
                artifact_header.len() + nested_prefix.len() + nested_header.len(),
            );
            header_wrapped_header.extend_from_slice(artifact_header);
            header_wrapped_header.extend_from_slice(nested_prefix);
            header_wrapped_header.extend_from_slice(nested_header);
            if *digest == Hash::new(&header_wrapped_header) {
                let qualifier = if nested_prefix.is_empty() {
                    "nested-header"
                } else if nested_prefix.iter().all(u8::is_ascii_whitespace) {
                    "whitespace-prefixed nested-header"
                } else {
                    "delayed nested-header"
                };
                return Err(BfvError::InvalidParameters(format!(
                    "{label} must not identify a {qualifier} audit artifact"
                )));
            }
        }
    }
    for body_len in bfv_full_bootstrap_release_audit_inert_body_digest_lengths_v1(min_body_bytes) {
        let zero_body = vec![0_u8; body_len];
        if *digest == Hash::new_from_chunks(&[artifact_header, zero_body.as_slice()]) {
            return Err(BfvError::InvalidParameters(format!(
                "{label} must not identify a zero-body audit artifact"
            )));
        }
        for blank_byte in BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_BLANK_BODY_DIGEST_BYTES {
            let blank_body = vec![*blank_byte; body_len];
            if *digest != Hash::new_from_chunks(&[artifact_header, blank_body.as_slice()]) {
                continue;
            }
            return Err(BfvError::InvalidParameters(format!(
                "{label} must not identify a blank-body audit artifact"
            )));
        }
    }
    if is_bfv_full_bootstrap_release_audit_placeholder_artifact_digest_v1(digest, artifact_header) {
        return Err(BfvError::InvalidParameters(format!(
            "{label} must not identify a placeholder audit artifact"
        )));
    }
    Ok(())
}

fn validate_distinct_bfv_full_bootstrap_release_audit_signed_commitments(
    context: &str,
    commitments: &[(&str, &Hash)],
) -> Result<(), BfvError> {
    for (index, (label, commitment)) in commitments.iter().enumerate() {
        if let Some((prior_label, _)) = commitments[..index]
            .iter()
            .find(|(_, prior)| *prior == *commitment)
        {
            return Err(BfvError::InvalidParameters(format!(
                "BFV full-bootstrap release audit {context} {label} must be distinct from {prior_label}"
            )));
        }
    }
    Ok(())
}

fn validate_bfv_full_bootstrap_release_audit_external_artifact_digest_pair_v1(
    context: &str,
    audit_report_digest: &Hash,
    audit_evidence_archive_digest: &Hash,
) -> Result<(), BfvError> {
    let report_label = format!("BFV full-bootstrap release audit {context} report digest");
    validate_nonzero_material_digest(&report_label, audit_report_digest)?;
    validate_bfv_full_bootstrap_release_audit_external_artifact_digest_v1(
        &report_label,
        audit_report_digest,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_REPORT_HEADER_V1,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_REPORT_BODY_MIN_BYTES,
    )?;
    let archive_label =
        format!("BFV full-bootstrap release audit {context} evidence archive digest");
    validate_nonzero_material_digest(&archive_label, audit_evidence_archive_digest)?;
    validate_bfv_full_bootstrap_release_audit_external_artifact_digest_v1(
        &archive_label,
        audit_evidence_archive_digest,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_ARCHIVE_HEADER_V1,
        BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_ARCHIVE_BODY_MIN_BYTES,
    )?;
    if audit_report_digest == audit_evidence_archive_digest {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap release audit {context} report and evidence archive digests must be distinct"
        )));
    }
    Ok(())
}

fn validate_bfv_full_bootstrap_release_audit_reviewer_id(
    reviewer_id: &str,
) -> Result<(), BfvError> {
    if reviewer_id.is_empty() {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit reviewer id must not be empty".to_owned(),
        ));
    }
    if reviewer_id.len() > BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_REVIEWER_ID_MAX_BYTES {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap release audit reviewer id exceeds the maximum supported length {BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_REVIEWER_ID_MAX_BYTES}"
        )));
    }
    if reviewer_id.trim() != reviewer_id {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit reviewer id must be canonical without surrounding whitespace"
                .to_owned(),
        ));
    }
    if !reviewer_id.bytes().all(|byte| byte.is_ascii_graphic()) {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit reviewer id must contain only printable ASCII bytes without whitespace"
                .to_owned(),
        ));
    }
    if bfv_full_bootstrap_release_audit_bytes_contain_placeholder_text_v1(reviewer_id.as_bytes()) {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit reviewer id must not contain placeholder audit text"
                .to_owned(),
        ));
    }
    if BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_REVIEWER_ID_PLACEHOLDER_TOKENS
        .iter()
        .any(|token| {
            bfv_full_bootstrap_release_audit_body_contains_ascii_case_insensitive_v1(
                reviewer_id.as_bytes(),
                token,
            )
        })
    {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit reviewer id must not contain non-production reviewer placeholder text"
                .to_owned(),
        ));
    }
    Ok(())
}

fn validate_no_full_bootstrap_placeholder_release_audit_signed_commitments(
    context: &str,
    commitments: &[(&str, &Hash)],
) -> Result<(), BfvError> {
    for (label, commitment) in commitments {
        let full_label = format!("BFV full-bootstrap release audit {context} {label}");
        validate_no_full_bootstrap_placeholder_material_digest(&full_label, commitment)?;
    }
    Ok(())
}

fn validate_bfv_full_bootstrap_release_audit_trusted_reviewer_inputs_v1(
    reviewer_id: &str,
    reviewer_public_key: &PublicKey,
) -> Result<(), BfvError> {
    validate_bfv_full_bootstrap_release_audit_reviewer_id(reviewer_id)?;
    validate_bfv_full_bootstrap_release_audit_reviewer_public_key(
        "BFV full-bootstrap release audit trusted reviewer public key",
        reviewer_public_key,
    )
}

/// Validate a trusted reviewer id for a BFV full-bootstrap release audit.
///
/// # Errors
/// Returns [`BfvError`] when the reviewer id is empty, non-canonical,
/// non-printable, too long, or carries placeholder/non-production marker text.
pub fn validate_bfv_full_bootstrap_release_audit_trusted_reviewer_id_v1(
    reviewer_id: &str,
) -> Result<(), BfvError> {
    validate_bfv_full_bootstrap_release_audit_reviewer_id(reviewer_id)
}

/// Validate a trusted reviewer public key for a BFV full-bootstrap release audit.
///
/// # Errors
/// Returns [`BfvError`] when the reviewer key is malformed, empty, all-zero, or
/// not an Ed25519 public key.
pub fn validate_bfv_full_bootstrap_release_audit_trusted_reviewer_public_key_v1(
    reviewer_public_key: &PublicKey,
) -> Result<(), BfvError> {
    validate_bfv_full_bootstrap_release_audit_reviewer_public_key(
        "BFV full-bootstrap release audit trusted reviewer public key",
        reviewer_public_key,
    )
}

fn validate_bfv_full_bootstrap_release_audit_reviewer_private_key(
    label: &str,
    reviewer_private_key: &PrivateKey,
) -> Result<(), BfvError> {
    let (algorithm, payload) = reviewer_private_key
        .try_to_bytes()
        .map_err(|err| BfvError::InvalidParameters(format!("{label} is invalid: {err}")))?;
    if algorithm != Algorithm::Ed25519 {
        return Err(BfvError::InvalidParameters(format!(
            "{label} must use Ed25519 reviewer private-key algorithm, found {algorithm}"
        )));
    }
    if payload.is_empty() {
        return Err(BfvError::InvalidParameters(format!(
            "{label} payload must not be empty"
        )));
    }
    if payload.iter().all(|byte| *byte == 0) {
        return Err(BfvError::InvalidParameters(format!(
            "{label} payload must not be all zero"
        )));
    }
    PrivateKey::from_bytes(algorithm, &payload)
        .map(|_| ())
        .map_err(|err| BfvError::InvalidParameters(format!("{label} is invalid: {err}")))
}

fn validate_bfv_full_bootstrap_release_audit_reviewer_public_key(
    label: &str,
    reviewer_public_key: &PublicKey,
) -> Result<(), BfvError> {
    let (algorithm, payload) = reviewer_public_key
        .try_to_bytes()
        .map_err(|err| BfvError::InvalidParameters(format!("{label} is invalid: {err}")))?;
    if algorithm != Algorithm::Ed25519 {
        return Err(BfvError::InvalidParameters(format!(
            "{label} must use Ed25519 reviewer key algorithm, found {algorithm}"
        )));
    }
    if payload.is_empty() {
        return Err(BfvError::InvalidParameters(format!(
            "{label} payload must not be empty"
        )));
    }
    if payload.iter().all(|byte| *byte == 0) {
        return Err(BfvError::InvalidParameters(format!(
            "{label} payload must not be all zero"
        )));
    }
    PublicKey::from_bytes(algorithm, payload)
        .map(|_| ())
        .map_err(|err| BfvError::InvalidParameters(format!("{label} is invalid: {err}")))
}

#[allow(clippy::too_many_lines)]
fn validate_bfv_full_bootstrap_release_audit_evidence_shape_v1(
    evidence: &BfvFullBootstrapReleaseAuditEvidenceV1,
) -> Result<(), BfvError> {
    if evidence.version != BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_EVIDENCE_VERSION_V1 {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap release audit evidence version {} does not match canonical version {}",
            evidence.version, BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_EVIDENCE_VERSION_V1
        )));
    }
    if evidence.field_count != BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_EVIDENCE_FIELD_COUNT_V1 {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap release audit evidence field count {} does not match canonical count {}",
            evidence.field_count, BFV_FULL_BOOTSTRAP_RELEASE_AUDIT_EVIDENCE_FIELD_COUNT_V1
        )));
    }
    validate_bfv_full_bootstrap_canonical_circuit_id(
        "BFV full-bootstrap release audit evidence circuit id",
        &evidence.circuit_id,
    )?;
    if evidence.max_bootstrap_depth == 0 {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit evidence max_bootstrap_depth must be greater than zero"
                .to_owned(),
        ));
    }
    if evidence.max_bootstrap_depth > BFV_FULL_BOOTSTRAP_MAX_CIRCUIT_DEPTH {
        return Err(BfvError::InvalidParameters(format!(
            "BFV full-bootstrap release audit evidence max_bootstrap_depth exceeds supported limit {BFV_FULL_BOOTSTRAP_MAX_CIRCUIT_DEPTH}"
        )));
    }
    validate_bfv_full_bootstrap_release_audit_proof_profile_shape_v1(&evidence.proof_profile)?;
    validate_bfv_full_bootstrap_release_audit_key_evidence_shape_v1(
        "BFV full-bootstrap release audit prover key",
        BfvFullBootstrapCircuitArtifactRoleV1::ProverKey,
        &evidence.prover_key,
    )?;
    validate_bfv_full_bootstrap_release_audit_key_evidence_shape_v1(
        "BFV full-bootstrap release audit verifier key",
        BfvFullBootstrapCircuitArtifactRoleV1::VerifierKey,
        &evidence.verifier_key,
    )?;
    if evidence.prover_key.key_digest == evidence.verifier_key.key_digest
        || evidence.prover_key.key_material_commitment
            == evidence.verifier_key.key_material_commitment
        || evidence.prover_key.native_payload_digest == evidence.verifier_key.native_payload_digest
    {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit evidence prover and verifier key material must be distinct"
                .to_owned(),
        ));
    }
    if evidence.prover_key.native_payload_circuit_id
        != evidence.verifier_key.native_payload_circuit_id
    {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit evidence native proof-key circuit id does not match"
                .to_owned(),
        ));
    }
    if evidence.prover_key.native_circuit_fingerprint
        != evidence.verifier_key.native_circuit_fingerprint
    {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit evidence native proof-key circuit fingerprint does not match"
                .to_owned(),
        ));
    }
    if evidence.prover_key.generated_circuit_body_digest
        != evidence.verifier_key.generated_circuit_body_digest
    {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit evidence generated circuit body digest does not match"
                .to_owned(),
        ));
    }
    validate_no_full_bootstrap_placeholder_release_audit_evidence_digests(evidence)?;
    validate_nonzero_material_digest(
        "BFV full-bootstrap release audit parameter digest",
        &evidence.parameter_digest,
    )?;
    validate_nonzero_material_digest(
        "BFV full-bootstrap release audit RNS modulus-chain digest",
        &evidence.rns_modulus_chain_digest,
    )?;
    validate_nonzero_material_digest(
        "BFV full-bootstrap release audit key-switch decomposition-chain digest",
        &evidence.key_switch_decomposition_chain_digest,
    )?;
    validate_nonzero_material_digest(
        "BFV full-bootstrap release audit centered scale-round source-chain digest",
        &evidence.centered_scale_round_source_chain_digest,
    )?;
    if evidence.centered_scale_round_source_chain_digest
        != evidence
            .proof_profile
            .centered_scale_round_source_chain_digest
    {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit proof profile centered scale-round source-chain digest does not match evidence"
                .to_owned(),
        ));
    }
    if evidence.centered_scale_round_source_chain_digest
        != evidence.prover_key.centered_scale_round_source_chain_digest
        || evidence.centered_scale_round_source_chain_digest
            != evidence
                .verifier_key
                .centered_scale_round_source_chain_digest
    {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit key evidence centered scale-round source-chain digest does not match evidence"
                .to_owned(),
        ));
    }
    validate_nonzero_material_digest(
        "BFV full-bootstrap release audit artifact bundle digest",
        &evidence.artifact_bundle_digest,
    )?;
    validate_nonzero_material_digest(
        "BFV full-bootstrap release audit evaluator artifact set digest",
        &evidence.evaluator_artifact_set_digest,
    )?;
    validate_nonzero_material_digest(
        "BFV full-bootstrap release audit coefficient-to-slot artifact digest",
        &evidence.coefficient_to_slot_key_digest,
    )?;
    validate_nonzero_material_digest(
        "BFV full-bootstrap release audit slot-to-coefficient artifact digest",
        &evidence.slot_to_coefficient_key_digest,
    )?;
    validate_nonzero_material_digest(
        "BFV full-bootstrap release audit blind-rotation artifact digest",
        &evidence.blind_rotation_key_digest,
    )?;
    validate_nonzero_material_digest(
        "BFV full-bootstrap release audit sample-extraction artifact digest",
        &evidence.sample_extraction_key_digest,
    )?;
    validate_nonzero_material_digest(
        "BFV full-bootstrap release audit accumulator artifact digest",
        &evidence.accumulator_digest,
    )?;
    validate_nonzero_material_digest(
        "BFV full-bootstrap release audit proof public-input schema digest",
        &evidence.proof_public_input_schema_digest,
    )?;
    validate_bfv_full_bootstrap_arithmetic_trace_profile_digest_v1(
        "BFV full-bootstrap release audit arithmetic trace profile digest",
        &evidence.arithmetic_trace_profile_digest,
    )?;
    validate_bfv_full_bootstrap_arithmetic_air_constraint_system_digest_v1(
        "BFV full-bootstrap release audit arithmetic AIR constraint-system digest",
        &evidence.arithmetic_air_constraint_system_digest,
    )?;
    validate_nonzero_material_digest(
        "BFV full-bootstrap release audit arithmetic AIR artifact digest",
        &evidence.arithmetic_air_constraint_system_artifact_digest,
    )?;
    validate_nonzero_material_digest(
        "BFV full-bootstrap release audit proof-key pair commitment",
        &evidence.proof_key_pair_commitment,
    )?;
    validate_bfv_full_bootstrap_release_audit_registered_profile_digests_v1(evidence)?;
    validate_distinct_bfv_full_bootstrap_release_audit_evidence_digests(evidence)?;
    validate_bfv_full_bootstrap_release_audit_evidence_recomputed_digests_v1(evidence)
}

fn validate_bfv_full_bootstrap_release_audit_evidence_recomputed_digests_v1(
    evidence: &BfvFullBootstrapReleaseAuditEvidenceV1,
) -> Result<(), BfvError> {
    let expected_evaluator_artifact_set_digest =
        hash_bfv_full_bootstrap_evaluator_artifact_set_digest_material_v1(
            &BfvFullBootstrapEvaluatorArtifactSetDigestMaterialV1 {
                version: BFV_FULL_BOOTSTRAP_EVALUATOR_ARTIFACT_SET_DIGEST_MATERIAL_VERSION_V1,
                field_count: BFV_FULL_BOOTSTRAP_EVALUATOR_ARTIFACT_SET_DIGEST_MATERIAL_FIELD_COUNT_V1,
                evaluator_artifact_digest_count:
                    BFV_FULL_BOOTSTRAP_EVALUATOR_ARTIFACT_SET_DIGEST_MATERIAL_ARTIFACT_DIGEST_COUNT_V1,
                circuit_id: evidence.circuit_id.clone(),
                parameter_digest: evidence.parameter_digest,
                rns_modulus_chain_digest: evidence.rns_modulus_chain_digest,
                key_switch_decomposition_chain_digest: evidence
                    .key_switch_decomposition_chain_digest,
                centered_scale_round_source_chain_digest: evidence
                    .centered_scale_round_source_chain_digest,
                max_bootstrap_depth: evidence.max_bootstrap_depth,
                coefficient_to_slot_key_digest: evidence.coefficient_to_slot_key_digest,
                slot_to_coefficient_key_digest: evidence.slot_to_coefficient_key_digest,
                blind_rotation_key_digest: evidence.blind_rotation_key_digest,
                sample_extraction_key_digest: evidence.sample_extraction_key_digest,
                accumulator_digest: evidence.accumulator_digest,
                proof_public_input_schema_digest: evidence.proof_public_input_schema_digest,
                arithmetic_air_constraint_system_artifact_digest: evidence
                    .arithmetic_air_constraint_system_artifact_digest,
                arithmetic_air_constraint_system_digest: evidence
                    .arithmetic_air_constraint_system_digest,
            },
        )?;
    if evidence.evaluator_artifact_set_digest != expected_evaluator_artifact_set_digest {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit evidence evaluator artifact set digest mismatch"
                .to_owned(),
        ));
    }

    let expected_artifact_bundle_digest =
        hash_bfv_full_bootstrap_circuit_artifact_bundle_digest_material_v1(
            &BfvFullBootstrapCircuitArtifactBundleDigestMaterialV1 {
                version: BFV_FULL_BOOTSTRAP_CIRCUIT_ARTIFACT_BUNDLE_DIGEST_MATERIAL_VERSION_V1,
                artifact_digest_count:
                    BFV_FULL_BOOTSTRAP_CIRCUIT_ARTIFACT_BUNDLE_DIGEST_MATERIAL_ARTIFACT_DIGEST_COUNT_V1,
                coefficient_to_slot_key_digest: evidence.coefficient_to_slot_key_digest,
                slot_to_coefficient_key_digest: evidence.slot_to_coefficient_key_digest,
                blind_rotation_key_digest: evidence.blind_rotation_key_digest,
                sample_extraction_key_digest: evidence.sample_extraction_key_digest,
                accumulator_digest: evidence.accumulator_digest,
                proof_public_input_schema_digest: evidence.proof_public_input_schema_digest,
                arithmetic_air_constraint_system_artifact_digest: evidence
                    .arithmetic_air_constraint_system_artifact_digest,
                prover_key_digest: evidence.prover_key.key_digest,
                verifier_key_digest: evidence.verifier_key.key_digest,
            },
        )?;
    if evidence.artifact_bundle_digest != expected_artifact_bundle_digest {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap release audit evidence artifact bundle digest mismatch".to_owned(),
        ));
    }
    Ok(())
}

fn validate_distinct_bfv_full_bootstrap_release_audit_evidence_digests(
    evidence: &BfvFullBootstrapReleaseAuditEvidenceV1,
) -> Result<(), BfvError> {
    let evidence_digests =
        bfv_full_bootstrap_release_audit_evidence_distinct_digest_entries(evidence);
    for (index, (label, digest)) in evidence_digests.iter().enumerate() {
        if let Some((prior_label, _)) = evidence_digests[..index]
            .iter()
            .find(|(_, prior)| *prior == *digest)
        {
            return Err(BfvError::InvalidParameters(format!(
                "BFV full-bootstrap release audit evidence {label} must be distinct from {prior_label}"
            )));
        }
    }
    Ok(())
}

