/// Validate the proof-facing profile bound by full-bootstrap material.
///
/// This is the verifier admission companion to
/// [`validate_bfv_full_bootstrap_circuit_material_v1`]. Callers provide the
/// expected governed BFV proof public-input schema artifact digest and, once a
/// proof attachment is available, the verifier-key material commitment
/// expected for the proof that will govern this material. The crypto layer then
/// enforces that the full-bootstrap material commits to exactly those
/// proof-facing values.
///
/// # Errors
/// Returns [`BfvError`] when the material is invalid, either expected digest is
/// empty, or the material proof profile does not match the expected schema or
/// verifier-key material commitment.
pub fn validate_bfv_full_bootstrap_material_proof_profile_v1(
    params: &BfvParameters,
    material: &BfvFullBootstrapCircuitMaterialV1,
    expected_public_input_schema_digest: &Hash,
    expected_verifier_key_material_commitment: Option<&Hash>,
) -> Result<(), BfvError> {
    validate_bfv_full_bootstrap_circuit_material_v1(params, material)?;
    validate_nonzero_material_digest(
        "expected BFV full-bootstrap proof public-input schema digest",
        expected_public_input_schema_digest,
    )?;
    validate_no_full_bootstrap_placeholder_material_digest(
        "expected BFV full-bootstrap proof public-input schema digest",
        expected_public_input_schema_digest,
    )?;
    if material.proof_public_input_schema_digest != *expected_public_input_schema_digest {
        return Err(BfvError::InvalidParameters(
            "BFV full-bootstrap proof public-input schema digest does not match expected verifier profile"
                .to_owned(),
        ));
    }
    if let Some(expected_verifier_key_material_commitment) =
        expected_verifier_key_material_commitment
    {
        validate_nonzero_material_digest(
            "expected BFV full-bootstrap verifier-key material commitment",
            expected_verifier_key_material_commitment,
        )?;
        validate_no_full_bootstrap_placeholder_material_digest(
            "expected BFV full-bootstrap verifier-key material commitment",
            expected_verifier_key_material_commitment,
        )?;
        if material.verifier_key_material_commitment != *expected_verifier_key_material_commitment {
            return Err(BfvError::InvalidParameters(
                "BFV full-bootstrap verifier-key material commitment does not match expected verifier profile"
                    .to_owned(),
            ));
        }
    }
    Ok(())
}

/// Refresh a ciphertext with round zero from a public bootstrap key.
///
/// # Errors
/// Returns [`BfvError`] when the input or refresh key does not match the
/// parameter set.
pub fn bootstrap_ciphertext(
    params: &BfvParameters,
    bootstrap_key: &BfvBootstrapKey,
    ciphertext: &BfvCiphertext,
) -> Result<BfvCiphertext, BfvError> {
    bootstrap_ciphertext_round(params, bootstrap_key, ciphertext, 0)
}

/// Refresh a ciphertext with one indexed public bootstrap-key round.
///
/// # Errors
/// Returns [`BfvError`] when the input, refresh key, or round index does not
/// match the parameter set.
pub fn bootstrap_ciphertext_round(
    params: &BfvParameters,
    bootstrap_key: &BfvBootstrapKey,
    ciphertext: &BfvCiphertext,
    round_index: u16,
) -> Result<BfvCiphertext, BfvError> {
    params.validate()?;
    validate_bootstrap_key_refresh_round_index_request(
        bootstrap_key,
        round_index,
        "BFV bootstrap refresh",
    )?;
    validate_bfv_seeded_bootstrap_refresh_round_capacity(
        params,
        bootstrap_key.max_refresh_rounds,
        "BFV bootstrap key",
    )?;
    validate_bootstrap_key_for_refresh_application(params, bootstrap_key)?;
    add_ciphertexts(
        params,
        ciphertext,
        bootstrap_round_refresh(bootstrap_key, round_index)?,
    )
}

/// Refresh a ciphertext with consecutive public bootstrap-key rounds.
///
/// The requested round count is validated against the key before the first
/// refresh is applied, so callers cannot accidentally rely on a partial
/// multi-round refresh when the request exceeds the key capacity.
///
/// # Errors
/// Returns [`BfvError`] when the input, refresh key, or requested round count
/// does not match the parameter set.
pub fn bootstrap_ciphertext_rounds(
    params: &BfvParameters,
    bootstrap_key: &BfvBootstrapKey,
    ciphertext: &BfvCiphertext,
    refresh_rounds: u16,
) -> Result<BfvCiphertext, BfvError> {
    params.validate()?;
    validate_bootstrap_key_refresh_round_count_request(
        bootstrap_key,
        refresh_rounds,
        "BFV bootstrap refresh",
    )?;
    validate_bfv_seeded_bootstrap_refresh_round_capacity(
        params,
        bootstrap_key.max_refresh_rounds,
        "BFV bootstrap key",
    )?;
    validate_bootstrap_key_for_refresh_application(params, bootstrap_key)?;
    let mut refreshed = ciphertext.clone();
    for round_index in 0..refresh_rounds {
        refreshed = add_ciphertexts(
            params,
            &refreshed,
            bootstrap_round_refresh(bootstrap_key, round_index)?,
        )?;
    }
    Ok(refreshed)
}

/// Refresh a rounded BFV ciphertext with round zero from a bounded-noise bootstrap key.
///
/// # Errors
/// Returns [`BfvError`] when the input or refresh key does not match the
/// parameter set.
pub fn bootstrap_ciphertext_bounded_noise(
    params: &BfvParameters,
    bootstrap_key: &BfvBootstrapKey,
    ciphertext: &BfvCiphertext,
) -> Result<BfvCiphertext, BfvError> {
    bootstrap_ciphertext_bounded_noise_round(params, bootstrap_key, ciphertext, 0)
}

/// Refresh a rounded BFV ciphertext with one indexed bounded-noise bootstrap round.
///
/// # Errors
/// Returns [`BfvError`] when the input, refresh key, or round index does not
/// match the parameter set.
pub fn bootstrap_ciphertext_bounded_noise_round(
    params: &BfvParameters,
    bootstrap_key: &BfvBootstrapKey,
    ciphertext: &BfvCiphertext,
    round_index: u16,
) -> Result<BfvCiphertext, BfvError> {
    validate_bootstrap_key_refresh_round_index_request(
        bootstrap_key,
        round_index,
        "BFV bounded-noise bootstrap refresh",
    )?;
    validate_bfv_bounded_noise_bootstrap_refresh_round_capacity(
        params,
        bootstrap_key.max_refresh_rounds,
        "BFV bounded-noise bootstrap key",
    )?;
    validate_bootstrap_key_for_refresh_application(params, bootstrap_key)?;
    add_ciphertexts(
        params,
        ciphertext,
        bootstrap_round_refresh(bootstrap_key, round_index)?,
    )
}

/// Refresh a rounded BFV ciphertext with consecutive bounded-noise bootstrap rounds.
///
/// The requested round count is validated against the key before the first
/// refresh is applied, so callers cannot accidentally rely on a partial
/// multi-round refresh when the request exceeds the key capacity.
///
/// # Errors
/// Returns [`BfvError`] when the input, refresh key, or requested round count
/// does not match the parameter set.
pub fn bootstrap_ciphertext_bounded_noise_rounds(
    params: &BfvParameters,
    bootstrap_key: &BfvBootstrapKey,
    ciphertext: &BfvCiphertext,
    refresh_rounds: u16,
) -> Result<BfvCiphertext, BfvError> {
    validate_bootstrap_key_refresh_round_count_request(
        bootstrap_key,
        refresh_rounds,
        "BFV bounded-noise bootstrap refresh",
    )?;
    validate_bfv_bounded_noise_bootstrap_refresh_round_capacity(
        params,
        bootstrap_key.max_refresh_rounds,
        "BFV bounded-noise bootstrap key",
    )?;
    validate_bootstrap_key_for_refresh_application(params, bootstrap_key)?;
    let mut refreshed = ciphertext.clone();
    for round_index in 0..refresh_rounds {
        refreshed = add_ciphertexts(
            params,
            &refreshed,
            bootstrap_round_refresh(bootstrap_key, round_index)?,
        )?;
    }
    Ok(refreshed)
}

