    #[test]
    fn full_bootstrap_linear_transform_artifacts_are_typed_and_executable() {
        let params = ram_lfe_bfv_parameters_v1();
        let (secret_key, public_key, _relinearization_key) =
            keygen_from_seed(&params, b"bfv-full-bootstrap-linear-keygen").expect("keygen");
        let transform = sample_identity_full_bootstrap_linear_transform(&params);
        validate_bfv_full_bootstrap_linear_transform_v1(&params, &transform)
            .expect("identity transform is valid");
        let artifact = encode_bfv_full_bootstrap_linear_transform_artifact_v1(
            &params,
            1,
            BfvFullBootstrapCircuitArtifactRoleV1::CoefficientToSlotKey,
            &transform,
        )
        .expect("encode linear transform artifact");
        let material = BfvFullBootstrapCircuitMaterialV1 {
            coefficient_to_slot_key_digest: Hash::new(&artifact),
            ..sample_full_bootstrap_circuit_material(&params)
        };
        let decoded = decode_bfv_full_bootstrap_linear_transform_artifact_v1(
            &params,
            &material,
            BfvFullBootstrapCircuitArtifactRoleV1::CoefficientToSlotKey,
            &artifact,
        )
        .expect("decode governed linear transform artifact");
        assert_eq!(decoded, transform);

        let slots = (0..params.degree())
            .map(|slot| u64::try_from((slot * 3 + 11) % 257).expect("slot fits"))
            .collect::<Vec<_>>();
        let packed_plaintext =
            encode_packed_plaintext_slots(&params, &slots).expect("encode packed slots");
        let ciphertext = encrypt_from_seed(
            &params,
            &public_key,
            &packed_plaintext,
            b"bfv-full-bootstrap-linear-transform-input",
        )
        .expect("encrypt packed input");
        let output = apply_bfv_full_bootstrap_linear_transform_registered_rns_exact_v1(
            &params,
            &[],
            &ciphertext,
            &decoded,
        )
        .expect("apply identity linear transform");
        let decrypted = decrypt(&params, &secret_key, &output).expect("decrypt output");
        assert_eq!(
            decode_packed_plaintext_slots(&params, &decrypted).expect("decode output slots"),
            slots,
            "identity full-bootstrap linear transform must preserve packed slots"
        );

        let opaque_payload = sample_full_bootstrap_artifact_payload(
            &params,
            BfvFullBootstrapCircuitArtifactRoleV1::CoefficientToSlotKey,
            b"opaque-coeff-to-slot-payload",
        );
        let opaque_material = BfvFullBootstrapCircuitMaterialV1 {
            coefficient_to_slot_key_digest: Hash::new(&opaque_payload),
            ..sample_full_bootstrap_circuit_material(&params)
        };
        assert_error_contains(
            decode_bfv_full_bootstrap_linear_transform_artifact_v1(
                &params,
                &opaque_material,
                BfvFullBootstrapCircuitArtifactRoleV1::CoefficientToSlotKey,
                &opaque_payload,
            ),
            "linear transform",
            "coefficient-to-slot artifacts must carry typed linear-transform payloads",
        );

        let mut all_zero_diagonal = transform.clone();
        all_zero_diagonal.diagonals[0].plaintext =
            encode_packed_plaintext_slots(&params, &vec![0; params.degree()])
                .expect("encode all-zero diagonal slots");
        assert_error_contains(
            validate_bfv_full_bootstrap_linear_transform_v1(&params, &all_zero_diagonal),
            "all-zero slots",
            "linear-transform diagonals must reject inert all-zero slot masks",
        );
        assert_error_contains(
            encode_bfv_full_bootstrap_linear_transform_artifact_v1(
                &params,
                1,
                BfvFullBootstrapCircuitArtifactRoleV1::CoefficientToSlotKey,
                &all_zero_diagonal,
            ),
            "all-zero slots",
            "linear-transform artifact encoding must reject inert all-zero diagonals",
        );

        let mut duplicate_rotation = transform;
        duplicate_rotation
            .diagonals
            .push(duplicate_rotation.diagonals[0].clone());
        assert_error_contains(
            validate_bfv_full_bootstrap_linear_transform_v1(&params, &duplicate_rotation),
            "duplicates rotation_steps",
            "linear-transform diagonals must have unique rotation metadata",
        );
    }

    #[test]
    fn full_bootstrap_blind_rotation_artifact_is_typed_and_profile_bound() {
        let params = ram_lfe_bfv_parameters_v1();
        let accumulator_artifact = sample_full_bootstrap_accumulator_artifact_payload(&params);
        let accumulator_digest = Hash::new(&accumulator_artifact);
        let key = bfv_full_bootstrap_blind_rotation_key_for_packed_left_rotation_v1(
            &params,
            accumulator_digest,
            1,
        )
        .expect("build blind-rotation key");
        validate_bfv_full_bootstrap_blind_rotation_key_v1(&params, &key)
            .expect("sample blind-rotation key is valid");
        let artifact = encode_bfv_full_bootstrap_blind_rotation_artifact_v1(&params, 1, &key)
            .expect("encode blind-rotation artifact");
        let material = BfvFullBootstrapCircuitMaterialV1 {
            blind_rotation_key_digest: Hash::new(&artifact),
            accumulator_digest,
            ..sample_full_bootstrap_circuit_material(&params)
        };
        let decoded =
            decode_bfv_full_bootstrap_blind_rotation_artifact_v1(&params, &material, &artifact)
                .expect("decode governed blind-rotation artifact");
        assert_eq!(decoded, key);

        let (secret_key, public_key, _relinearization_key) =
            keygen_from_seed(&params, b"bfv-full-bootstrap-blind-rotation-exec-keygen")
                .expect("keygen");
        let slots = (0..params.degree())
            .map(|slot| u64::try_from((slot * 5 + 3) % 257).expect("slot fits"))
            .collect::<Vec<_>>();
        let packed_plaintext =
            encode_packed_plaintext_slots(&params, &slots).expect("encode packed slots");
        let ciphertext = encrypt_from_seed(
            &params,
            &public_key,
            &packed_plaintext,
            b"bfv-full-bootstrap-blind-rotation-exec-input",
        )
        .expect("encrypt packed input");
        let galois_keys = key
            .steps
            .iter()
            .map(|step| {
                galois_key_from_seed(
                    &params,
                    &secret_key,
                    step.automorphism_power,
                    b"bfv-full-bootstrap-blind-rotation-exec-galois",
                )
                .expect("Galois key")
            })
            .collect::<Vec<_>>();
        let rotated = apply_bfv_full_bootstrap_blind_rotation_registered_rns_exact_v1(
            &params,
            &galois_keys,
            &ciphertext,
            &key,
        )
        .expect("apply governed blind rotation");
        let baseline = rotate_packed_ciphertext_slots_left_with_galois_keys_registered_rns_exact(
            &params,
            &galois_keys,
            &ciphertext,
            key.rotation_steps,
        )
        .expect("apply registered packed RotateLeft baseline");
        assert_eq!(rotated, baseline);
        let rotated_plaintext =
            decrypt(&params, &secret_key, &rotated).expect("decrypt blind-rotation output");
        let mut expected_slots = slots;
        expected_slots.rotate_left(usize::try_from(key.rotation_steps).expect("rotation fits"));
        assert_eq!(
            decode_packed_plaintext_slots(&params, &rotated_plaintext)
                .expect("decode blind-rotation output slots"),
            expected_slots
        );
        let input_bound =
            bfv_encrypted_zero_refresh_residual_multiple_bound(&params).expect("input bound");
        let governed_bound = bfv_full_bootstrap_blind_rotation_output_residual_multiple_bound_v1(
            &params,
            &galois_keys,
            &key,
            input_bound,
        )
        .expect("full-bootstrap blind-rotation residual bound");
        let baseline_bound = bfv_packed_rotate_left_output_residual_multiple_bound(
            &params,
            &galois_keys,
            input_bound,
            key.rotation_steps,
        )
        .expect("packed RotateLeft residual bound");
        assert_eq!(governed_bound, baseline_bound);
        validate_ciphertext_exact_residual_multiple_bound(
            &params,
            &secret_key,
            &rotated,
            governed_bound,
            "full-bootstrap blind rotation output",
        )
        .expect("blind-rotation output fits governed residual bound");

        let missing_power = key.steps[0].automorphism_power;
        assert_error_contains(
            apply_bfv_full_bootstrap_blind_rotation_registered_rns_exact_v1(
                &params,
                &galois_keys[1..],
                &ciphertext,
                &key,
            ),
            &format!("automorphism power {missing_power}"),
            "blind rotation must reject missing Galois keys",
        );
        assert_error_contains(
            bfv_full_bootstrap_blind_rotation_output_residual_multiple_bound_v1(
                &params,
                &galois_keys[1..],
                &key,
                input_bound,
            ),
            &format!("automorphism power {missing_power}"),
            "blind-rotation bounds must reject missing Galois keys",
        );

        let (bounded_secret_key, bounded_public_key) = keygen_bounded_noise_from_seed(
            &params,
            b"bfv-full-bootstrap-blind-rotation-bounded-exec-keygen",
        )
        .expect("bounded-noise keygen");
        let bounded_ciphertext = encrypt_bounded_noise_from_seed(
            &params,
            &bounded_public_key,
            &packed_plaintext,
            b"bfv-full-bootstrap-blind-rotation-bounded-exec-input",
        )
        .expect("encrypt bounded packed input");
        let bounded_galois_keys = key
            .steps
            .iter()
            .map(|step| {
                galois_key_bounded_noise_from_seed(
                    &params,
                    &bounded_secret_key,
                    step.automorphism_power,
                    b"bfv-full-bootstrap-blind-rotation-bounded-exec-galois",
                )
                .expect("bounded-noise Galois key")
            })
            .collect::<Vec<_>>();
        let bounded_rotated =
            apply_bfv_full_bootstrap_blind_rotation_bounded_noise_registered_rns_basis_extension_exact_v1(
                &params,
                &bounded_galois_keys,
                &bounded_ciphertext,
                &key,
            )
            .expect("apply governed bounded-noise blind rotation");
        let bounded_baseline =
            rotate_packed_ciphertext_slots_left_with_galois_keys_bounded_noise_registered_rns_basis_extension_exact(
                &params,
                &bounded_galois_keys,
                &bounded_ciphertext,
                key.rotation_steps,
            )
            .expect("apply bounded-noise packed RotateLeft baseline");
        assert_eq!(bounded_rotated, bounded_baseline);
        let bounded_rotated_plaintext =
            decrypt_bounded_noise(&params, &bounded_secret_key, &bounded_rotated)
                .expect("decrypt bounded blind-rotation output");
        assert_eq!(
            decode_packed_plaintext_slots(&params, &bounded_rotated_plaintext)
                .expect("decode bounded blind-rotation output slots"),
            expected_slots
        );
        let input_noise_bound =
            bfv_fresh_bounded_noise_ciphertext_bound(&params).expect("fresh bounded-noise bound");
        let governed_noise_bound = bfv_full_bootstrap_blind_rotation_bounded_noise_output_bound_v1(
            &params,
            &bounded_galois_keys,
            &key,
            input_noise_bound,
        )
        .expect("full-bootstrap bounded-noise blind-rotation bound");
        let baseline_noise_bound = bfv_packed_rotate_left_bounded_noise_output_bound(
            &params,
            &bounded_galois_keys,
            input_noise_bound,
            key.rotation_steps,
        )
        .expect("bounded-noise packed RotateLeft bound");
        assert_eq!(governed_noise_bound, baseline_noise_bound);
        validate_ciphertext_bounded_noise(
            &params,
            &bounded_secret_key,
            &bounded_rotated,
            governed_noise_bound,
            "bounded full-bootstrap blind rotation output",
        )
        .expect("bounded blind-rotation output fits governed noise bound");
        assert_error_contains(
            bfv_full_bootstrap_blind_rotation_bounded_noise_output_bound_v1(
                &params,
                &bounded_galois_keys[1..],
                &key,
                input_noise_bound,
            ),
            &format!("automorphism power {missing_power}"),
            "bounded blind-rotation bounds must reject missing Galois keys",
        );

        let opaque_payload = sample_full_bootstrap_artifact_payload(
            &params,
            BfvFullBootstrapCircuitArtifactRoleV1::BlindRotationKey,
            b"opaque-blind-rotation-payload",
        );
        let opaque_material = BfvFullBootstrapCircuitMaterialV1 {
            blind_rotation_key_digest: Hash::new(&opaque_payload),
            accumulator_digest,
            ..sample_full_bootstrap_circuit_material(&params)
        };
        assert_error_contains(
            decode_bfv_full_bootstrap_blind_rotation_artifact_v1(
                &params,
                &opaque_material,
                &opaque_payload,
            ),
            "blind rotation",
            "blind-rotation artifacts must carry typed blind-rotation payloads",
        );

        let wrong_slot_count = BfvFullBootstrapBlindRotationKeyV1 {
            slot_count: params.polynomial_degree.saturating_sub(1),
            ..key.clone()
        };
        assert_error_contains(
            validate_bfv_full_bootstrap_blind_rotation_key_v1(&params, &wrong_slot_count),
            "slot_count",
            "blind rotation must bind the packed slot count",
        );

        let zero_accumulator_digest = BfvFullBootstrapBlindRotationKeyV1 {
            accumulator_digest: Hash::prehashed([0_u8; Hash::LENGTH]),
            ..key.clone()
        };
        assert_error_contains(
            validate_bfv_full_bootstrap_blind_rotation_key_v1(&params, &zero_accumulator_digest),
            "accumulator digest",
            "blind rotation must reject zero accumulator digests",
        );

        let mut duplicate_power = key.clone();
        duplicate_power.steps.push(duplicate_power.steps[0].clone());
        assert_error_contains(
            validate_bfv_full_bootstrap_blind_rotation_key_v1(&params, &duplicate_power),
            "duplicates automorphism_power",
            "blind rotation must reject duplicate automorphism powers",
        );

        let mut malformed_plaintext = key.clone();
        malformed_plaintext.steps[0].selector_plaintext[0] = params.plaintext_modulus;
        assert_error_contains(
            validate_bfv_full_bootstrap_blind_rotation_key_v1(&params, &malformed_plaintext),
            "plaintext coefficient",
            "blind-rotation selectors must stay inside plaintext modulus",
        );

        let mut non_binary_selector = key.clone();
        non_binary_selector.steps[0].selector_plaintext =
            encode_packed_plaintext_slots(&params, &vec![2; params.degree()])
                .expect("encode non-binary selector slots");
        assert_error_contains(
            validate_bfv_full_bootstrap_blind_rotation_key_v1(&params, &non_binary_selector),
            "binary",
            "blind-rotation selectors must be binary slot masks",
        );

        let mut all_zero_selector = key.clone();
        all_zero_selector.steps[0].selector_plaintext = vec![0; params.degree()];
        assert_error_contains(
            validate_bfv_full_bootstrap_blind_rotation_key_v1(&params, &all_zero_selector),
            "all zero",
            "blind-rotation selectors must reject inert all-zero masks",
        );

        let mismatched_accumulator_digest =
            bfv_full_bootstrap_blind_rotation_key_for_packed_left_rotation_v1(
                &params,
                Hash::new(b"other full-bootstrap accumulator artifact"),
                1,
            )
            .expect("build mismatched blind-rotation key");
        let mismatched_artifact = encode_bfv_full_bootstrap_blind_rotation_artifact_v1(
            &params,
            1,
            &mismatched_accumulator_digest,
        )
        .expect("encode mismatched blind-rotation artifact");
        let mismatched_material = BfvFullBootstrapCircuitMaterialV1 {
            blind_rotation_key_digest: Hash::new(&mismatched_artifact),
            accumulator_digest,
            ..sample_full_bootstrap_circuit_material(&params)
        };
        assert_error_contains(
            decode_bfv_full_bootstrap_blind_rotation_artifact_v1(
                &params,
                &mismatched_material,
                &mismatched_artifact,
            ),
            "accumulator digest",
            "blind rotation must bind the governed accumulator artifact digest",
        );
    }

