    #[test]
    fn galois_keys_reject_noncanonical_powers_and_malformed_entries() {
        let params = params();
        let (secret_key, public_key, _) =
            keygen_from_seed(&params, b"bfv-galois-invalid-keygen").expect("keygen");
        for (power, message) in [(0, "1..16"), (2, "coprime"), (16, "1..16")] {
            let err = galois_key_from_seed(&params, &secret_key, power, b"bfv-galois-invalid")
                .expect_err("invalid Galois powers must be rejected");
            assert!(
                err.to_string().contains(message),
                "expected `{message}` in `{err}`"
            );
        }

        let ciphertext =
            encrypt_from_seed(&params, &public_key, &[1], b"bfv-galois-invalid-ciphertext")
                .expect("encrypt");
        let mut malformed = galois_key_from_seed(&params, &secret_key, 3, b"bfv-galois-malformed")
            .expect("Galois key");
        malformed.entries.pop();
        let err = apply_galois_automorphism_ciphertext(&params, &malformed, &ciphertext)
            .expect_err("malformed Galois key entries must be rejected");
        assert!(err.to_string().contains("Galois key expected"));
    }

    #[test]
    fn galois_key_generation_self_checks_key_switch_residuals() {
        let params = params();
        let (secret_key, _, _) =
            keygen_from_seed(&params, b"bfv-galois-self-check-keygen").expect("keygen");
        let galois_key =
            galois_key_from_seed(&params, &secret_key, 3, b"bfv-galois-self-check-key")
                .expect("generated Galois key self-checks before returning");
        let target_secret =
            apply_galois_automorphism_poly(&params, &secret_key.s, galois_key.automorphism_power)
                .expect("target secret");
        validate_key_switch_entry_residuals(
            &params,
            &secret_key.s,
            &target_secret,
            &galois_key.entries,
            "standalone generated Galois key",
        )
        .expect("generated Galois key residuals match automorphed secret");

        let mut tampered = galois_key;
        tampered.entries[0].b[0] =
            add_mod_u64(tampered.entries[0].b[0], 1, params.ciphertext_modulus);
        let err = validate_key_switch_entry_residuals(
            &params,
            &secret_key.s,
            &target_secret,
            &tampered.entries,
            "standalone generated Galois key",
        )
        .expect_err("tampered generated Galois entries must fail residual validation");
        assert!(
            err.to_string().contains("non-plaintext-multiple"),
            "unexpected error: {err}"
        );
    }

    #[test]
    fn key_switch_primitives_reject_truncated_entries_before_digit_zip() {
        fn malformed_key_with_expected_entry_count(
            params: &BfvParameters,
        ) -> Vec<BfvRelinearizationKeyEntry> {
            let entry_count = params
                .decomposition_digits()
                .expect("test parameters have decomposition digits");
            vec![
                BfvRelinearizationKeyEntry {
                    b: Vec::new(),
                    a: Vec::new(),
                };
                entry_count
            ]
        }

        let params = params();
        let (_, _, relinearization_key) =
            keygen_from_seed(&params, b"bfv-key-switch-truncated-keygen").expect("keygen");
        let mut truncated_entries = relinearization_key.entries.clone();
        truncated_entries.pop().expect("sample key has entries");
        let zero = zero_poly(&params);
        let malformed_poly = Vec::new();
        let malformed_entries = malformed_key_with_expected_entry_count(&params);

        let err = key_switch(&params, &truncated_entries, &zero, &zero, &zero)
            .expect_err("scalar key switching must reject truncated entries before zipping digits");
        assert!(
            err.to_string().contains("key switch key expected"),
            "unexpected error: {err}"
        );
        let err = key_switch(
            &params,
            &malformed_entries,
            &malformed_poly,
            &malformed_poly,
            &malformed_poly,
        )
        .expect_err("scalar key switching must reject malformed entries before components");
        assert!(
            err.to_string().contains("key switch key b[0] length"),
            "unexpected error: {err}"
        );

        let rns_params = rns_exact_params();
        let rns_chain = rns_exact_chain();
        let (_, _, rns_relinearization_key) =
            keygen_from_seed(&rns_params, b"bfv-rns-key-switch-truncated-keygen")
                .expect("RNS keygen");
        let mut rns_truncated_entries = rns_relinearization_key.entries.clone();
        rns_truncated_entries
            .pop()
            .expect("sample RNS key has entries");
        let rns_zero = zero_poly(&rns_params);

        let err = key_switch_rns_exact(
            &rns_params,
            &rns_chain,
            &rns_truncated_entries,
            &rns_zero,
            &rns_zero,
            &rns_zero,
        )
        .expect_err("RNS key switching must reject truncated entries before zipping digits");
        assert!(
            err.to_string()
                .contains("RNS exact key switch key expected"),
            "unexpected error: {err}"
        );
        let rns_malformed_entries = malformed_key_with_expected_entry_count(&rns_params);
        let rns_malformed_poly = Vec::new();
        let err = key_switch_rns_exact(
            &rns_params,
            &rns_chain,
            &rns_malformed_entries,
            &rns_malformed_poly,
            &rns_malformed_poly,
            &rns_malformed_poly,
        )
        .expect_err("RNS key switching must reject malformed entries before components");
        assert!(
            err.to_string()
                .contains("RNS exact key switch key b[0] length"),
            "unexpected error: {err}"
        );

        let bounded_params = bounded_noise_multiply_params();
        let evaluator_chain = bounded_noise_multiply_rns_chain();
        let decomposition_chain = BfvRnsModulusChain {
            moduli: evaluator_chain.moduli[..2].to_vec(),
        };
        let bounded_malformed_entries = malformed_key_with_expected_entry_count(&bounded_params);
        let bounded_malformed_poly = Vec::new();
        let err = key_switch_rns_exact_with_basis_extension(
            &bounded_params,
            &decomposition_chain,
            &evaluator_chain,
            &bounded_malformed_entries,
            &bounded_malformed_poly,
            &bounded_malformed_poly,
            &bounded_malformed_poly,
        )
        .expect_err(
            "basis-extension key switching must reject malformed entries before components",
        );
        assert!(
            err.to_string()
                .contains("RNS basis-extension key switch key b[0] length"),
            "unexpected error: {err}"
        );

        let malformed_digits = [BfvRnsPolynomial {
            residues_by_limb: Vec::new(),
        }];
        let err = key_switch_rns_exact_with_digit_polynomials(
            &rns_params,
            &rns_chain,
            &rns_malformed_entries,
            &rns_malformed_poly,
            &rns_malformed_poly,
            &malformed_digits,
        )
        .expect_err("RNS digit key switching must reject malformed entries before digits");
        assert!(
            err.to_string()
                .contains("RNS exact key switch key b[0] length"),
            "unexpected error: {err}"
        );
    }

    #[test]
    fn multiply_preflights_relinearization_entries_before_ciphertext_shapes() {
        fn assert_error_contains<T>(result: Result<T, BfvError>, expected: &str, context: &str) {
            let Err(err) = result else {
                panic!("{context}");
            };
            assert!(
                err.to_string().contains(expected),
                "expected `{expected}` in `{err}`"
            );
        }

        fn malformed_key_with_expected_entry_count(
            params: &BfvParameters,
        ) -> BfvRelinearizationKey {
            let entry_count = params
                .decomposition_digits()
                .expect("test parameters have decomposition digits");
            BfvRelinearizationKey {
                entries: vec![
                    BfvRelinearizationKeyEntry {
                        b: Vec::new(),
                        a: Vec::new(),
                    };
                    entry_count
                ],
            }
        }

        let params = params();
        let malformed_ciphertext = BfvCiphertext {
            c0: Vec::new(),
            c1: Vec::new(),
        };
        let truncated_relinearization_key = BfvRelinearizationKey {
            entries: Vec::new(),
        };
        let malformed_entry_relinearization_key = malformed_key_with_expected_entry_count(&params);
        let zero_ct = zero_ciphertext(&params);

        assert_error_contains(
            multiply_ciphertexts(
                &params,
                &truncated_relinearization_key,
                &malformed_ciphertext,
                &malformed_ciphertext,
            ),
            "relinearization key expected",
            "exact multiply must reject relinearization-key digit count before ciphertext shape",
        );
        assert_error_contains(
            multiply_ciphertexts(
                &params,
                &malformed_entry_relinearization_key,
                &malformed_ciphertext,
                &malformed_ciphertext,
            ),
            "relinearization key b[0] length",
            "exact multiply must reject relinearization entry polynomials before ciphertext shape",
        );
        assert_error_contains(
            multiply_ciphertexts(
                &params,
                &malformed_entry_relinearization_key,
                &zero_ct,
                &zero_ct,
            ),
            "relinearization key b[0] length",
            "exact multiply must still validate relinearization entry polynomials",
        );

        assert_error_contains(
            multiply_ciphertexts_bounded_noise(
                &params,
                &truncated_relinearization_key,
                &malformed_ciphertext,
                &malformed_ciphertext,
            ),
            "bounded-noise relinearization key expected",
            "bounded multiply must reject relinearization-key digit count before ciphertext shape",
        );
        assert_error_contains(
            multiply_ciphertexts_bounded_noise(
                &params,
                &malformed_entry_relinearization_key,
                &malformed_ciphertext,
                &malformed_ciphertext,
            ),
            "bounded-noise relinearization key b[0] length",
            "bounded multiply must reject relinearization entry polynomials before ciphertext shape",
        );

        let rns_params = rns_exact_params();
        let rns_chain = rns_exact_chain();
        let rns_malformed_ciphertext = BfvCiphertext {
            c0: Vec::new(),
            c1: Vec::new(),
        };
        let rns_zero_ciphertext = zero_ciphertext(&rns_params);
        let rns_truncated_relinearization_key = BfvRelinearizationKey {
            entries: Vec::new(),
        };
        let rns_malformed_entry_relinearization_key =
            malformed_key_with_expected_entry_count(&rns_params);
        assert_error_contains(
            multiply_ciphertexts_rns_exact(
                &rns_params,
                &rns_chain,
                &rns_truncated_relinearization_key,
                &rns_malformed_ciphertext,
                &rns_malformed_ciphertext,
            ),
            "RNS exact relinearization key expected",
            "RNS multiply must reject relinearization-key digit count before ciphertext shape",
        );
        assert_error_contains(
            multiply_ciphertexts_rns_exact(
                &rns_params,
                &rns_chain,
                &rns_malformed_entry_relinearization_key,
                &rns_malformed_ciphertext,
                &rns_malformed_ciphertext,
            ),
            "RNS exact relinearization key b[0] length",
            "RNS multiply must reject relinearization entry polynomials before ciphertext shape",
        );
        assert_error_contains(
            multiply_ciphertexts_rns_exact(
                &rns_params,
                &rns_chain,
                &rns_malformed_entry_relinearization_key,
                &rns_zero_ciphertext,
                &rns_zero_ciphertext,
            ),
            "RNS exact relinearization key b[0] length",
            "RNS multiply must still validate relinearization entry polynomials",
        );

        let bounded_rns_params = bounded_noise_multiply_params();
        let bounded_rns_chain = bounded_noise_multiply_rns_chain();
        let bounded_decomposition_chain = BfvRnsModulusChain {
            moduli: bounded_rns_chain.moduli[..2].to_vec(),
        };
        let bounded_malformed_ciphertext = BfvCiphertext {
            c0: Vec::new(),
            c1: Vec::new(),
        };
        let bounded_truncated_relinearization_key = BfvRelinearizationKey {
            entries: Vec::new(),
        };
        let bounded_malformed_entry_relinearization_key =
            malformed_key_with_expected_entry_count(&bounded_rns_params);
        assert_error_contains(
            multiply_ciphertexts_bounded_noise_rns_exact(
                &bounded_rns_params,
                &bounded_rns_chain,
                &bounded_truncated_relinearization_key,
                &bounded_malformed_ciphertext,
                &bounded_malformed_ciphertext,
            ),
            "bounded-noise RNS relinearization key expected",
            "bounded RNS multiply must reject relinearization-key digit count before ciphertext shape",
        );
        assert_error_contains(
            multiply_ciphertexts_bounded_noise_rns_exact(
                &bounded_rns_params,
                &bounded_rns_chain,
                &bounded_malformed_entry_relinearization_key,
                &bounded_malformed_ciphertext,
                &bounded_malformed_ciphertext,
            ),
            "bounded-noise RNS relinearization key b[0] length",
            "bounded RNS multiply must reject relinearization entry polynomials before ciphertext shape",
        );
        assert_error_contains(
            multiply_ciphertexts_bounded_noise_rns_basis_extension_exact(
                &bounded_rns_params,
                &bounded_decomposition_chain,
                &bounded_rns_chain,
                &bounded_truncated_relinearization_key,
                &bounded_malformed_ciphertext,
                &bounded_malformed_ciphertext,
            ),
            "bounded-noise basis-extension RNS relinearization key expected",
            "bounded basis-extension multiply must reject digit count before ciphertext shape",
        );
        assert_error_contains(
            multiply_ciphertexts_bounded_noise_rns_basis_extension_exact(
                &bounded_rns_params,
                &bounded_decomposition_chain,
                &bounded_rns_chain,
                &bounded_malformed_entry_relinearization_key,
                &bounded_malformed_ciphertext,
                &bounded_malformed_ciphertext,
            ),
            "bounded-noise basis-extension RNS relinearization key b[0] length",
            "bounded basis-extension multiply must reject entry polynomials before ciphertext shape",
        );
        let non_prefix_scale_round_source_chain = BfvRnsModulusChain {
            moduli: vec![
                bounded_rns_chain.moduli[0],
                bounded_rns_chain.moduli[1],
                4_292_805_217,
            ],
        };
        validate_rns_centered_scale_round_source_chain(
            &bounded_rns_params,
            &non_prefix_scale_round_source_chain,
            "test non-prefix centered scale-round source",
        )
        .expect("non-prefix source chain is structurally valid and covers scale-round products");
        assert!(
            !bounded_rns_chain
                .moduli
                .as_slice()
                .starts_with(non_prefix_scale_round_source_chain.moduli.as_slice()),
            "test source chain must retarget the evaluator chain"
        );
        assert_error_contains(
            multiply_ciphertexts_bounded_noise_rns_basis_extension_with_scale_round_source_exact(
                &bounded_rns_params,
                &non_prefix_scale_round_source_chain,
                &bounded_decomposition_chain,
                &bounded_rns_chain,
                &bounded_malformed_entry_relinearization_key,
                &bounded_malformed_ciphertext,
                &bounded_malformed_ciphertext,
            ),
            "source chain must be a prefix of the evaluator chain",
            "bounded basis-extension multiply must reject scale-round source retargets before payload shapes",
        );

        let registered_params = ram_lfe_bfv_parameters_v1();
        let registered_malformed_entry_relinearization_key =
            malformed_key_with_expected_entry_count(&registered_params);
        assert_error_contains(
            multiply_ciphertexts_registered_rns_exact(
                &registered_params,
                &registered_malformed_entry_relinearization_key,
                &malformed_ciphertext,
                &malformed_ciphertext,
            ),
            "RNS exact relinearization key b[0] length",
            "registered RNS multiply must reject entry polynomials before ciphertext shape",
        );
        assert_error_contains(
            multiply_ciphertexts_bounded_noise_registered_rns_exact(
                &registered_params,
                &registered_malformed_entry_relinearization_key,
                &malformed_ciphertext,
                &malformed_ciphertext,
            ),
            "bounded-noise basis-extension RNS relinearization key b[0] length",
            "registered bounded RNS compatibility multiply must reject entry polynomials before ciphertext shape",
        );
        assert_error_contains(
            multiply_ciphertexts_bounded_noise_registered_rns_basis_extension_exact(
                &registered_params,
                &registered_malformed_entry_relinearization_key,
                &malformed_ciphertext,
                &malformed_ciphertext,
            ),
            "bounded-noise basis-extension RNS relinearization key b[0] length",
            "registered bounded basis-extension multiply must reject entry polynomials before ciphertext shape",
        );
    }

    #[test]
    fn rns_key_switch_rejects_too_narrow_chain_before_key_material() {
        let rns_params = rns_exact_params();
        let (_, _, rns_relinearization_key) =
            keygen_from_seed(&rns_params, b"bfv-rns-key-switch-chain-preflight-keygen")
                .expect("RNS keygen");
        let mut truncated_entries = rns_relinearization_key.entries.clone();
        truncated_entries.pop().expect("sample RNS key has entries");
        let rns_zero = zero_poly(&rns_params);
        let addition_only_chain = BfvRnsModulusChain {
            moduli: vec![73, 89],
        };
        addition_only_chain
            .validate_exact_ciphertext_modulus_addition_coverage(&rns_params)
            .expect("chain covers exact addition");
        addition_only_chain
            .validate_exact_ciphertext_modulus_negacyclic_product_coverage(&rns_params)
            .expect_err("chain remains too narrow for exact multiplication");

        let err = key_switch_rns_exact(
            &rns_params,
            &addition_only_chain,
            &truncated_entries,
            &rns_zero,
            &rns_zero,
            &rns_zero,
        )
        .expect_err("RNS key switching must preflight exact chain coverage");
        assert!(
            err.to_string().contains("negacyclic product bound"),
            "unexpected error: {err}"
        );
    }

    #[test]
    fn rns_exact_public_entrypoints_preflight_chain_before_late_operation_errors() {
        let rns_params = rns_exact_params();
        let addition_too_narrow_chain = BfvRnsModulusChain { moduli: vec![73] };
        addition_too_narrow_chain
            .validate_for_parameters(&rns_params)
            .expect("single-limb chain is structurally valid for the small profile");
        addition_too_narrow_chain
            .validate_exact_ciphertext_modulus_addition_coverage(&rns_params)
            .expect_err("single-limb chain is too narrow for exact addition");

        let product_too_narrow_chain = BfvRnsModulusChain {
            moduli: vec![73, 89],
        };
        product_too_narrow_chain
            .validate_exact_ciphertext_modulus_addition_coverage(&rns_params)
            .expect("two-limb chain covers exact addition");
        product_too_narrow_chain
            .validate_exact_ciphertext_modulus_negacyclic_product_coverage(&rns_params)
            .expect_err("two-limb chain is too narrow for exact multiplication");

        let (secret_key, public_key, relinearization_key) =
            keygen_from_seed(&rns_params, b"bfv-rns-public-preflight-keygen").expect("keygen");
        let ciphertext = encrypt_from_seed(
            &rns_params,
            &public_key,
            &[1, 2],
            b"bfv-rns-public-preflight-ciphertext",
        )
        .expect("encrypt");
        let rhs = encrypt_from_seed(
            &rns_params,
            &public_key,
            &[3, 4],
            b"bfv-rns-public-preflight-rhs",
        )
        .expect("encrypt rhs");
        let bootstrap_key = bootstrap_key_with_max_refresh_rounds_from_seed(
            &rns_params,
            &public_key,
            "rns-public-preflight",
            1,
            b"bfv-rns-public-preflight-bootstrap",
        )
        .expect("bootstrap key");
        let full_cycle_rotation_key = rotation_key_from_seed(
            &rns_params,
            &public_key,
            2,
            b"bfv-rns-public-preflight-rotation",
        )
        .expect("rotation key");
        let galois_key = galois_key_from_seed(
            &rns_params,
            &secret_key,
            3,
            b"bfv-rns-public-preflight-galois",
        )
        .expect("Galois key");

        let err = bootstrap_ciphertext_rns_exact_round(
            &rns_params,
            &addition_too_narrow_chain,
            &bootstrap_key,
            &ciphertext,
            99,
        )
        .expect_err("bootstrap refresh must preflight the RNS addition chain");
        assert!(
            err.to_string().contains("addition bound"),
            "unexpected error: {err}"
        );

        let err = rotate_ciphertext_slots_left_rns_exact(
            &rns_params,
            &addition_too_narrow_chain,
            &full_cycle_rotation_key,
            &[ciphertext.clone(), rhs.clone()],
        )
        .expect_err("outer-slot rotation must preflight the RNS addition chain");
        assert!(
            err.to_string().contains("addition bound"),
            "unexpected error: {err}"
        );

        let err = multiply_ciphertexts_rns_exact(
            &rns_params,
            &product_too_narrow_chain,
            &relinearization_key,
            &ciphertext,
            &rhs,
        )
        .expect_err("ciphertext multiplication must preflight the full exact RNS chain");
        assert!(
            err.to_string().contains("negacyclic product bound"),
            "unexpected error: {err}"
        );

        let err = multiply_plaintext_polynomial_rns_exact(
            &rns_params,
            &product_too_narrow_chain,
            &ciphertext,
            &[1, 0],
        )
        .expect_err("plaintext-polynomial mask must preflight the full exact RNS chain");
        assert!(
            err.to_string().contains("negacyclic product bound"),
            "unexpected error: {err}"
        );

        let err = apply_galois_automorphism_ciphertext_rns_exact(
            &rns_params,
            &product_too_narrow_chain,
            &galois_key,
            &ciphertext,
        )
        .expect_err("Galois key switching must preflight the full exact RNS chain");
        assert!(
            err.to_string().contains("negacyclic product bound"),
            "unexpected error: {err}"
        );

        let err = rotate_packed_ciphertext_slots_left_with_galois_keys_rns_exact(
            &rns_params,
            &product_too_narrow_chain,
            &[],
            &ciphertext,
            0,
        )
        .expect_err("packed rotation must preflight the full exact RNS chain");
        assert!(
            err.to_string().contains("negacyclic product bound"),
            "unexpected error: {err}"
        );
    }

    #[test]
    fn bounded_noise_basis_extension_public_entrypoints_preflight_corridors_before_late_errors() {
        let params = ram_lfe_bfv_parameters_v1();
        let malformed_ciphertext = BfvCiphertext {
            c0: Vec::new(),
            c1: Vec::new(),
        };
        let malformed_relinearization_key = BfvRelinearizationKey {
            entries: Vec::new(),
        };
        let malformed_galois_key = BfvGaloisKey {
            automorphism_power: 3,
            entries: Vec::new(),
        };
        validate_galois_key_metadata(&params, &malformed_galois_key)
            .expect("fixture keeps public Galois metadata valid");
        let malformed_rotation_key = BfvRotationKey {
            rotation_steps: 1,
            zero_refresh: malformed_ciphertext.clone(),
        };

        let evaluator_chain =
            registered_bfv_rns_modulus_chain(&params).expect("registered evaluator chain");
        let addition_too_narrow_chain = BfvRnsModulusChain {
            moduli: vec![RAM_LFE_BFV_RNS_MODULI_V1[0]],
        };
        let err = multiply_ciphertexts_bounded_noise_rns_basis_extension_exact(
            &params,
            &addition_too_narrow_chain,
            &addition_too_narrow_chain,
            &malformed_relinearization_key,
            &malformed_ciphertext,
            &malformed_ciphertext,
        )
        .expect_err("basis-extension multiply must preflight evaluator-chain coverage");
        assert!(
            err.to_string().contains("ciphertext modulus"),
            "unexpected error: {err}"
        );

        let non_prefix_decomposition_chain = BfvRnsModulusChain {
            moduli: evaluator_chain.moduli[4..].to_vec(),
        };
        validate_rns_key_switch_decomposition_chain(
            &params,
            &non_prefix_decomposition_chain,
            "test non-prefix decomposition",
        )
        .expect("suffix decomposition chain is valid but not the evaluator prefix");

        let err = multiply_ciphertexts_bounded_noise_rns_basis_extension_exact(
            &params,
            &non_prefix_decomposition_chain,
            &evaluator_chain,
            &malformed_relinearization_key,
            &malformed_ciphertext,
            &malformed_ciphertext,
        )
        .expect_err("basis-extension multiply must reject non-prefix decomposition");
        assert!(
            err.to_string().contains("prefix of the evaluator chain"),
            "unexpected error: {err}"
        );

        let err = apply_galois_automorphism_ciphertext_bounded_noise_rns_basis_extension_exact(
            &params,
            &non_prefix_decomposition_chain,
            &evaluator_chain,
            &malformed_galois_key,
            &malformed_ciphertext,
        )
        .expect_err("basis-extension Galois switch must reject non-prefix decomposition");
        assert!(
            err.to_string().contains("prefix of the evaluator chain"),
            "unexpected error: {err}"
        );

        let err = rotate_ciphertext_slots_left_bounded_noise_rns_basis_extension_exact(
            &params,
            &non_prefix_decomposition_chain,
            &evaluator_chain,
            &malformed_rotation_key,
            &[malformed_ciphertext.clone(), malformed_ciphertext.clone()],
        )
        .expect_err("basis-extension outer rotation must reject non-prefix decomposition");
        assert!(
            err.to_string().contains("prefix of the evaluator chain"),
            "unexpected error: {err}"
        );

        let err = bfv_rotate_slots_left_bounded_noise_rns_basis_extension_output_bounds(
            &params,
            &non_prefix_decomposition_chain,
            &evaluator_chain,
            &malformed_rotation_key,
            &[0, 0],
        )
        .expect_err("basis-extension outer rotation bounds must reject non-prefix decomposition");
        assert!(
            err.to_string().contains("prefix of the evaluator chain"),
            "unexpected error: {err}"
        );

        let err =
            rotate_packed_ciphertext_slots_left_with_galois_keys_bounded_noise_rns_basis_extension_exact(
                &params,
                &non_prefix_decomposition_chain,
                &evaluator_chain,
                std::slice::from_ref(&malformed_galois_key),
                &malformed_ciphertext,
                1,
            )
            .expect_err("basis-extension packed rotation must reject non-prefix decomposition");
        assert!(
            err.to_string().contains("prefix of the evaluator chain"),
            "unexpected error: {err}"
        );
    }

    #[test]
    fn shared_key_validators_reject_malformed_parameters_first() {
        let material = evaluation_key_adversarial_material();
        let mut invalid_params = material.params;
        invalid_params.decomposition_base_log = 0;
        let bootstrap_key = bootstrap_key_with_rounds(
            "bootstrap-refresh-key",
            BFV_BOOTSTRAP_KEY_DEFAULT_MAX_REFRESH_ROUNDS,
            &material.zero_refresh,
            vec![material.zero_refresh.clone()],
        );

        assert_malformed_parameter_rejection(
            validate_secret_key(&invalid_params, &material.secret_key),
            "secret-key validation must reject malformed parameters",
        );
        assert_malformed_parameter_rejection(
            validate_public_key(&invalid_params, &material.public_key),
            "public-key validation must reject malformed parameters",
        );
        assert_malformed_parameter_rejection(
            validate_rotation_key(&invalid_params, &material.rotation_key),
            "rotation-key validation must reject malformed parameters",
        );
        assert_malformed_parameter_rejection(
            validate_relinearization_key(&invalid_params, &material.relinearization_key),
            "relinearization-key validation must reject malformed parameters",
        );
        assert_malformed_parameter_rejection(
            validate_galois_key(&invalid_params, &material.galois_key),
            "Galois-key validation must reject malformed parameters",
        );
        assert_malformed_parameter_rejection(
            validate_key_switch_entries(
                &invalid_params,
                &material.relinearization_key.entries,
                "direct key-switch entries",
            ),
            "key-switch entry validation must reject malformed parameters",
        );
        assert_malformed_parameter_rejection(
            validate_bootstrap_key(&invalid_params, &bootstrap_key),
            "bootstrap-key validation must reject malformed parameters",
        );
    }

