    #[test]
    fn evaluation_key_bundle_digest_rejects_inert_refresh_material() {
        let material = evaluation_key_adversarial_material();
        let all_zero_refresh = BfvCiphertext {
            c0: zero_poly(&material.params),
            c1: zero_poly(&material.params),
        };
        let all_zero_rotation = BfvEvaluationKeyBundle {
            relinearization_key: material.relinearization_key.clone(),
            rotation_keys: vec![BfvRotationKey {
                rotation_steps: material.rotation_key.rotation_steps,
                zero_refresh: all_zero_refresh.clone(),
            }],
            galois_keys: Vec::new(),
            bootstrap_key: None,
        };
        all_zero_rotation.validate(&material.params).expect(
            "shape validation remains available for owner diagnostics over all-zero refresh masks",
        );
        assert_error_contains(
            all_zero_rotation.digest(&material.params),
            "all-zero refresh ciphertext",
            "evaluation-key bundle digesting must reject inert all-zero rotation refresh masks",
        );

        let all_zero_bootstrap_descriptor = BfvEvaluationKeyBundle {
            relinearization_key: material.relinearization_key.clone(),
            rotation_keys: Vec::new(),
            galois_keys: Vec::new(),
            bootstrap_key: Some(bootstrap_key_with_rounds(
                "bootstrap-refresh-key",
                1,
                &all_zero_refresh,
                vec![all_zero_refresh.clone()],
            )),
        };
        all_zero_bootstrap_descriptor.validate(&material.params).expect(
            "shape validation remains available for owner diagnostics over all-zero bootstrap descriptors",
        );
        assert_error_contains(
            all_zero_bootstrap_descriptor.digest(&material.params),
            "all-zero refresh ciphertext",
            "evaluation-key bundle digesting must reject inert all-zero bootstrap zero_refresh descriptors",
        );

        let all_zero_bootstrap_round = BfvEvaluationKeyBundle {
            relinearization_key: material.relinearization_key,
            rotation_keys: Vec::new(),
            galois_keys: Vec::new(),
            bootstrap_key: Some(bootstrap_key_with_rounds(
                "bootstrap-refresh-key",
                2,
                &material.zero_refresh,
                vec![material.zero_refresh.clone(), all_zero_refresh],
            )),
        };
        all_zero_bootstrap_round.validate(&material.params).expect(
            "shape validation remains available for owner diagnostics over all-zero bootstrap rounds",
        );
        assert_error_contains(
            all_zero_bootstrap_round.digest(&material.params),
            "all-zero refresh ciphertext",
            "evaluation-key bundle digesting must reject inert all-zero bootstrap round refresh masks",
        );
    }

    #[test]
    fn evaluation_key_bundle_rejects_adversarial_bootstrap_key_ids() {
        let material = evaluation_key_adversarial_material();
        let blank_bootstrap_key = BfvEvaluationKeyBundle {
            relinearization_key: material.relinearization_key.clone(),
            rotation_keys: Vec::new(),
            galois_keys: Vec::new(),
            bootstrap_key: Some(bootstrap_key_with_rounds(
                "   ",
                BFV_BOOTSTRAP_KEY_DEFAULT_MAX_REFRESH_ROUNDS,
                &material.zero_refresh,
                vec![material.zero_refresh.clone()],
            )),
        };
        assert_evaluation_key_bundle_error_contains(
            &material.params,
            &blank_bootstrap_key,
            "bootstrap key id",
            "blank bootstrap key ids must be rejected",
        );

        let placeholder_bootstrap_key = BfvEvaluationKeyBundle {
            relinearization_key: material.relinearization_key.clone(),
            rotation_keys: Vec::new(),
            galois_keys: Vec::new(),
            bootstrap_key: Some(bootstrap_key_with_rounds(
                "replace_before_production",
                BFV_BOOTSTRAP_KEY_DEFAULT_MAX_REFRESH_ROUNDS,
                &material.zero_refresh,
                vec![material.zero_refresh.clone()],
            )),
        };
        assert_evaluation_key_bundle_error_contains(
            &material.params,
            &placeholder_bootstrap_key,
            "placeholder text",
            "placeholder bootstrap key ids must be rejected",
        );

        let binary_decorated_placeholder_bootstrap_key = BfvEvaluationKeyBundle {
            relinearization_key: material.relinearization_key.clone(),
            rotation_keys: Vec::new(),
            galois_keys: Vec::new(),
            bootstrap_key: Some(bootstrap_key_with_rounds(
                "\0replace_before_production\0",
                BFV_BOOTSTRAP_KEY_DEFAULT_MAX_REFRESH_ROUNDS,
                &material.zero_refresh,
                vec![material.zero_refresh.clone()],
            )),
        };
        assert_evaluation_key_bundle_error_contains(
            &material.params,
            &binary_decorated_placeholder_bootstrap_key,
            "placeholder text",
            "binary-decorated placeholder bootstrap key ids must be rejected",
        );

        let padded_bootstrap_key = BfvEvaluationKeyBundle {
            relinearization_key: material.relinearization_key.clone(),
            rotation_keys: Vec::new(),
            galois_keys: Vec::new(),
            bootstrap_key: Some(bootstrap_key_with_rounds(
                " bootstrap-refresh-key",
                BFV_BOOTSTRAP_KEY_DEFAULT_MAX_REFRESH_ROUNDS,
                &material.zero_refresh,
                vec![material.zero_refresh.clone()],
            )),
        };
        let err = padded_bootstrap_key
            .digest(&material.params)
            .expect_err("padded bootstrap key ids must not receive digests");
        assert!(err.to_string().contains("canonical"));

        let control_bootstrap_key = bootstrap_key_with_rounds(
            "bootstrap\nkey",
            BFV_BOOTSTRAP_KEY_DEFAULT_MAX_REFRESH_ROUNDS,
            &material.zero_refresh,
            vec![material.zero_refresh.clone()],
        );
        let err = bootstrap_ciphertext(
            &material.params,
            &control_bootstrap_key,
            &material.zero_refresh,
        )
        .expect_err("control bytes in bootstrap key ids must be rejected");
        assert!(err.to_string().contains("ASCII alphanumeric"));

        let delimiter_bootstrap_key = bootstrap_key_with_rounds(
            "bootstrap/key",
            BFV_BOOTSTRAP_KEY_DEFAULT_MAX_REFRESH_ROUNDS,
            &material.zero_refresh,
            vec![material.zero_refresh.clone()],
        );
        let err = bootstrap_ciphertext(
            &material.params,
            &delimiter_bootstrap_key,
            &material.zero_refresh,
        )
        .expect_err("delimiter-shaped bootstrap key ids must be rejected");
        assert!(err.to_string().contains("ASCII alphanumeric"));

        let err = bootstrap_key_from_seed(
            &material.params,
            &material.public_key,
            "a".repeat(BFV_BOOTSTRAP_KEY_ID_MAX_BYTES + 1),
            b"bfv-oversized-bootstrap-key-id",
        )
        .expect_err("oversized bootstrap key ids must be rejected");
        assert!(err.to_string().contains("maximum supported length"));
    }

    #[test]
    fn evaluation_key_bundle_rejects_adversarial_bootstrap_round_metadata() {
        let material = evaluation_key_adversarial_material();
        let zero_round_key = BfvEvaluationKeyBundle {
            relinearization_key: material.relinearization_key.clone(),
            rotation_keys: Vec::new(),
            galois_keys: Vec::new(),
            bootstrap_key: Some(bootstrap_key_with_rounds(
                "bootstrap-refresh-key",
                0,
                &material.zero_refresh,
                Vec::new(),
            )),
        };
        assert_evaluation_key_bundle_error_contains(
            &material.params,
            &zero_round_key,
            "max_refresh_rounds",
            "zero bootstrap refresh-round capacity must be rejected",
        );

        let err = bootstrap_key_with_max_refresh_rounds_from_seed(
            &material.params,
            &material.public_key,
            "bootstrap-refresh-key",
            0,
            b"bfv-zero-bootstrap-refresh-rounds",
        )
        .expect_err("zero bootstrap refresh-round capacity must be rejected");
        assert!(err.to_string().contains("greater than zero"));

        let err = bootstrap_key_with_max_refresh_rounds_from_seed(
            &material.params,
            &material.public_key,
            "bootstrap-refresh-key",
            BFV_BOOTSTRAP_KEY_MAX_REFRESH_ROUNDS + 1,
            b"bfv-oversized-bootstrap-refresh-rounds",
        )
        .expect_err("oversized bootstrap refresh-round capacity must be rejected");
        assert!(err.to_string().contains("supported limit"));

        let missing_round_refresh = BfvEvaluationKeyBundle {
            relinearization_key: material.relinearization_key.clone(),
            rotation_keys: Vec::new(),
            galois_keys: Vec::new(),
            bootstrap_key: Some(bootstrap_key_with_rounds(
                "bootstrap-refresh-key",
                2,
                &material.zero_refresh,
                vec![material.zero_refresh.clone()],
            )),
        };
        assert_evaluation_key_bundle_error_contains(
            &material.params,
            &missing_round_refresh,
            "round refresh ciphertexts",
            "missing per-round bootstrap refresh material must be rejected",
        );

        let mut malformed_zero_refresh = material.zero_refresh.clone();
        malformed_zero_refresh.c0.pop();
        let malformed_missing_round_refresh = BfvEvaluationKeyBundle {
            relinearization_key: material.relinearization_key.clone(),
            rotation_keys: Vec::new(),
            galois_keys: Vec::new(),
            bootstrap_key: Some(bootstrap_key_with_rounds(
                "bootstrap-refresh-key",
                2,
                &malformed_zero_refresh,
                vec![malformed_zero_refresh.clone()],
            )),
        };
        assert_evaluation_key_bundle_error_contains(
            &material.params,
            &malformed_missing_round_refresh,
            "round refresh ciphertexts",
            "bootstrap round-count metadata must be rejected before malformed refresh shapes",
        );

        let duplicate_round_refresh = BfvEvaluationKeyBundle {
            relinearization_key: material.relinearization_key.clone(),
            rotation_keys: Vec::new(),
            galois_keys: Vec::new(),
            bootstrap_key: Some(bootstrap_key_with_rounds(
                "bootstrap-refresh-key",
                2,
                &material.zero_refresh,
                vec![material.zero_refresh.clone(), material.zero_refresh.clone()],
            )),
        };
        assert_evaluation_key_bundle_error_contains(
            &material.params,
            &duplicate_round_refresh,
            "duplicate round refresh",
            "duplicate per-round bootstrap refresh material must be rejected",
        );
    }

